window.__D("text/maamarei-admur-hazaken/c013",{"p":[[2101000242,"ופחד יצחק היו לי, שהוא<sup data-n=\"1487\">63</sup> בחי' קו האמצעי הנק' בריח התיכון כו' שכלול מב' הקוין ימין ושמאל, ולכך<sup data-n=\"1488\">64</sup> נק' בחיר שבאבות. והענין<sup data-n=\"1489\">65</sup> הוא כמ\"ש והאכלתיך<sup data-n=\"1490\">66</sup> נחלת יעקב אביך דוקא שנק'<sup data-n=\"1491\">67</sup> נחלה בלי מצרים כמ\"ש ופרצת ימה וקדמה וצפונה וכו', פי' ופרצת לשון פרצה כמו המקום שאינו מוגבל בגדר מחיצות מכל צד נק' מקום פרוץ לגמרי מכל צדדיו דהיינו שאין לשטח שלו הגבלה כלל לכל צד מצדדיו, אם לצד הימין מתפשט עד אין שיעור וגבול כי אין לו גדר ומחיצה להגבילו, וכן לצד השמאל מתפשט בלי שיעור, וכן למזרח ולמערב אין לו גדרים להגבילם, ונק' פרצה לכל צד. וכך ופרצת ימה למערב בהתפשטו' לאין שיעור וכן לקדמה ולצפונה כו', והוא הנק' נחלה בלי מצרים המגבילים שתתפשט לצדדיו בלי שיעור כו'. וככה יובן למעלה בבחי' נחלה דיעקב שנק' בריח התיכון, דגם שכלול מב' הקוין ימין ושמאל אבל אין בו בחי' מיצר לא לימין ולא לשמאל, שבחי' ימין ושמאל הכלולים בו מתפשטי' לאין שיעור, וכן למזרח ולמערב שנק' ראש וסוף וכמ\"ש אחור<sup data-n=\"1492\">68</sup> וקדם שהמזרח נק' קדם כו'. וז\"ש אשר<sup data-n=\"1493\">69</sup> נשבעת לאבותינו מימי קדם, כי בחי' קו האמצעי דיעקב עולה עד בחי' הכתר עליון שלמעלה מבחי' התחלקות הקוין במדה, וע\"כ בחי' המדות דשם נק' י\"ג מדה\"ר שהן בלי גבול כלל, וע\"כ נק' ארך<sup data-n=\"1494\">70</sup> אפים ורב חסד כו' מאריך אף לרשעי' ג\"כ להיות נושא עון וכו', כי לעוצם בחי' הרוממו' כולא<sup data-n=\"1495\">71</sup> קמי' כלא כו' ונמשך ר\"ר גם על העולמות היותר עליונים כמו על התחתוני' בהשוואה א' כו'. ובחי' מדתו של יעקב שנק' רחמים שכולל ב' המדות חו\"ג מגיע לבחי' הרחמים הרבים העליונים שאינן בגבול ומדה כלל ע\"כ נאמר בו ופרצת ימה וקדמה, שנמשך למעלה עד אין קץ ולמטה עד אין תכלית ולימין ושמאל בלי שיעור ונק' נחלה בלי מצרים כלל, ולכך אמר והאכלתיך נחלת יעקב אביך דוקא, וד\"ל.\n<b>וזהו</b> תתן אמת ליעקב דוקא פי' אמ\"ת אלף<sup data-n=\"1496\">72</sup> הוא אלופו ש\"ע שלמעלה מכל העולמות שנק'<sup data-n=\"1497\">73</sup> בחי' פלא עליון בהיפוך אותיות, והוא בחי' פנימי' הכתר ששם אא\"ס עצמו בבחי' העלם העצמו' כנ\"ל. ושיתחבר אלף זה למטה מטה עד תי\"ו<sup data-n=\"1498\">74</sup> שהוא בחי' מל' סופא דכל דרגין היינו ע\"י מדתו של יעקב דוקא מדת הרחמים, לפי שהוא בריח התיכון המבריח מן הקצה העליון לקצה התחתון מטעם",[["1487","63","<b>שהוא בחי' קו האמצעי הנק' בריח התיכון</b>: ראה זח\"א א, ב. רנז, א. זח\"ב קעה, ב. ועוד. וראה אוה\"ת ויחי שצה, א."],["1488","64","<b>ולכך נק' בחיר שבאבות</b>: שער הפסוקים תולדות כז, כה. וראה ג\"כ ב\"ר פע\"ו, א. זח\"א קיט, ב. קמז, ב."],["1489","65","<b>והענין</b>: מכאן ואילך הוא באוה\"ת שם בשינויים קלים."],["1490","66","<b>והאכלתיך נחלת יעקב אביך</b>: ישעי' נח, יד."],["1491","67","<b>שנק' נחלה בלי מצרים. . . ופרצת</b>: שבת קיח, א ואילך. בראשית כח, יד."],["1492","68","<b>אחור וקדם</b>: תהלים קלט, ה."],["1493","69","<b>אשר נשבעת לאבותינו מימי קדם</b>: מיכה ז, כ."],["1494","70","<b>ארך אפים ורב חסד</b>: שמות לד, ו."],["1495","71","<b>כולא קמי' כלא</b>: זח\"א יא, ב."],["1496","72","<b>אלף הוא אלופו של עולם</b>: ראה ב\"י או\"ח סי' ס\"א בשם הסמ\"ק."],["1497","73","<b>שנק' בחי' פלא עליון</b>: ת\"ז ת\"ע (קלה, א). וראה תו\"א מקץ לא, ד. ביאוה\"ז להצ\"צ ע' תקכז ואילך."],["1498","74","<b>תי\"ו שהוא בחי' מל'</b>: ראה מאו\"א ת, א."]]],[2101000243,"הנ\"ל וד\"ל. אך במה מעוררי' בחי' ר\"ר הנ\"ל ע\"י מדתו של יעקב שהוא הרחמים, הנה הוא ע\"י הבכי' דמים<sup data-n=\"1499\">75</sup> תחתוני' בוכים אנן בעינן למהוי קדם מלכא, פי' שבבכי' זאת מעוררי' רחמים על עוצם ריחוקם מאחד כמשל בן המלך שצועק אל אביו מתוך עומק בור השבי' בבכיות גדולות לעורר רחמי האב להעלותו משם כו', כך בחי' הניצוצות שנפלו בשאול צלמות בחושך החומרי דעוה\"ז השפל נק' מים תחתוני' בוכים כו' שצועקין לעלות וליכלל באחד ונק' מי בוכים כידוע, ואז דוקא מעוררי' לר\"ר העליוני'. משא\"כ כשהבן בריחוק לגמרי ואין קולו מגיע אל אזני אביו שאינו מעורר רחמי האב כלל כו'. אמנם אחר הרחמנות נמשך ג\"כ בחי' שמחה עד\"מ ביציאת הבן מבית השביה שישמחו האב והבן יחד מאד מאד. וז\"ש רננו<sup data-n=\"1500\">76</sup> צדיקים בה', רינה זו היא שמחה שלאחר הבכי' מן הריחוק עד\"מ ב' אוהבים מופלגים שרואים זא\"ז אחר ריחוקם זה כמה או אוהב דבק מאח שנפל בצרה וניצול שישמח בו מאד וכיוצא. וז\"ש רננו צדיקים, ב' צדיקים צדיק עליון שהוא אא\"ס ב\"ה, וצדיק תחתון שהן כנ\"י בהעלאות הנשמות מחושך הגס אחר הבכי' כנ\"ל שנמשך רינה ושמחה בה' וישראל יחד. ומש\"כ בה' לפי שב' הצדיקים שוין למעלה בעצמות א\"ס שאין שם בחי' מעלה ומטה כלל כידוע, וזהו וצדקתך<sup data-n=\"1501\">77</sup> ירננו וד\"ל.\n<b>וזהו</b> ואולם חי אני וימלא כבוד ה' את כל הארץ. כי הנה עיקר טעות המרגלים הי' באמרם חזק<sup data-n=\"1502\">78</sup> הוא ממנו (וארז\"ל ממנו<sup data-n=\"1503\">79</sup> כבי' אפי' בעה\"ב אינו יכול להוציא כליו משם) כי הם היו סוברים שבחי' חיות הע' שרים דנוגה נמשך ג\"כ מבחי' מלכותו ית' כמ\"ש ומלכותו<sup data-n=\"1504\">80</sup> בכל משלה מלך<sup data-n=\"1505\">81</sup> אלקים על גוים כו' כמ\"ש את<sup data-n=\"1506\">82</sup> זלעו\"ז עשה כו'. אך דבאמת טעו, דודאי אין לך דבר חוץ ממנו ית' כמ\"ש כי<sup data-n=\"1507\">83</sup> ממך הכל, אבל מ\"מ יש הפרש בין המשכה חיצוני' להמשכה פנימיו' דעל הע' שרים לא נמשך האור האלקי להחיותם מאין ליש רק בבחי' חיצוני' מאד והוא הנק' בחי' צל כמו צל האדם שאינו מבחי' עצמותו כלל. וזהו שאמר כלב סר<sup data-n=\"1508\">84</sup> צלם מעליהם, כי שרש חיותם אינו אלא בחי' צל שהוא בבחי' מקיף בהעלם גדול ולא בא בבחי' אור וחיות פנימי ע\"כ עומד למעלה ואינו מאיר ובא למטה בתוך תוכם כלל (ומ\"ש כי חזק הוא להיות שרש הע' שרים מז' מלכי' דתוהו שהן בחי' גבורות חזקות אך כתיב למכה מלכים גדולים כו'). וז\"ש סר צילם מעליהם וממילא לחמינו הם כמו הבהמה שבורחת מן האדם כי אין להם בחי' אור פרצוף אדם אלא אתם<sup data-n=\"1509\">85</sup> קרויים אדם (ובמ\"א מבואר בענין בבואה אית להו ובבואה דבבואה<sup data-n=\"1510\">86</sup> לית להו שצל דצל הוא בחי' יחידה",[["1499","75","<b>דמים תחתונים בוכים אנן בעינן למהוי קדם מלכא</b>: ת\"ז תי' ה'. תוס' הרא\"ש בראשית בתחילתו."],["1500","76","<b>רננו צדיקים בה'</b>: תהלים לג, א."],["1501","77","<b>וצדקתך ירננו</b>: תהלים קמה, ז."],["1502","78","<b>חזק הוא ממנו</b>: במדבר יג, לא."],["1503","79","<b>ממנו כבי' אפי' בעה\"ב אינו יכול להוציא כליו משם</b>: סוטה לה, א. ובכ\"מ."],["1504","80","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["1505","81","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["1506","82","<b>את זה לעו\"ז עשה</b>: קהלת ז, יד."],["1507","83","<b>כי ממך הכל</b>: דה\"א כט, יד."],["1508","84","<b>סר צלם</b>: במדבר יד, ט."],["1509","85","<b>אתם קרוים אדם</b>: ב\"מ קיד, ב. זח\"א כ, ב. ובכ\"מ."],["1510","86","<b>בבואה אית להו ובבואה דבבואה לית להו</b>: יבמות קכב, א. ובכ\"מ. וראה לקו\"ת תצא לו, ג. ובכ\"מ."]]],[2101000244,"אין להם כו'). וזהו ואולם חי אני וימלא כבוד ה' גם למטה בבחי' גילוי או\"פ את כל הארץ גם באותיות דא\"ת דתוהו שנפלו בע' שרים, וכמו לעתיד דכתיב ואת<sup data-n=\"1511\">87</sup> רוח הטומאה אעביר כו' וממילא אין לע' שרים בחי' אור גם בחיצוני' המקיף כמ\"ש סר צילם מעליהם, כי הרי נאמר וכבודי<sup data-n=\"1512\">88</sup> לאחר לא אתן פי' כבודי העצמי שבו נאמר לכבודי בראתיו כנ\"ל לסט\"א לא אתן, כי הפרידן מאחדותו הפשוט ולא עליהם הי' הרצון ומחשבה אנא אמלוך כו'. וזהו שנשבע ה' בנפשו ואמר חי אני בחי' אור עצמותו ממש שימלא כבוד ה' בחי' אנא אמלוך הנ\"ל את כל הארץ ויבוער רוח הטומאה לגמרי לפי שנאמר וכבודי לאחר לא אתן כו'. ובזה מתורץ הקושי' הנ\"ל בענין וימלא ל' עתיד, דעכשיו עדיין יש יניקה לע' שרים מבחי' מלכותו ית' עכ\"פ בבחי' צל ומקיף וע\"כ אין כבוד ה' העצמי הנ\"ל מתגלה למטה משום דכבודי העצמי לאחר לא אתן ומ\"ש מכה\"כ היינו רק בחי' גילוי כבוד העליון הנמשך בבחי' צמצום מן ההעלם, אבל על בחי' עצמו' כבודו הרי שואלים המלאכי' איה מקום כבודו כנ\"ל, רק שלעתיד יתגלה, וז\"ש וימלא כבוד ה' כו' וד\"ל.",[["1511","87","<b>ואת רוח הטומאה אעביר מן הארץ</b>: זכרי' יג, ב."],["1512","88","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."]]],[2101000245,"<h3>להבין שרשי הדברים</h3>\n<b>להבין שרשי הדברים </b>\n<b>להבין</b><sup data-n=\"1513\">1</sup> שרשי הדברי' הנ\"ל. הנה להבין שרש ענין וימלא כבוד ה' כו' לשון להבא ומ\"ש ברוך<sup data-n=\"1514\">2</sup> כבוד ה' ממקומו מהו ממקומו, וכן להבין תירוץ הקושיא למה שואלין המלאכים איה מקום כבודו כו' כנ\"ל. הנה דבר זה יובן בהקדי' תחלה הקדמה אחת בענין ע\"ס דאצי' שיש ב' מדריגות בהן הא' בחי' ע\"ס הגלויות באצי', והב' בחי' ע\"ס הגנוזות בעצמו' המאציל וכמ\"ש בפרד\"ס באריכות<sup data-n=\"1515\">3</sup>. דהנה<sup data-n=\"1516\">4</sup> מבואר בס\"י ובפרד\"ס במשל ע\"ס הגנוזות במאציל שהוא כדמיון שלהבת הקשורה בגחלת כו'. ולכאורה י\"ל הטעם למה לא מצאו משל ודמיון לזה רק משלהבת הקשורה בגחלת דוקא כו'. אך הענין הוא דבאמת משל זה דשלהבת הקשורה בגחלת אינו אלא דמיון אמיתי לענין ע\"ס הגנוזות שהן בכח ולא בפועל ואין ערוך לגילוי הפעולה לעצם כח הפועל כמשי\"ת, אבל לענין השני דהיינו בבחי' היחוד והקשר של הע\"ס במאציל אין משל זה דמיון אמיתי אלא דמיון האמיתי הוא מיחוד והתקשרות כחות הנפש בעצמות הנפש שמתאחדי' בה ממש. דהנה יש לפרש בכונת המשל הזה דשלהבת כו' ב' ענינים הא' שר\"ל כמו השלהבת הקשורה בהעלם ומתאחדת בעצם הגחלת, וא\"כ",[["1513","1","<b>להבין שרשי הדברים</b>: נדפס בשינויים בדרמ\"צ קפב, א."],["1514","2","<b>ברוך כבוד ה' ממקומו</b>: יחזקאל ג, יב."],["1515","3","<b>ע\"ס דאצי' שיש ב' מדריגות. . וכמ\"ש בפרדס באריכות</b>: שער הצחצחות. ובהבא להלן ראה ג\"כ סה\"מ תקס\"ד ע' צז. אוה\"ת בשלח ע' תפא ואילך. המשך מים רבים תרל\"ו פס\"ד ואילך. הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 243."],["1516","4","<b>דהנה מבואר בס\"י</b>: פ\"א מ\"ז."]]],[2101000246,"עיקר המכוון במשל הזה להבין על בחי' היחוד של הע\"ס הגנוזות במאציל דוקא. והכונה השנית במשל זה הוא לדמות ענין הבנת ערך ע\"ס הגלויות לגבי ע\"ס הגנוזות שהוא כמו השלהבת הקשורה בגחלת, וא\"כ פי' קשורה בגחלת אין הכונה על השלהבת הגנוזה בגחלת בהעלם שהיא מתאחדת בעצם הגחלת כנ\"ל בפי' הא', אלא הכונה הוא על בחי' גילוי השלהבת שקשורה בעצם שלהבת הגחלת, וזהו דמיון להבין קשר וחיבור גילוי הפעולה בכח הפועל בלבד. אבל לפי פי' הא' הכונה במשל זה להבין על יחוד וקשר ע\"ס עצמן במאציל דהיינו יחוד ע\"ס הגנוזות איך שהן מיוחדים בעצמות המאציל, וז\"ש קשורה כלומר שלהבת הקשורה בהעלם ומתייחדת בעצם הגחלת ואינו מדבר בבחי' גילוי שלהבת כלל וד\"ל.\n<b>והנה</b> שני הפירושי' אמת, דבמשל זה דשלהבת הקשורה כו' הרי יש ב' ענינים הללו, דגילוי השלהבת נמשכת מעצם החמימות הנעלמת בתוך הגחלת וגם זה אמת דבחי' כח החמימות הנעלמת בתוך הגחלת מתאחדת עמה והיו לעצם א'. והנמשל מב' ענינים הללו יובן ג\"כ בע\"ס הגלויות בבחי' האצי' שהן בחי' אורות נגלים מן ההעלם דעצמו' המאציל ונק' ע\"ס במציאת ניכרת לכאו\"א, אך הן קשורים ומתייחדים במקור חוצבם בעצמות המאציל כדמיון גילוי שלהבת שקשורה בהעלם החמימות שבגחלת כפי' הב' דלעיל. והנמשל מענין הפי' הא' כשלהבת הקשורה כו' הוא בחי' ע\"ס הגנזזות במאציל שמיוחדי' בו בתכלית היחוד כדמיון כח החמימות שלהבת הנעלם בגחלת שקשורה ומתאחדת עמה מאד, ומובן ממילא שבודאי יחוד ע\"ס הגנוזות בעצמות יחוד אמיתי יותר מיחוד ע\"ס הגלויות בע\"ס הגנוזות שכבר באו בגילוי בבחי' מציאת ניכרת רק שנכללים ומתייחדי' במקור חוצבם, אבל ע\"ס הגנוזות שנק' ע\"ס בלי מ\"ה כלומר בלי מהות מתאחדי' בתכלית בעצמו' המאציל כו'. והמשל מורה ע\"ז שהרי כח החמימות הנעלמת בגחלת מתייחדת יותר מיחוד גילוי השלהבת כשנקשרת בגחלת כידוע וד\"ל.\n<b>והנה</b> יובן ג\"כ מכ\"ז גם בבחי' גילוי כח הפועל בנפעל שיש ב' מיני יחודים, הא' יחוד והתכללות בחי' גילוי הפעולה שנתפשטה בנפעל אל עצם הכח הנעלם בפועל שהוא כמו קשר גילוי השלהבת בגחלת כנ\"ל, והב' בחי' יחוד דכח הפועל הנעלם בו כשהוא מתאחד בעצם הפועל שהוא יחוד יותר אמיתי כמו כח החמימות שמתאחד בגחלת כנ\"ל. והדוגמא במשלים הללו ג\"כ יובן בחי' גילוי פעולת הע\"ס הגלויות איך שנכללים בע\"ס הגנוזות שהן כדמיון כח הפועל הנעלם בעצמו שבודאי אין ערוך לגילוי הפעולה המתפשטת מכח הפועל העצמי ומ\"מ היא קשורה ומתאחדת תמיד בו כו', אבל יחוד כח הפועל בעצם הפועל הוא יחוד גמור. וכך גם בחי' ע\"ס הגנוזות במאציל שהן בחי' מקוריות וכחות עצמיו' במאציל כמו כח הפועל אשר בעצם הפועל ודאי מתייחדי' בו יחוד גמור ואמיתי וד\"ל.\n<b>וזהו</b> פי' המאמר הידוע אנת<sup data-n=\"1517\">5</sup> הוא חד כו' חכים ולא בחכ' ידיע' כו' פי' על בחי' היחוד שבע\"ס הגנוזות בעצמות המאציל אמר אנת הוא חד בעצמותך יחוד",[["1517","5","<b>אנת הוא חד</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101000247,"גמור ושם נק' חכים ולא בחכ' ידיעה כלל וכלל כי חכמתו ית' מתייחדת בעצמו' המאציל וכמ\"ש ולתבונתו<sup data-n=\"1518\">6</sup> אין חקר פי' ולתבונתו העצמי' כו' כמאמר הוא המדע והוא<sup data-n=\"1519\">7</sup> הידוע וכן לגדולתו העצמי' אין חקר שהוא בבחי' א\"ס ממש כמ\"ש חסדי<sup data-n=\"1520\">8</sup> ה' כי לא תמנו כו', משא\"כ בחי' ספי' חכ' דאצי' וספי' חסד דאצי' גם כשבאין ונכללין במקור חוצבם בע\"ס הגנוזות מ\"מ אינן אלא בחי' התפשטו' הארה פרטיות מבחי' כחות דע\"ס העצמיי' כמשל גילוי כח הפועל בפעולה פרטי' כנ\"ל רק שנכללים בכחות העצמיי' דע\"ס הגנוזות ע\"כ עליהם לא יפול לשון לא ידיעא כי הרי ניכרין במציאת כח פעולתן ומוגבלין הן לפי ערך לגבי ע\"ס הגנוזות עצמן כו' רק על ע\"ס הגנוזות בעצמות שייך לומר חד ולא בחושבן וגבול ולא ידיעה כלל וד\"ל.\n<b>והנה</b> משל הזה דשלהבת הקשורה בגחלת אינו דמיון אמיתי רק לענין השגת ערך התפשטו' י\"ס הגלויות באצי' לגבי בחי' המקוריות שלהן הגנוזות במאציל שהוא רק כמו כח התפשטו' הפעולה מכח עצם הפועל כנ\"ל. אבל לענין היחוד של ע\"ס הגנוזות במאצילן עם עצמו' אור המאציל אינו דמיון אמיתי שהרי עצם הגחלת עם כח החמימות של שלהבת הקשורה בה בהעלם המה ב' דברים עכ\"פ רק שמתאחדי' יחד והיו לאחדי' וא\"כ איננו יחוד עצמי כמו בחי' היחידו' באדם כאשר אין שני לו כלל שנק' יחיד בעצם ועד\"ז אמר אנת הוא חד פי' אנת היינו בחי' יחיד בעצם האחדו' הפשוטה ואין זה מובן בדמיון אמיתי רק ממשל ודוגמא של יחוד והתכללות כחות הנפש בעצם הנפש כמו כח החכ' כאשר הוא כלול בעצם הנפש ממש שאינה ניכרת כלל במציאות חכ' ושכל אלא כלולה ומתאחדת ממש בעצם הנפש. וכך למעלה אמר אנת חכים ולא בחכ' ידיעה כלל, ופי' אנת חכים ר\"ל בחי' החכ' הקדומה הכלולה ומתאחדת בעצמי' אור המאציל והוא הנק' ולא בחכ' ידיעה כלל. ועד\"ז שאר הספי' הגנוזות בעצמו' המאציל שמתייחדים בו הרי הן מתייחדים ביחוד גמור ואמיתי הנ\"ל אינו מובן רק ע\"ד התכללות כחות הנפש בעצמותה בלבד וד\"ל.\n<b>ויובן</b> בחי' יחוד זה בתוס' ביאור גם בבחי' ההשתלשלות דע\"ס הגלויות זמ\"ז כאשר הן באין בבחי' השתלשלו' מעילה לעילה אך לא בבחי' התגלות העלול מן העילה שאינו אלא כמו התגלות הפעולה מכח הפועל או כמו גילוי השלהבת מעצם העלם השלהבת הקשורה בגחלת אלא בבחי' מקור כל עלול ושרש כחו הנעלם בעילה כמו כח ומקור התפעלות המדות כמו שהוא עדיין בשכל ובינה<sup data-n=\"1521\">9</sup> שנק' אם הבנים כנודע. דהנה ודאי שאין לדמות מהות גילוי התפעלות האהבה שנולדה מן השכל בלב לבחי' מקור חוצבה שהוא בחי' התפעלות האהבה בשכל שבמוח שהיא שם בחי' התפעלות שכליי' ולא מהות התפעלות שבלב כלל, אך מ\"מ בחי' התפעלות",[["1518","6","<b>ולתבונתו אין חקר</b>: ראה ישעי' מ, כח."],["1519","7","<b>הוא המדע והוא הידוע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. מו\"נ ח\"א פס\"ח. שמונה פרקים פ\"ח. תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["1520","8","<b>חסדי ה' כי לא תמנו</b>: איכה ג, כב."],["1521","9","<b>ובינה שנק' אם הבנים</b>: זח\"א ריט, א. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ד ע' 52. תש\"ט ע' 112."]]],[2101000248,"שכליי' הזאת שבמוח נק' מקור וכח המוליד להתפעלו' האהבה שבלב שהרי לא יתפעל בלב רק לפי אופן התפעלו' שבשכל כי כל מוליד יוליד בדומה לו דוקא וה\"ז כדמיון כח הפועל בנפעל כנ\"ל. וזהו ענין התהוות העלול מן העילה בגילוי שאיננו מתייחד כ\"כ במקורו כמו יחוד מקור העלול כמו שהוא כלול בעילה שהוא מתייחד בעצם העילה ביחוד והתכללות אמיתי יותר, והיינו כמו בחי' יחוד והתכללות של התפעלו' שכליי' שנק' מקור וכח העלול שהוא התפעלו' המדה שבלב בתוך עצם העילה שהוא עצם השכל וההתבוננו' כנראה בחוש שהתפעלות השכל לא יוכר כלל בהיותו טרוד בעצם המושכל, וכמ\"כ כל מקור העלול כמי שהוא כלול בעצם העילה מתייחד ומתכלל שם בתכלית היחוד וההתכללות כידוע דגם אור השכל נק' עלול לגבי אור הרצון ונמשך בגילוי התהוות מן הרצון כמ\"ש והחכ' מאין תמצא<sup data-n=\"1522\">10</sup> ובהכרח שיש בחי' מקור ושרש להתהוות עלול דחכ' בעצם העילה שהוא הרצון והוא הנק' בשם משכיל שמשכיל כל שכל מן ההעלם לגילוי ובזהר נק' בשם חכמה סתימאה פי' בחי' כח השכל הנעלם שמשכיל כל שכל וחכ' בגילוי כו' וכמבואר בכמה מקומות. והנה בחי' משכיל זה הוא כלול ומתייחד בעצם העילה שהוא בחי' אור הרצון עצמו שנק' כתר עליון ונק' עילות העילות וכמאמר דאפי'<sup data-n=\"1523\">11</sup> אור צח אור מצוחצח אוכם הוא לגבי עה\"ע פי' אפי' בחי' ח\"ס הנ\"ל אוכם הוא לגבי עצם עילת העילות בתכלית הביטול וההתכללות וד\"ל. ועד\"ז יובן עד רום המעלות למעלה מעלה גם במקור הרצון הנק'<sup data-n=\"1524\">12</sup> רצון קדום או מח' הקדומה ולמעלה הימנו עד בחי' עצמו' אא\"ס ממש. ועפ\"י כ\"ז יובן ג\"כ בדרך כללות בבחי' יחוד והתכללות דע\"ס הגנוזות בעצמות המאציל שהוא יחוד גמור ואמיתי כמו בחי' יחוד והתכללות של כל מקור העלול בתוך העצמו' של העילה הגם שנק' גם הוא בשם גנוז ונעלם לגבי העלול הנגלה ממנו אבל לגבי עצם העילה בטל ונכלל לגמרי ולא כמו ביטול והתכללות העלול הנגלה לגבי מקור חוצבו הנעלם ממנו שאינו אלא כמו התגלות הפעולה מעצם כח הפועל או בגילוי השלהבת שאינו יחוד גמור כנ\"ל וד\"ל.\n<b>והנה</b> כתיב לך<sup data-n=\"1525\">13</sup> ה' הגדולה והגבורה כו' לך ה' הממלכה כו', דבחי' מדת המלוכה דאצי' שהוא מדת ההתנשאות ג\"כ בטל לגבי מקור חוצבה בהעלם העצמו' כמו שאר הספי' דאצי' הגלויות באצי' שבטלים ונכללים במקורם בבחי' ע\"ס הגנוזות כנ\"ל וז\"ש לך ה' הגדולה והגבורה והתפארת כו' שהן בחי' מדות חג\"ת דאצי' שבאו מן ההעלם לגילוי עד\"מ באדם התחתון שמדת החסד אשר בלבו ישנה בבחי' ההעלם בעצם הנפש אך כשמתפעל בהתפעלות החסד הנה אז תאיר אורה לגילוי לחוץ וכן שאר המדות נמשכים מהעלמם בנפש ע\"ד דמיון יציאת השלהבת מן הגחלת או כמו פעולה הנגלית מעצם כח הפועל כנ\"ל באורך, וגם אור הרצון או מדת הניצחון שתלוי בפנימי' הרצון ג\"כ מתגלה מן ההעלם כו'.",[["1522","10","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["1523","11","<b>דאפי' אור צח אור מצוחצח אוכם</b>: ראה ת\"ז תי' ע (קלה, ב)."],["1524","12","<b>הנק' רצון קדום או מח' הקדומה</b>: ראה לקו\"ת שה\"ש יז, ד. סידור שער המילה קלט, ד."],["1525","13","<b>לך ה' הגדולה והגבורה</b>: דה\"א כט, יא."]]],[2101000249,"<b>והנה</b> בחי' ההעלם דמדת ההתנשאות למעלה היינו בחי' מל' דא\"ס שלפני הקוה\"ח כו', כי הנה מבואר בס' עמק המלך דשרש הראשון לע\"ס הגלויות הוא בחי' הקוה\"ח ובחי' טהירו עילאה הנק' אויר קדמון הוא בחי' אור הא\"ס עצמו שקודם הצמצום (אבל בחי' הקו נק' אור קדמון והוא שרש בחי' א\"ק שנמשך מראשי' הקו כו') וא\"כ עיקר בחי' ע\"ס הגנוזות בעצמות הוא בבחי' אור הא\"ס שלפני הקו ששם גנוזים כל הע\"ס בהעלם העצמות ממש (וכמ\"ש במק\"מ ב' האריז\"ל בפי' בריש הורמנתא דמלכא כו' ששיער בכח בעצמו כו' וכמבואר במ\"א) ובחי' הנק' מל' דא\"ס הוא ספי' ומדה העשירית מע\"ס הגנוזות בהעלם העצמות אבל הנה עלה תחלה במח' הקדומה אנא אמלוך פי' במחה\"ק שבעצמותו ממש עלה סוף מעשה תחלה שהוא בחי' כח ההעלם דמדת ההתנשאו' דאנא אמלוך ובקו\"ח בא אור מדה זאת באחרונה, והוא בחי' מל' דאצי' שהוא בחי' ההתנשאות בגילוי אור לחוץ והוא ענין אין<sup data-n=\"1526\">14</sup> מלך בלא עם על עם נפרד להתנשא עליהם וכמ\"ש לכבודי<sup data-n=\"1527\">15</sup> בראתיו כו' וכבוד<sup data-n=\"1528\">16</sup> הוא בחי' המל' הנ\"ל כנודע. וז\"ש לך ה' הממלכה והמתנשא מימות עולם, פי' לך ה' בחי' אור ההתנשאות דגילוי שבאצי', כי סוף מעשה זו עלה במה\"ק תחלה אנא אמלוך והוא הנק' מל' דא\"ס כי<sup data-n=\"1529\">17</sup> נעוץ תחב\"ס וסופן בתחילתן וד\"ל (כי מדת ההתנשאות אינה מדה ואור וחיות פרטי כאור החסד או אור השכל אלא היא בחי' מדה ואור כללי דהיינו התנשאות עצמותו דוקא והוא להיות שרשה בעצמות הנפש יותר משאר המדות וע\"כ אנו רואים שיעזוב המלך כל אשר לו בעושר ותענוגים וימסור כל חיי נפשו בעד המלוכה וההתנשאו', וכנראה מענין שאול עם דוד דגם שצדיק גמור הי' ונק'<sup data-n=\"1530\">18</sup> בחיר ה' וידע האמת והודה לדוד כי<sup data-n=\"1531\">19</sup> מלוך תמלוך ויכול תוכל כו' ואעפ\"כ רדף אחריו כו' וד\"ל).\n<b>ובכ\"ז</b> יובן מה שאומרים המלאכים ג\"פ קדוש עד שאומרים מלא כה\"כ וכמ\"ש וקרא<sup data-n=\"1532\">20</sup> זא\"ז וא' קק\"ק כו'. כי הנה כתיב לכבודי<sup data-n=\"1533\">21</sup> בראתיו יצרתיו אף עשיתיו שהן ג' עולמות בריאה יצירה עשי' כידוע דהיינו בחי' המל' שנק' כבוד מתפשט בג' עולמות בי\"ע ע\"י בחי' ג' צמצומים והן ג\"פ קדוש כידוע<sup data-n=\"1534\">22</sup> בע\"ח שג' צמצומים הללו הן ג' שמות א\"ל שדי בבריאה וא\"ל הו\"י' ביצירה וא\"ל אדנ\"י בעשי' (ולפעמים אל שדי ביצי' ואל הוי' בבריאה וכמ\"ש וארא<sup data-n=\"1535\">23</sup> אל אברהם באל שד\"י כו' כמ\"ש במק\"מ) כי פי' א\"ל הוא בחי' צמצום באל\"ף למ\"ד כו'. והנה הבריאה נק' בחי'",[["1526","14","<b>אין מלך בלא עם</b>: בחיי וישב לח, ל. ר\"פ בלק. ועוד. וראה שעהיחוה\"א פ\"ז."],["1527","15","<b>לכבודי בראתיו</b>: ישעי' מג, ז."],["1528","16","<b>וכבוד הוא בחי' המל'</b>: ראה פרדס שער ערה\"כ ומאו\"א מע' כבוד. לקו\"ת האזינו עה, א."],["1529","17","<b>כי נעוץ תחב\"ס וסופן בתחילתן</b>: ס\"י פ\"א מ\"ז."],["1530","18","<b>ונק' בחיר ה'</b>: שמואל-ב כא, ו. ובכ\"מ."],["1531","19","<b>כי מלוך תמלוך ויכול תוכל</b>: שמואל-א כד, כא. כו, כה."],["1532","20","<b>וקרא זא\"ז ואמר קק\"ק</b>: ישעי' ו, ג. ברכת יוצר. וראה אוה\"ת נ\"ך ע' קסח."],["1533","21","<b>לכבודי בראתיו</b>: ישעי' מג, ז."],["1534","22","<b>כידוע בע\"ח</b>: ראה תו\"א משפטים עו, ג. דרמ\"צ הנסמן לעיל בריש המאמר (קפג, ב)."],["1535","23","<b>וארא אל אברהם באל שדי</b>: ראה שמות ו, ג."]]],[2101000250,"חושך העלם לגבי היצי' כמ\"ש יוצר<sup data-n=\"1536\">24</sup> אור ובורא חושך משום דברישא<sup data-n=\"1537\">25</sup> חשוכא והדר נהורא דהיינו בחי' ההעלם שקדם לבחי' הגילוי שנק' יצירה כמו משל הדיבור לגבי המחשבה כידוע, והוא בחי' א\"ל שדי שאמר לעולמו די<sup data-n=\"1538\">26</sup> בבחי' הצמצום וההעלם כו'. וא\"ל הוי' שהוא בבחי' אור גילוי ההעלם הוא ביצי', וא\"ל אדנ\"י בסוף מעשה דעולם העשי' כו'. ועל ג' שמות הללו רומז ג\"פ קדוש כי כל קדוש הוא ענין הבדלה והעלמת אור, וז\"ש וקרא זה אל זה וא' קדוש ג\"פ עד שאומרים מלא כה\"כ, פי' עד שנגלה בחי' המל' שנק' כבודו בכל עולם ועולם, ובקדוש הא' נמשך המל' בבריאה ובקדוש הב' ביצי' כו'. ועד\"ז יובן דרך פרט שיש ג' מדריגות דבי\"ע בכל עולם מג' עולמות דבי\"ע כו', וזהו שגם השרפי' שבבריאה או' ג\"פ קדוש כו'. וכמ\"כ יובן ג\"כ דרך כללות כל ההשתלשלות דאבי\"ע דבחי' א\"ק שהוא ראשי' הקו נק' אדם דבריאה ובחי' ע\"י וא\"א נק' אדם דיצי' ובחי' ז\"א נק' [אדם] דעשי' כמ\"ש<sup data-n=\"1539\">27</sup> בע\"ח, וג\"פ קדוש היינו בחי' ג' צמצומי' הכלליי' הללו בבחי' בי\"ע הכלליי' עד שנגלה בחי' מל' דא\"ס שנק' כבודי העצמי. דהנה כמו שמדת המל' דאצי' מתפשטת בבי\"ע הנפרדי' בג' צמצומים כנ\"ל כך בחי' מל' דא\"ס מתפשט בבחי' הקוה\"ח בג' צמצומים הכלליי' דא\"ק וע\"י כו' שהן בחי' בי\"ע הכלליי'. וע\"ז אמר ג\"כ וקרא זא\"ז ואמר ג\"פ קדוש עד שיהי' מכה\"כ, שהוא בחי' המל' דא\"ס בכל עולם, בעולם הא\"ק בקדוש הא', ובע\"י וא\"א בקדוש הב', ובקדוש הג' בז\"א דאצי' כו' עד בחי' מל' דאצי' שהוא מדת ההתנשאו' בגילוי אור לחוץ כו' כנ\"ל וד\"ל. והנה מבואר למעלה דשרש מדת ההתנשאות מגעת בבחי' העצמות יותר וע\"כ היא נעלמת יותר בעצמות משאר המדות הנעלמים בעצמות, והוא הטעם ג\"כ מה שאנא אמלוך עלה במח\"ת כו' כנ\"ל. וע\"כ כדי להמשיך ולעורר זאת המדה מעצם העלם הקדמות צריך להיות ע\"י קריאת ג\"פ קדוש עד שיהי' התעוררו' לגילוי העלמה וז\"ש וקרא זא\"ז ג\"פ קדוש עד שאו' מכה\"כ, וכן נאמר שאו<sup data-n=\"1540\">28</sup> שערי' ראשיכם ויבא מלך הכבוד ושואלים מי הוא זה מלך הכבוד כו' עד שמתגלה ה' צבאות הוא מלך הכבוד כו' וד\"ל.\n<b>וזהו</b> שרש ענין ברוך כבוד ה' ממקומו, פי' ממקומו מבחי' מקור ושרש הנעלם דמדת המלוכה וההתנשאות שנק' כבוד ה' כנ\"ל. וכן המלאכים ששואלין איה מקום כבודו אין הכונה על בחי' גילוי אור המל' שנגלה בתוך תוכם אלא על בחי' מקור ושרש מחצב מדת ההתנשאו' כמו שהיא בעצמות הא\"ס שנק' בחי' מל' דא\"ס, וזהו איה מקום כבודו בחי' המקום והשרש של כבודו כו' וד\"ל. וזהו ג\"כ מ\"ש ראו<sup data-n=\"1541\">29</sup> כי אני אני הוא, פי' בחי' מל' דא\"ס נק' אני ובחי' מל' דאצי' נק' אני וכמ\"ש אני ראשון ואני<sup data-n=\"1542\">30</sup> אחרון מפני שסוף מעשה עבמח\"ת משום שנעוץ תחב\"ס כו' כנ\"ל וד\"ל.",[["1536","24","<b>יוצר אור ובורא חושך</b>: ישעי' מה, ז. וראה פע\"ח שער הק\"ש פ\"א. שער הכוונות ענין כוונת יוצר. מ\"ח מס' תפלת הבריאה פ\"א מ\"ז ואילך."],["1537","25","<b>דברישא חשוכא והדר נהורא</b>: שבת עז, ב."],["1538","26","<b>א-ל שדי שאמר לעולמו די</b>: חגיגה יב, א. זח\"ב רנז, א. זח\"ג רנא, ב."],["1539","27","<b>כמ\"ש בע\"ח</b>: ש\"ג פ\"א. ובכ\"מ."],["1540","28","<b>שאו שערים ראשיכם. . מי הוא זה מלך הכבוד</b>: תהלים כד, ז ואילך."],["1541","29","<b>ראו כי אני אני הוא</b>: דברים לב, לט. וראה אוה\"ת האזינו ע' א'תש."],["1542","30","<b>אני ראשון ואני אחרון</b>: ישעי' מד, ו."]]],[2101000251,"<b>אך</b> הנה בס' פע\"ח אמר בפי' ברוך כבוד ה' ממקומו שהוא בחי' אור אבא כו' משום דאבא<sup data-n=\"1543\">31</sup> יסד ברתא כו' ע\"ש. והענין הוא להיות כי אנו רואים עד\"מ התינוק קודם שנגדלו המוחין שלו בשלימות דהיינו כאשר לא נשלמו בו הארות מוחין דאבא הנק' צלם אבא אז לא יוכל לדבר בפה בה' מוצאות משום שהתהוות הצירופי' בה' מוצאות הוא מבחי' אור החכ' דוקא (והיינו מבחי' כח המשכיל ההיולי שנק' קדמות השכל ולא בחי' נקודת המושכל הבא בגילוי כמ\"ש במ\"א). וזהו דאבא יסד ברתא שהוא המל' בחי' דיבור העליון כמ\"ש מצרף לחכ' כו'. וזהו מ\"ש בע\"ח בפי' ברוך כבוד ה' שהוא במל' ממקומו ושרשו באור אבא, וע\"ד שאמר והמלך<sup data-n=\"1544\">32</sup> שלמה ברוך לשון נפעל דהיינו ממקורו באור החכ' שמשם נמשך שרש התהוות הצירופי' שבמל'. והנה גם על בחי' מקור דחכ' בדיבור שואלים המלאכים איה מקום כבודו פי' מקומו ושרשו של כבוד התחתון שהוא בחי' מל' הוא בחי' אור שנק' כבוד העליון וכמ\"ש כבוד<sup data-n=\"1545\">33</sup> חכמים ינחלו וכן ונגד<sup data-n=\"1546\">34</sup> זקיניו כבוד וכידוע, ולכך שואלים איה מקום ושרש כבודו בחכ' כו'. משא\"כ בחי' כבוד התחתון דמל' הבא בצירופי אותיות הרי מתגלה בתוך כל מלאך ונברא כמ\"ש הדובר<sup data-n=\"1547\">35</sup> בי שמקבל מבחי' דיבור העליון ולכך יוכל המלאך לומר הרבה<sup data-n=\"1548\">36</sup> ארבה זרעך כו' כי דבר ה' הדובר בו כו' וכמ\"ש למעלה ולא יתכן שישאלו עליו כי אין השאלה רק על דבר הנסתר כידוע וד\"ל. אך הנה מבואר למעלה בפי' מקומו שהוא בחי' מל' דא\"ס דהיינו בחי' מקור של מדת ההתנשאו' כמו שהיא כלולה בעצמות ממש כנ\"ל, אמנם הענין הוא דשניהם אמת משום שידוע שבחי'<sup data-n=\"1549\">37</sup> ראשי' גילוי אא\"ס הוא בחכ' דוקא כמ\"ש ה'<sup data-n=\"1550\">38</sup> בחכ' כו' וכן בראשי' <sup data-n=\"1551\">39</sup>ברא אלקי' הוא בחי' חו\"ב כמ\"ש<sup data-n=\"1552\">40</sup> בזהר דאבא אמר לאימא כו'. והטעם הוא כי בחי' החכמה הוא נחשב לבחי' גילוי ההעלם לגבי בחי' עצמות א\"ס כמו שנראה למטה שהברקת גילוי אור השכל הגם שאינו אלא בחי' נקודה נעלמת לגבי אור הבינה שהוא ההשגה מ\"מ נק' גילוי לגבי העלם העצמות דבחי' יחידה שבנפש כו' (ואפי' בחי' כח המשכיל ההיולי נק' גילוי אור לגבי עצמות ההעלם כו'). וז\"ש כי<sup data-n=\"1553\">41</sup> אתה אבינו שאור אבא נק' אתה כמו שהמל' נק' אתה שהן כ\"ב אותיות וה' מוצאות (וכמ\"ש<sup data-n=\"1554\">42</sup> בזהר ע\"פ ואתה כהן לעולם דתלת דוכתי איקרי אתה כו' וכמ\"ש במ\"א) וגם על בחי' אור אבא יתפרש ענין ברוך כבוד ה' דהיינו בחי' כבוד העליון דחכ' ממקומו ושרשו בעצמו' כי כבוד הן ל\"ב נ\"ח כידוע וד\"ל.",[["1543","31","<b>דאבא יסד ברתא</b>: זח\"ג רמח, א. רנו, ב. רנח, א. ת\"ז תי' כא (סא, ב)."],["1544","32","<b>והמלך שלמה ברוך</b>: מלכים-א ב, מה. וראה לקו\"ת תזריע כב, ג. ובכ\"מ."],["1545","33","<b>כבוד חכמים ינחלו</b>: משלי ג, לה."],["1546","34","<b>ונגד זקיניו כבוד</b>: ישעי' כד, כג."],["1547","35","<b>הדובר בי</b>: זכרי' א, ט ואילך."],["1548","36","<b>הרבה ארבה זרעך</b>: בראשית כב, יז."],["1549","37","<b>שבחי' ראשית גילוי אוא\"ס הוא בחכ'</b>: ראה ע\"ח שער דרושי אבי\"ע פ\"א. שעהיחוה\"א פ\"ח ואילך. ובכ\"מ."],["1550","38","<b>ה' בחכ'</b>: משלי ג, יט."],["1551","39","<b>בראשית ברא אלקים</b>: בראשית א, א."],["1552","40","<b>כמ\"ש בזוהר דאבא אמר לאימא</b>: ראה זח\"א כב, א."],["1553","41","<b>כי אתה אבינו</b>: ישעי' סג, טז. וראה זח\"ג רצ, א."],["1554","42","<b>וכמ\"ש בזוהר ע\"פ ואתה כהן לעולם</b>: תהלים קי, ד. זח\"ג קצג, ב. וראה ביאוה\"ז להצ\"צ כרך ב' ע' תשיג."]]],[2101000252,"<b>וא\"כ</b> הרי פי' הנ\"ל במקומו מבחי' מל' דא\"ס כולל ב' הענינים בפי' ברוך כבוד ה' בין על כבוד התחתון דמל' בין על כבוד העליון דחכ', כי מאחר דאבא יסד ברתא כנ\"ל הרי שניהם כא' כבוד התחתון ושרשו כבוד העליון מתברכים ממקור הראשון שהוא בחי' מל' דא\"ס רק שעובר השפע תחלה בכבוד העליון דחכ' ומחכ' לדיבור כו'. אמנם שסוף מעשה במח\"ת ונעוץ תחב\"ס דוקא כנ\"ל הנה מ\"מ שרש בחי' המל' הוא בבחי' מל' דא\"ס קודם לבחי' החכ' הגם שהחכמה הוא ג\"כ בחי' גילוי ההעלם כנ\"ל אבל בחי' הדיבור שבמל' היא סוף מעשה יותר ועולה במח' דחכ' הקדומה תחלה להתהוות החכ' בגילוי, והוא ענין בי\"ת דבראשי' כמ\"ש בחכ'<sup data-n=\"1555\">43</sup> יבנה בית שהוא הדיבור שנק' בית כמ\"ש<sup data-n=\"1556\">44</sup> בס\"י ה' אבנים בונות ק\"כ בתים כו' וע\"כ הפי' האמיתי יותר הוא כנ'\"ל בפי' כבוד ה' ממקומו שהוא בחי' מל' דא\"ס שמאיר במל' דאצי' דוקא וכמ\"ש אני ראשון ואני אחרון וכן ראו כי אני אני הוא כו' כנ\"ל שלמעלה מבחי' החכמה (והגם<sup data-n=\"1557\">45</sup> דאבא יסד ברתא אינו אלא שמצרף לצירופי האותיות כמו שמיסד אדם בנין אבנים שאינו אלא מסדר סדר המצב אבל גוף האותיות הנק' אבן שרשו בבחי' מל' דא\"ס, וז\"ש כי אני אני הוא וד\"ל.\n<b>והנה</b> כתיב תתן<sup data-n=\"1558\">46</sup> אמת ליעקב חסד לאברהם כו', פי' שרש<sup data-n=\"1559\">47</sup> מדת יעקב הוא מדת הרחמים רבים שבכתר שנק' נחלה<sup data-n=\"1560\">48</sup> בלי מצרים וכמ\"ש והאכלתיך נחלת יעקב אביך כו', והיינו בחי' הקו האמצעי דת\"י שנק'<sup data-n=\"1561\">49</sup> בריח התיכון המבריח מן הקצה לקצה. פי' כי קו הימין והשמאל חח\"נ בג\"ה יש להן מצרים למעלה ולמטה ולצדדי', אבל קו האמצעי אין לו מיצר לא למעלה ולא למטה ולא לצדדי' וע\"כ נק' נחלה בלי מצרים. וז\"ש תתן אמ\"ת, א'מ'ת' א' הוא בחי' הכתר ששם מבריח קו האמצעי למעלה, ומ' הוא בחי' בינה ומל' שנק' מ\"ם פתוחה ומ\"ם סתומה, והתי\"ו הוא בחי' ת\"ת ומל' שמשפיעי' לבי\"ע.\n<b>וביאור</b> כ\"ז הנה תחלה יש להקדי' בשרש ענין ברוך כבוד ה' ממקומו הנ\"ל דהגם שהפי' האמיתי היינו מבחי' מל' דא\"ס שהוא מקור מדת ההתנשאו' כו' אבל מ\"מ בחי' ממוצע צריך להיות בין עצמות ההתנשאו' הנעלמת בעצמותו הנק' מל' דא\"ס שתבא ע\"י לגילוי בחכ' ומחכ' לדיבור (כנ\"ל שפי' ברוך כבוד ה' מתפרש על חכ' ומל' כא' ומחכ' למל' א\"צ לממוצע כי אבא בעצמו יסד ברתא, ואמנם כדי שיבא בחי' מל' דא\"ס לידי גילוי גם בחכ' צריך לממוצע, והיינו מי שיברך לכבוד ה' העליון והתחתון ממקומם ושרשם במל' דא\"ס להמשיך מן ההעלם לגילוי כו' וד\"ל). וזהו ההפרש בין חכמה לכתר שהחכ' שנק' כבוד הוא האור הבא בגילוי מן ההעלם,",[["1555","43","<b>בחכ' יבנה בית</b>: משלי כד, ג."],["1556","44","<b>כמ\"ש בס\"י ה' אבנים בונות ק\"כ בתים</b>: פ\"ד מט\"ז."],["1557","45","<b>(והגם</b>: בהכת\"י חסר סיום המוסגר."],["1558","46","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["1559","47","<b>שרש מדת יעקב הוא מדת הרחמים רבים</b>: ראה ג\"כ תניא פמ\"ה. אוה\"ת נ\"ך ע' א'נג."],["1560","48","<b>נחלה בלי מצרים וכמ\"ש והאכלתיך נחלת יעקב</b>: שבת קיח, א. ישעי' נח, יד."],["1561","49","<b>שנק' בריח התיכון</b>: זח\"ב קעה, ב. ועוד. וראה אוה\"ת ויחי שצה, א."]]],[2101000253,"אבל אור הכתר הוא נק' ממוצע להביא מן ההעלם לגילוי, א\"כ למעלה הוא מבחי' הגילוי ולמטה הוא בבחי' העלם העצמי כדרך כל בחי' ממוצע והוא בחי' אור הכתר שנק' העלם לגבי החכ' ונק' גילוי לגבי העצמות. והיינו פי' הוא ל' נסתר אבל יש מי שאומר עליו הוא רק שאינו ידוע למטה, אבל למעלה גלוי הוא. וזהו מ\"ש<sup data-n=\"1562\">50</sup> בזהר ע\"פ ועבד הלוי הוא דא עתיקא וכמ\"ש<sup data-n=\"1563\">51</sup> במ\"א בפי' הקדוש ב\"ה, דקדוש היינו בחי' מל' דא\"ס שמלובש בכתר וברוך הוא בחי' הגילוי באור אבא והוא בחי' הכתר הממוצע ביניהם שמביא מהעלם מל' דא\"ס לידי גילוי בחכ' כו' ע\"ש באריכות וד\"ל<sup data-n=\"1564\">52</sup>). והנה הממוצע הזה הוא בחי' אור כתר עליון כמ\"ש<sup data-n=\"1565\">53</sup> בתיקונים דאא\"ס מלגיו וכתרא עילאה מלבר כו' וכמ\"ש<sup data-n=\"1566\">54</sup> בע\"ח דבחי' הכתר נק' ממוצע בין עצמות המאציל לנאצלים ויש בו מבחי' האחרונה שבמאציל שהוא בחי' מל' דא\"ס דרך כללות וגם הוא בחי' מקור וראש לנאצלים כו', והוא הנק' בחי' רחמי' רבים שנק' נחלה בלי מצרים כלל כנ\"ל.\n<b>וביאור</b> הענין הנה תחלה י\"ל מהו ענין בחי' המיצר, דהנה כל מיצר מוגבל מששה קצוות מעלה ומטה וד' צדדי' מזרח ומערב צפון ודרום, וכאשר אנו אומרים שיש בחי' מיצר בב' הקוין ימין ושמאל חח\"נ ובג\"ה כנ\"ל היינו שיש להם ששה גבולים הללו, הא' למעלה דהיינו שיש לו שיעור וגבול למעלה, והוא בבחי' העילוי אחר עילוי למעלה בעצמו' המאציל, ויש לו שיעור וגבול למטה והוא בבחי' ההתפשטו' וירידת ההמשכה למטה. וכמו בחי' מקור החסד דקו הימין חח\"נ הנה יש לו שיעור למעלה בשרשו מעצמו' המאציל כו', כי חפץ חסד הוא במדה הקצובה עפ\"י<sup data-n=\"1567\">55</sup> מאמר קו המדה כידוע, וממילא יש לו שיעור למטה בהתפשטות החסד בכל קו הימין עד נצח שבחסד כו' ושם הוא כלה ומסתיים אורו, וכמ\"כ בחי' גבורה בקו השמאל בג\"ה כו', ועד\"ז יש להן גבול לצדדים כי קו הימין דחסד מתצמצם אורו כשמגיע להיפכו המנגדו שהוא קו השמאל מדה\"ד, וכן להיפך מדה\"ד מתקצר ומתצמצם כשמגיע להיפכו המנגדו שהוא קו הימין. וצמצום הזה בא בכאו\"א בשני אופני', הא' לאורך ורוחב שהוא ממזרח למערב, והב' לימין ושמאל שהוא צפון ודרום כידוע, והן ב' המצרים לד' צדדי' וב' המצרי' למעלה ולמטה וכל אלה הששה מצרים באין בג' הקוין גם בקו האמצעי דת\"י, שהרי גם קו האמצעי אעפ\"י שכולל לב' הקוין חח\"נ ובג\"ה מ\"מ גם בחי' התכללות הזאת באה במדה ושיעור קצוב בגדר וגבול ששה מיצרים הנ\"ל בב' הקוין. כי הנה מאמר קו המדה שנמשך מחיצוני' הכתר הוא המחלק לג' הקוין בשוה וכמ\"ש בפרד\"ס בשער הצינורות. ויובן זה גם באדם התחתון כמו מדת הרחמים שכלולה מחו\"ג הנה הגם שכולל בעצמו ב' הפכים",[["1562","50","<b>מ\"ש בזוהר ע\"פ ועבד הלוי הוא</b>: זח\"ג קעח, ב."],["1563","51","<b>וכמ\"ש במ\"א בפי' הקדוש ב\"ה</b>: ראה לקו\"ת תזריע כב, ג. [וראה לקמן בהוספות ד\"ה קמיפלגי ברקיע]."],["1564","52","<b>וד\"ל)</b>: בהכת\"י חסר התחלת המוסגר."],["1565","53","<b>כמ\"ש בתקונים דאוא\"ס מלגאיו</b>: ת\"ז סוף תי' כב."],["1566","54","<b>וכמ\"ש בע\"ח דבחי' הכתר נק' ממוצע</b>: שער מ\"ב פ\"א. ובכ\"מ."],["1567","55","<b>עפ\"י מאמר קו המדה</b>: ראה זח\"א טו, א. ת\"ז תי' ה. לקו\"ת נשא כז, ג. ביאוה\"ז נז, ד. ובכ\"מ."]]],[2101000254,"מ\"מ יש שיעור קצוב למדה זו כי גם שמדה\"ר הוא לאחר שחייבה מדה\"ד לעונש מ\"מ מצד מדת הרחמנות יפטר מן העונש וכיוצא, וא\"כ ה\"ז המתקת הדין בחסד ורחמים, הנה אעפ\"כ יש שיעור וגבול להמתקה זו, כי לפעמים אנו רואים שלא תספיק מדה\"ר להמתיק למדה\"ד כמו כאשר יגברו העוונות יותר מדאי וכיוצא ועכ\"פ יש מזה קציבה במדה\"ר כמה יהי' כחה להמתיק למדה\"ד כו', לפי שגם מדה\"ר נמדדה בשיעור קצוב מלמעלה מעצמות המאציל כמו שנמדד החסד דקו הימין ומדה\"ד דקו השמאל, ויש לו שיעור למעלה ולמטה ולד' צדדין כמו בב' הקוין כנ\"ל, רק שהוא באופן הממוזג משני הקוין כו', ועד\"ז אור הדעת הכולל לחו\"ב כו'. אבל הנה בחי' פנימית הכתר שלמעלה מבחי' ההתחלקות לג' קוין הוא הנק' נחלה בלי מצרים כנ\"ל והוא הנק' רחמים רבים, פי' רבים בלי שיעור וגבול לא למעלה ולא למטה ולא לד' צדדים כו'. והענין הוא כי בחי' פנימי' הכתר מאיר בו מבחי' עצמות אור המאציל, שע\"ס דאצי' גנוזים שם בתכלית היחוד באא\"ס עצמו וכמ\"ש למעלה בפי' אנת הוא חד בעצמותך וכל מדה וספי' דשם אינו בא במדה ושיעור כלל כמ\"ש לתבונתו<sup data-n=\"1568\">56</sup> אין חקר כי הוא המדע והוא<sup data-n=\"1569\">57</sup> הידוע כו', וכן לגדולתו<sup data-n=\"1570\">58</sup> אין חקר כו' וכמ\"ש ולא בחושבן, וכדמפרש ואזיל חכים ולא בחכ' ידיעה כו' עד לאו דאית לך צדק ידיעא כו', וכמ\"כ מדת הרחמים דשם הכלולה מחו\"ג דעצמות המאציל נק' רחמים רבים פי' מפני שמתפשטת בלתי מיצר וגבול כלל וכמו שמדת הרחמים שבאצי' ממתקת למדה\"ד במדה ושיעור כנ\"ל כך מדת ר\"ר שבעצמות המאציל ממתקת למדה\"ד בלי שיעור וגבול, והוא כענין מאריך לרשעי' כמו לצדיקים (וכמ\"ש טוב<sup data-n=\"1571\">59</sup> ארך אפים מגבורה דקו השמאל). וכן ענין שאנו אומרי' יה\"ר מלפניך שיכבשו רחמיך את כעסך, ואין הכונה על הרחמים שבאה באצי' במדה אלא על בחי' רחמים רבים הנ\"ל שיכבשו לכעס ודין שבא מלמעלה שנק' כעסך כו', והוא הנק' נחלה בלי מצרים, פי' בלי מצרים דמעלה ומטה וד' סטרין שבקוין דאצי'. והוא שרש מדתו של יעקב, וכמ\"ש והאכלתיך נחלת יעקב אביך, משום דקו האמצעי אעפ\"י שבא למטה במדה כמו ב' הקוין כנ\"ל מ\"מ שרשו למעלה יותר מגיע בפנימי' הכתר שמקבל מבחי' עצמי' המאציל מאחר שנק' בריח התיכון המבריח מן הקצה לקצה, פי' מקצה היותר עליון שבפנימיות הכתר עד קצה היותר תחתון למטה מב' הקוין. כי מאחר שאין לו שיעור למעלה בבחי' ר\"ר הנ\"ל ממילא אין לו שיעור בהתפשטו' למטה מטה גם לאחר כלות כח קו הימין כמו למחול ולסלוח גם לעוברי רצונו מאד שאין מדת החסד וגם לא מדה\"ר שבאצי' מספיק להמתיק מדה\"ד הקשה אשר עליהם. אבל ע\"י בחי' הר\"ר הנ\"ל תהפוך גם הזדונות כזכיות כמ\"ש מחוק ברחמיך הרבים כו'. והוא שרש ענין י\"ג מדה\"ר שנמשכין בי\"ג ת\"ד בר\"ה ויו\"כ, שהוא המשכת פנימי' הכתר דוקא כמ\"ש ועתה<sup data-n=\"1572\">60</sup> יגדל נא כח אד' כו' אל<sup data-n=\"1573\">61</sup> רחום וחנון כו' ויעבור<sup data-n=\"1574\">62</sup> ה' על פניו",[["1568","56","<b>לתבונתו אין חקר</b>: ראה ישעי' מ, כח."],["1569","57","<b>הוא המדע והוא הידוע</b>: ראה רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. מו\"נ ח\"א פס\"ח. שמונה פרקים פ\"ח. תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["1570","58","<b>לגדולתו איו חקר</b>: תהלים קמה, ג."],["1571","59","<b>טוב ארך אפים</b>: משלי טז, לב."],["1572","60","<b>ועתה יגדל נא כח אד'</b>: במדבר יד, יז."],["1573","61","<b>אל רחום וחנון</b>: כ\"ה בהכת\"י. וראה במדבר שם."],["1574","62","<b>ויעבור ה' על פניו ויקרא</b>: שמות לד, ו."]]],[2101000255,"ויקרא ה' ה' אל רחום כו', וז\"ש אנוכי אנוכי הוא מוחה פשעיך<sup data-n=\"1575\">63</sup> כו' למעני וכמ\"ש במ\"א וד\"ל.\n<b>וזהו</b> פי' תתן<sup data-n=\"1576\">64</sup> אמת ליעקב, פי' אמ\"ת א' פנימית הכתר שנק' אלופו ש\"ע הנאצל כו', והמ\"ם הוא האמצעי דכ\"ב אותיות, והתי\"ו הוא הסוף ורת\"ס הוא אותיות אמ\"ת הכולל כל קו האמצעי כו'. ובי\"ג תיקונין נחשב תיקון ואמ\"ת תיקון הז' שע\"י נמשך הארת תרין תפוחים דא\"א כמ\"ש יאר<sup data-n=\"1577\">65</sup> ה' פניו כו' שהוא הכולל לי\"ג מדה\"ר הבאים מבחי' הארת פנים דא\"א שהוא בחי' פנימי' הכתר בכלל כידוע. וזהו תתן אמת ליעקב, פי' שתתפשט בחי' רחמים הרבים שבפנימי' הכתר לכל אורך הקו האמצעי דיעקב שנק' בריח התיכון כנ\"ל עד למטה מטה מאד גם למחול לעוברי רצונו כנ\"ל, והוא כח יותר גדול מחסד לאברהם שנמשך בשרש הקו הימין חח\"נ שהוא נק' חסד דאברהם<sup data-n=\"1578\">66</sup> אבר מ\"ה כו' כי הרי הוא נק' נחלה בלי מצרים. וז\"ש והאכלתיך נחלת יעקב אביך דוקא, שמתפשטת למטה עד אין שיעור. והוא ענין התי\"ו דאמ\"ת שהוא בחי' ת\"ת ומל' שמתפשטי' ומשפיעי' לבי\"ע הארת י\"ג מדה\"ר עד שגם מחי' מתים בר\"ר. וז\"ש והתוית<sup data-n=\"1579\">67</sup> תיו על מצחות האנשים כו' (וע\"ז רמזו רז\"ל יעקב<sup data-n=\"1580\">68</sup> לא מת כו' וד\"ל). אך הנה מהיכן יהי' התעוררו' המשכת בחי' רחמים רבים הנ\"ל שנמשך ע\"י בחי' הממוצע הנ\"ל שהוא בחי' כתר עליון שע\"ז נאמר תתן אמת ליעקב נחלה בלי מצרים כנ\"ל, הנה הוא דוקא ע\"י העלאת מ\"נ מלמטה שנק' בחי' מים<sup data-n=\"1581\">69</sup> תחתונים בוכים ונק' מי בוכים מפני שרוצים להעלות ולהכלל ג\"כ למעלה באור פני מלך חיים ואו' אנן בעינן למהוי קדם מלכא כידוע והיינו בחי' העלאה של האותיות האלקיי' שנפלו וירדו למטה מטה מאד (והיינו ענין את כל הארץ בהעלאת האותיות דא' עד תי\"ו שירדו בכל הארץ כו'). ועי\"ז מתעורר למעלה בעצמות המאציל בחי' ר\"ר הנ\"ל כמשל הבן שנפל בידי האויב בשבי כאשר יוצא חפשי מבית השבי ובא אל אביו שמתעורר באב רחמים גדולים עד שירים קולו בבכי מרוב הרחמים (כמ\"ש במ\"א בענין בבכי<sup data-n=\"1582\">70</sup> יבואו כו' ולזה רמזו שהקב\"ה<sup data-n=\"1583\">71</sup> שאוג ישאג כו') כי מן הרחמים מסתעפת הבכי' כידוע, ועי\"ז נמשך אח\"כ בחי' המשכת מ\"ד בחכ' שנק' טפת אבא כו' ומאור אבא נמשך למל' כנ\"ל בפי' ברוך כבוד ה' ממקומו דאבא יסד ברתא, ומבחי' המל' נמשך לבי\"ע מקור כל המשכת מ\"ד שנמשך מאור אבא הוא מפני בחי' הרחמים רבים שבכתר שמתעורר ע\"י העלאת מ\"נ של האותיות שנפלו למטה מאד. וז\"ש תתן אמת ליעקב, בחי' ר\"ר שמתעורר ע\"י העלאת מ\"נ דמים תחתונים וד\"ל.",[["1575","63","<b>אנכי אנכי הוא מוחה פשעיך</b>: ישעי' מג, כה."],["1576","64","<b>תתן אמת ליעקב</b>: מיכה ז, כ."],["1577","65","<b>יאר ה' פניו</b>: במדבר ו, כה."],["1578","66","<b>דאברהם אבר מ\"ה</b>: ראה זח\"א ד, א. תו\"א מג\"א צ, א. לקו\"ת ר\"ה נו, ב."],["1579","67","<b>והתוית תו על מצחות האנשים</b>: יחזקאל ט, ד."],["1580","68","<b>יעקב לא מת</b>: תענית ה, ב."],["1581","69","<b>מים תחתונים בוכים</b>: ת\"ז תי' ה. תוס' הרא\"ש בראשית בתחילתו."],["1582","70","<b>בבכי יבואו</b>: ירמי' לא, ט."],["1583","71","<b>שהקב\"ה שאוג ישאג</b>: ירמי' כה, ל. וראה ברכות ג, א. ובכ\"מ."]]],[2101000256,"<b>וזהו</b> פי' רננו<sup data-n=\"1584\">72</sup> צדיקים בה'. ולכאורה יש לתמוה למה אמר לשון רננה דוקא הל\"ל שמחו צדיקים בה'. אך הענין הוא כמ\"ש<sup data-n=\"1585\">73</sup> בזהר ההפרש בין רננה לחדוה ושמחה, דרננה ברמשא וחדותא בצפרא. לפי ששרש הרננה הוא מבחי' הגבורות דאו\"ח ע\"כ עיקרו ברמשא, אבל החדוה שרשו מבחי' החסדי' דאו\"י ע\"כ עיקרו בצפרא שהוא בחי' חסד דאברהם כידוע. וביאור הדברים ידוע שבחי' העלאת מ\"נ מלמטה למעלה הוא בא בבחי' הגבורות שהוא כמו קול רחמנות ובכי' כמו מים תחתוני' בוכים כו' כנ\"ל להיותו עומד למטה בהסתר וחושך מאד וכאשר יחפוץ לעלות ולחזות בזיו האור העליון הרי תשוקתו באה בבחי' רחמנות ושפלות גדולה כמו קול העני ונדכה או קול יתום ואלמנה דכתיב בהו והי'<sup data-n=\"1586\">74</sup> כי יצעק אלי ושמעתי כי חנון אני כו' וכיוצא. והוא הנק' רננה שהוא קול של מרירות, אבל החדוה שרשו בבחי' החסדי' היורדים מלמעלה למטה, והוא בחי' המשכת מ\"ד היורד מגבוה לנמוך שהוא בקול שמחה, וע\"כ הוא בצפרא כנ\"ל. אך הנה כאשר כבר עלה התחתון ונתקרב לגבי העליון אזי מתערב החדוה עם המרירות יחד, כי בחי' הקירוב שנעשה אחר הריחוק נק' בכי' של שמחה ומרירות כולם יחד כי הבכי' באה מצד הריחוק שקדם והשמחה מצד הקירוב כו' וכמ\"ש במ\"א. וזהו רננו צדיקים בה', פי' צדיקים היינו בחי' צד\"ע ובחי'<sup data-n=\"1587\">75</sup> צד\"ת שהן יוסף ובנימין, יוסף הוא בחי' צד\"ע דהיינו בחי' יסוד ז\"א שהוא בחי' התקשרות המשפיע במקבל ע\"י המשכת מ\"ד שהוא בחי' החדוה והעונג. ובחי' צד\"ת הוא בחי' התקשרות המקבל במשפיע ע\"י העלאת מ\"נ בקול מרירות כנ\"ל, והוא בחי' בנימין ב\"ן אונ\"י לשון אונן כו'. וכאשר יפגשו יחדיו העליון בירידה והתחתון בעלי' אז נאמר רננו צדיקים בה', כי בחי' שמחה של הקירוב והמרירות שמחמת הריחוק הקדום מתכללים יחד והוא עיקר ענין הרננה שממוזג מחדוה ומרירות יחד והוא קול רחמים שכלול מחו\"ג, והיינו שאמר רננה ברמשא שהוא מדתו של יעקב כידוע וד\"ל. (וזהו שאמר רננו בשני הצדיקים צד\"ע וצד\"ת כי שניהם מתכללים החדוה של הקירוב עם המרירות של הריחוק כמ\"ש במ\"א בפי' ויבכו<sup data-n=\"1588\">76</sup> איש את רעהו כו' וד\"ל).\n<b>ובכל</b> הנ\"ל יובן שרש ענין הפסוק ואולם חי אני וימלא כבוד ה' את כל הארץ. למה אמר לשון להבא הלא גם עכשיו נאמר מלא כה\"כ כו'. כי הנה תחלה י\"ל שרש ענין טעות המרגלים שאמרו כי<sup data-n=\"1589\">77</sup> חזק הוא ממנו כבי' אפי' בעה\"ב אינו יכול להוציא כליו כו' כידוע. דהנה ידוע בענין בחי' יחו\"ת דמל' דאצי' שמתלבשת בבי\"ע הנק' בחי' ממכ\"ע דהיינו כדמיון התלבשות הנפש בגוף שהגוף יחי' מחיי הנפש הרוחניות, ויש ערך וקירוב לחיות הגוף עם חיות הנפש עד שהנפש תתפעל גם היא ממאורעות הגוף, הגם שאין הארת חיות הנפש בגופה רק בחי' הארה בעלמא ממנה",[["1584","72","<b>רננו צדיקים בה'</b>: תהלים לג, א."],["1585","73","<b>כמ\"ש בזוהר. . דרננה ברמשא וחדותא בצפרא</b>: זח\"א רכט, ב."],["1586","74","<b>והי' כי יצעק אלי ושמעתי</b>: שמות כב, כו."],["1587","75","<b>בחי' צד\"ע ובחי' צד\"ת שהן יוסף ובנימין</b>: זח\"א קנג, ב. וראה תו\"א תרומה פ, ד. לקו\"ת ראה כה, ד. יהל אור ע' קכ."],["1588","76","<b>ויבכו איש את רעהו</b>: שמואל-א כ, מא."],["1589","77","<b>כי חזק הוא ממנו כבי' אפי' בעה\"ב</b>: במדבר יג, לא. סוטה לה, א. ועוד."]]],[2101000257,"שהוא רק בחי' גילוי העצם כידוע, מ\"מ ע\"י בחי' גילוי הזה תתייחס בערך והשתוות להתפעל מהתפעלות הגוף. ולמעלה יובן הדוגמא מזה ג\"כ בבחי' השפעה האלקי' בג' עולמות בי\"ע וכמ\"ש ואתה<sup data-n=\"1590\">78</sup> מחי' את כולם והוא הנק' כח הפועל האלקי בנפעלים שמתלבש בתוך תוכם בבחי' התלבשות ממש ונק' שכינה מפני ששוכן ומתלבש ממש בעולמות. אך הנה כ\"ז הדמיון אינו אלא לענין בחי' התלבשו' כח האלקי דמל' דאצי' בפנימיות הג' עולמות דבי\"ע דהיינו בבחי' ע\"ס דבי\"ע באורות וכלים והיכלות ולבושים כו', אבל בחי' כח השפע' האלקי' הנשפע לע\"ש דנוגה דבי\"ע שמקבלי' מבחי' אחוריי' וחיצוניות דכלים ולבושים דע\"ס דקדושה וכידוע וכמ\"ש ומלכותו<sup data-n=\"1591\">79</sup> בכל משלה וכן כתיב מלך<sup data-n=\"1592\">80</sup> אלקים על גוים כידוע, הנה א\"א לדמותו לבחי' התלבשות הנפש בגוף שיש להם ערך כנ\"ל, כי הרי נאמר וכבודי<sup data-n=\"1593\">81</sup> לאחר לא אתן וכמ\"ש<sup data-n=\"1594\">82</sup> בזוהר וכן כתיב לא<sup data-n=\"1595\">83</sup> יגורך רע לא יגור במגורו כו' אלא הדמיון הוא כמו התלבשות הנשמה האלקי' בחומר נפש החיונית הבהמית דהנה ידוע שטבע נה\"ב למשך אחר כל גשמיות כבהמה ממש כמו אחר כל תאוות גשמיות כמו<sup data-n=\"1596\">84</sup> רוח הבהמה הגשמיות שיורדת למטה כו', אבל הנשמה נק' ניצוץ האלקי שעולה לידבק באלקות כמ\"ש כי רוח האדם העולה כו', ואין להם ערך וקירוב כלל זע\"ז, ועכ\"ז הנשמה האלקי' מלובשת בנה\"ב. וכאשר הנפש החומריות תמשך אחרי גשמיות אזי בהכרח שגם הנשמה האלקי' תתלבש שם שרחוקה לגמרי מדברי תאוות גופניי' ואינה מבחי' וסוג גשמיות כלל אך היא מתלבשת שם בבחי' גלות ומאסר כמו האיש שאסור בבית השבי' וכמ\"ש מלך<sup data-n=\"1597\">85</sup> אסור ברהטים כו'. ולפעמים אור הניצוץ האלקי גובר על הנפש החומריות ותבטל ותכניע המשכת החומריות. ולפעמים בהיפך שהנפש הבהמי' גוברת ותכניע לאור הניצוץ האלקי שיסבול גם הוא החומריות. אבל אין הנפש האלקי' מתפעלת מהתפעלות התאות החומריות כלל לא כהתפעלו' הנפש החיונית ממאורעות הגוף כנ\"ל רק שהיא בגלות וסובלת את הגשמיות, ויהי' איך שיהי' מלובשת הניצוץ האלקי בתוך החומריות דנה\"ב כשהיא גוברת עליה כמ\"ש ולאום<sup data-n=\"1598\">86</sup> מלאום יאמץ כו'. והדמיון מזה למעלה יובן שכדרך זה של התלבשות הנשמה האלקי' כך הוא בחי' התלבשות כח שפע האלקי בע\"ש דנוגה דבי\"ע שנק' רוח הבהמה היורדת למטה כמ\"ש רגליה<sup data-n=\"1599\">87</sup> יורדות מות, ובחי' החיות האלקי המחי' אותם הוא כמו התלבשות הניצוץ האלקי בנפש החומריות ונק' רוח האדם. ולפעמים יגבר כח רוח האדם דקדושה ויכניע ויברר לחומריות דנוגה דבי\"ע, והוא בחי' שם ב\"ן הנק' אדם תתאה שמברר לנוגה, ולפעמים להיפך שגוברים יניקת הע\"ש, ואז כתיב מלך אסור ברהטים כו' כמשל הגלות והשבי', והוא שרש ענין גלות השכינה דכתיב עת<sup data-n=\"1600\">88</sup> אשר",[["1590","78","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1591","79","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["1592","80","<b>מלך אלקים על גוים</b>: תהלים מז, ט."],["1593","81","<b>וכבודי לאחר לא אתן</b>: ישעי' מב, ח. מח, יא."],["1594","82","<b>וכמ\"ש בזוהר</b>: זח\"ג ערה, ב ואילך."],["1595","83","<b>לא יגורך רע</b>: תהלים ה, ה. וראה לקו\"ת במדבר ג, ג."],["1596","84","<b>כמו רוח הבהמה</b>: ראה קהלת ג, כא."],["1597","85","<b>מלך אסור ברהטים</b>: שה\"ש ז, ו."],["1598","86","<b>ולאום מלאום יאמץ</b>: בראשית כה, כג."],["1599","87","<b>רגליה יורדות מות</b>: משלי ה, ה. וראה לקו\"ת שה\"ש נא, ב. ובכ\"מ."],["1600","88","<b>עת אשר שלט האדם באדם לרע לו</b>: קהלת ח, ט. וראה זח\"ב צה, ב. פרדס שט\"ז פ\"ז."]]],[2101000258,"שלט האדם באדם לרע לו, דהיינו שליטת אדם בליעל דרוח הבהמה באדם דקדושה והוא לרע לו כדי שיבורר מנוגה כל ניצוצות העליונו' דתוהו שנפלו בהם כידוע וד\"ל.\n<b>והנה</b> טעות המרגלים הי' שכח האלקי הנשפע בע\"ש הגם שאינו בקירוב גמור כמו הנפש בגוף משום דכתיב וכבודי לאחר לא אתן כנ\"ל, אבל מ\"מ כמו התלבשות הנשמה האלקי' בנה\"ב שוכן בהם ומחיה אותם בהתלבשות זאת בסוד גלות כנ\"ל, וא\"כ יכול להיות שעד שיובררו כל הרפ\"ח ניצוצות דתוהו דנוגה דבי\"ע הנה כעת שולטים הם וגוברים על בחי' אדם דקדושה כמו דמיון התגברות הנפש הבהמיו' על רוח ניצוץ האלקי וכמ\"ש עת אשר שלט האדם באדם כו'. ועיקר טעם השליטה הזאת היינו מפני כח אלקי היותר עליון שנפל בהם בבחי' שבה\"כ, והן רפ\"ח ניצוצות וכמ\"ש ורוח<sup data-n=\"1601\">89</sup> אלקים מרחפת רפ\"ח כו', והיינו בחי' אורות דתוהו שהן אורות חזקים ביותר להיותם מבחי' הגבורות שבא האור והשפע בתגבורת גדולה, וכאשר נפלו וירדו למטה נעשי' מהם בחי' גבורות קשי' דנוגה שנק' תקיפי<sup data-n=\"1602\">90</sup> דרא וכמ\"ש במ\"א באריכות. וזהו שטענו המרגלים כי חזק הוא ממנו כבי' אפי' בעה\"ב אינו יכול להוציא את כליו כו', פי' בעה\"ב הוא בחי' אדם דאצי' שיורד ומתלבש למטה בבי\"ע וכמ\"ש כתפארת<sup data-n=\"1603\">91</sup> אדם לשבת בית כו', וע\"כ נק' בעה\"ב כו'. ובחי' רפ\"ח ניצוצות דתוהו שנפל בנוגה הוא הנק' בחי' כליו של בעה\"ב ואינו יכול לבררם ולהוציאם מבחי' נגה דהיינו להביאם מרה\"ר טורי דפרודא לרה\"י דקדושה מפני ששלט האדם באדם כמ\"ש מלך<sup data-n=\"1604\">92</sup> אסור ברהטי' ברהיטי מוחין כו', וכמו דמיון התגברות הנה\"ב על הנה\"א. וז\"ש כי חזק הוא ממנו, פי' כי בחי' הגבורות דנוגה חזקים ותקיפים יותר מאור דתיקון דאדם דקדושה, וזהו ממנו כבי' מצד שרשם בתוהו שחזק הוא מבחי' התיקון (והמופת ידוע מאשר אנו רואים שעל הלחם יחי' האדם כו' וכמ\"ש במ\"א וד\"ל). אך הנה כלב בן יפונה אמר להם שטעו בזה טעות גמורה. כי הנה באמת א\"א שיקבלו החיצוני' יניקה מכח האלקי גם לא בבחי' ריחוק הערך כמו התלבשו' הנשמה בנה\"ב שמ\"מ הרי מלובש בתוכם כו' וכתיב וכבודי לאחר לא אתן כלל אלא ההשפעה שנשפעת עליהם מאור וכח האלקי נמשך בבחי' מקיף בהעלם מרחוק מאד בלתי יבא האור והחיות האלקי בהן בבחי' התלבשו' בבחי' פנימי' כלל וכלל, ולכך אוה\"ע הגם דקרו<sup data-n=\"1605\">93</sup> לי' אלקא דאלקי' כו' אעפ\"כ אינו מושג ונודע כלל בשכלם והשגתם כמו בישראל דכתיב נודע<sup data-n=\"1606\">94</sup> ביהודה כו' ולכך נאמר רם<sup data-n=\"1607\">95</sup>",[["1601","89","<b>ורוח אלקים מרחפת רפ\"ח כו'</b>: בראשית א, ב. ע\"ח שי\"ח פ\"א. ועוד. לקו\"ת להאריז\"ל (ושעה\"פ וס' הלקוטים) עה\"פ. וראה תו\"א וישב כז, ד. לקו\"ת מטות פב, ד. ביאוה\"ז קט, ד."],["1602","90","<b>תקיפי דרא</b>: ראה חגיגה יד, רע\"א. וראה סה\"מ תקס\"ח ע' רכג. תו\"ח בראשית טז, ב. שם שמות תקמ, ב. ובכ\"מ."],["1603","91","<b>כתפארת אדם לשבת בית</b>: ישעי' מד, יג."],["1604","92","<b>מלך אסור ברהטים ברהיטי מוחין</b>: שה\"ש ז, ו. וראה ת\"ז תי' ו' בתרא (קמד, ב). תניא פמ\"ה. אגה\"ת פ\"ז."],["1605","93","<b>דקרו לי' אלקא דאלקייא</b>: סוף מס' מנחות."],["1606","94","<b>נודע ביהודה</b>: תהלים עו, ב."],["1607","95","<b>רם על כל גוים</b>: תהלים קיג, ד. וראה ג\"כ תו\"א מקץ לד, ד. וארא נו, א. תו\"ח שמות צג, א. ובכ\"מ."]]],[2101000259,"על כל גוים, מפני שעל הגויים דע\"ש הוא מאיר ברחוק בהעלם גדול ע\"כ הוא רם ומתנשא מהם בבחי' הסתלקות כו' (וגם הנביאים שבאוה\"ע כבלעם וכיוצא לא השיגו אלקות מקרוב אלא בבחי' העלם וכמ\"ש בו נופל<sup data-n=\"1608\">96</sup> וגלוי עינים וכמ\"ש בזוהר).\n<b>וזהו</b> שאמר להם כלב סר<sup data-n=\"1609\">97</sup> צילם מעליהם כי לחמינו הם כו', פי' צילם הוא בחי' ההארה האלקי' שמאיר עליהם מרחוק בהעלם כמו הצל על הארץ ונק' צל זה בחי' מקיף, והוא<sup data-n=\"1610\">98</sup> מ\"ש בע\"ח בענין י\"א סממני הקטורת דהלבונה הוא בחי' או\"מ שמאיר עליהם מרחוק כו' (וכמ\"ש במ\"א בענין מארז\"ל דבבואה דבבואה<sup data-n=\"1611\">99</sup> לית להו שנק' צל דצל רק צל א' כו'), ובהסיר בחי' הצל המקיף הזה יסור מהם צל אדם לגמרי ונמשלו לבהמות ממש כמו האדם שרודה בבהמה וניתנה לו למאכל. וזהו שאמר לחמינו הם כו' (וכמו הלחם דגם ששרשו מבחי' התוהו מ\"מ מתברר ומתעלה ע\"י האדם האוכלו כך יוסר מהם צל דאדם לגמרי מפני שלא יהי' מאיר בהן הארת המקיף דקדושה ואז ממילא אחד ירדוף אלף כמו אלף בהמות שאיש א' רודפם, ואז נק' לחמינו רק כמו הלחם שע\"י יתחזק כח השכל בלבד והיינו לאחר בירורי' דרפ\"ח ניצוצות דתוהו מהם לגמרי וכמ\"ש חיל<sup data-n=\"1612\">100</sup> בלע ויקיאנו, וה\"ז כדמיון התגברו' הנשמו' על רוח הבהמה עד שהיא בגלות כמו הבהמה ביד האדם כו' וד\"ל).\n<b>וזהו</b> ואולם חי אני לשון שבועה כמ\"ש נשבע<sup data-n=\"1613\">101</sup> ה' בנפשו שהוא בחי' מל' דא\"ס מקור הראשון דמדת ההתנשאו' דמל' דאצי' כאשר תאיר למטה כמו למעלה ממש וכמ\"ש גלה כבוד מלכותך עלינו ממש, והיינו לאחר שיבוער רוח הטומאה לגמרי ויבוררו כל הניצוצי' דתוהו מנוגה ויבואו ליחוד העליון דקדושה אזי ימלא כבוד ה' את כל הארץ גם באותיו' דא' עד תי\"ו שירדו ונפלו למטה שנק' מי בוכים כנ\"ל. משא\"כ עכשיו דהגם שמלא כה\"כ מבחי' מל' דאצי' אבל מ\"מ יש מקום עדיין ליניקת החיצוני' בבחי' מקיף והעלם עכ\"פ ולא נברר מהם בחי' הטוב לגמרי רק שמלך אלקים על גוים בממשלה, ולא שנבררו בתכלית. וע\"כ או' וימלא לשון להבא דקאי לעתיד באלף הז' לאחר תשלום כל הבירורי'. ואע\"פ שהמרגלי' טעו בענין התלבשו' פנימי' מ\"מ גם לפי האמת כמו שהשיבם כלב דסר צילם לא נברר מהם לגמרי עד לעתיד כו' וד\"ל.",[["1608","96","<b>נופל וגלוי עינים וכמ\"ש בזוהר</b>: במדבר כד, ד. טז. וראה זח\"א פח, ב. צא, א. זח\"ב סט, א. קיב, ב. ובכ\"מ."],["1609","97","<b>סר צלם מעליהם כי לחמנו הם</b>: ראה במדבר יד, ט."],["1610","98","<b>והוא מ\"ש בע\"ח בענין י\"א סממני הקטורת</b>: פע\"ח שער עולם העשי' פ\"ד. ובכ\"מ. וראה אוה\"ת תולדות קנב, א ואילך."],["1611","99","<b>בבואה דבבואה לית להו</b>: יבמות קכב, א."],["1612","100","<b>חיל בלע ויקיאנו</b>: איוב כ, טו. וראה תו\"א תולדות כ, ג. אוה\"ת שם קנד, א. שערי אורה פו, ב ואילך. ובכ\"מ."],["1613","101","<b>נשבע ה' בנפשו</b>: עמוס ו, ח. וראה זח\"א פז, א."]]],[2101000260,"<h3>עולת תמיד</h3>\n<b></b><b>בעזר\"ה שבת<sup data-n=\"1614\">1</sup> מברכים תמוז</b>\n<b>עולת</b><sup data-n=\"1615\">2</sup> תמיד העשוי' בהר סיני<sup data-n=\"1616\">3</sup> לריח ניחוח אשה לה'. הנה י\"ל מהו העשוי' בהר סיני דמשמע שהוכנה קרבן עולת תמיד מכבר במעמד הר סיני. ולכאורה פ' התמיד נאמר אחר מעמד הר סיני כידוע, וגם מהו לריח ניחוח וכי יתכן שריח קרבן חלב ודם גשמי יעלה לבחי' ריח ניחוח למעלה שאין להקב\"ה גוף ולא דמות הגוף ולא מתוארי הגוף, ואיך יריח ריח ניחוח מהקטר חלב ודם שאינו ריח טוב גם לאדם הגשמי כידוע. אך תחלה יש להקדי' ענין הידוע בפי' מארז\"ל דקודם<sup data-n=\"1617\">4</sup> שנבה\"ע הי' הוא ושמו בלבד, פי' שמו הוא בחי' התגלות אור וזיו בלבד מעצמותו כבי'<sup data-n=\"1618\">5</sup> עד\"מ שמו של אדם שאינו מבחי' עצמותו רק שנתפס לקרות אותו ע\"י השם, כך בחי' שמו של א\"ס ב\"ה אינו אלא בחי' אותיות התגלות עצמותו כדמיון זיו השמש ואורו שאינו נחשב מעצמות מאור השמש רק שנגלה העצם באותו הזיו ונק' התגלות שלו בלבד שעי\"ז נתפס למראה בעין כל, וכך השם אינו אלא להתפס לזולתו לקוראו בלבד כנ\"ל וממילא מובן שאין בחי' ההתגלות עושה שום שינוי בהעצמות, וכך למעלה לא יעשה בחי' זיו ואור דא\"ס ב\"ה שום שינוי בעצמותו כבי' וז\"ש אני<sup data-n=\"1619\">6</sup> ה' לא שניתי כו' (ומה<sup data-n=\"1620\">7</sup> שאומרים אתה הוא משנברא כו' דכמו שקודם שנבה\"ע ונאצל כו' הי' הוא ושמו בלבד הכל בבחי' א\"ס כך גם לאחר ההשתלשלו' מבחי' הקו כו' הוא ושמו בלבד וכמ\"ש בע\"ח דבחי' מל' דא\"ס שלפני הצמצום הראשון הנק' מקו\"פ כו' שנק' שמו העצמי בכלל גם אחר הצמצום נמשך האור בבחי' קו כו' הארת מל' דא\"ס מאיר לכל ההשתלשלות ונוגע לכולם בשוה וא\"כ גם בבחי' אור וזיו דא\"ס אין שינוי כלל, וזהו אתה הוא משנברא, פי' אתה בחי' התגלות אותיות שמו שנאמר בו אתה ה' לבדך גם עכשיו כמו קודם שנברא ונאצל כו'. (ובזה יובן יותר פי' מלך<sup data-n=\"1621\">8</sup> משובח ומפואר עדי עד שמו הגדול, משום דגם בבחי' אור וזיו דא\"ס שנק' שמו הגדול שהוא בחי' מל' דא\"ס ג\"כ הוא בבחי' א\"ס, וע\"כ משובח ומפואר בנ'<sup data-n=\"1622\">9</sup> אלפים יובלות כו' ואין לזה שיעור כלל, וז\"ש עדי עד בבחי' נצחיו' דא\"ס וד\"ל). וזהו מלך משובח ומפואר עדי עד שמו הגדול, פי' כי גם מקור כל תענוגי העוה\"ב בעליות העולמות דאבי\"ע עד נ' אלפים יובלות וגם בחי' יום שכולו שבת לאחר עליות הכלליות דנ' אלפים יובלות ג\"כ בטלים ונכללים כולם בבחי' שמו הגדול שהוא רק בחי' זיו ואור",[["1614","1","<b>שבת. . תמוז</b>: בכת\"י ב: שבת שמברכין ר\"ח אב."],["1615","2","<b>עולת תמיד</b>: נמצא בשינויים ובאריכות בס' מאמרי אדהאמ\"צ במדבר ח\"ה ע' א'תרסד. ובתוס' קיצורים והגהות באוה\"ת פינחס ע' א'קכה. בשינויים ותוס' הגהות באוה\"ת שם ע' א'קלז וע' א'קמ. ובשינויים באוה\"ת בלק ע' א'ד (ד\"ה לא הביט און ביעקב). קטע מהמאמר בשינויים ותוס' הגהות באוה\"ת שם כרך ה' ע' א'תרעט."],["1616","3","<b>עולת תמיד העשויה בהר סיני</b>: במדבר כח, ו."],["1617","4","<b>דקודם שנבה\"ע הי' הוא ושמו בלבד</b>: פדר\"א פ\"ג. וראה סה\"מ באתי לגני ח\"א ע' כד וע' ר. אוה\"ת יתרו ע' תתלט."],["1618","5","<b>כבי'</b>: בכת\"י ב וכת\"י ג: כו'."],["1619","6","<b>אני ה' לא שניתי</b>: מלאכי ג, ו."],["1620","7","<b>ומה שאומרים</b>: בכת\"י ב וכת\"י ג: וכמ\"ש."],["1621","8","<b>מלך משובח ומפואר עדי עד שמו הגדול</b>: ברכות פסוד\"ז. וראה סדור מד, א. פיה\"מ עח, ד. ובכ\"מ."],["1622","9","<b>בנ' אלפים יובלות</b>: ראה ג\"כ לעיל ע' צז. סה\"מ תקס\"ב ע' יז. תו\"א פא, ג. ובכ\"מ."]]],[2101000261,"דא\"ס עצמו כנ\"ל להיותו מרומם ומנושא מכל ההשתלשלו' דאבי\"ע, וכמ\"ש כי<sup data-n=\"1623\">10</sup> עמך מקור חיים פי' מקור כל התענוגים דעוה\"ב<sup data-n=\"1624\">11</sup> שנברא רק ביו\"ד כו' להיותו בבחי' א\"ס ממש כנ\"ל בפי' אני ה' לא שניתי כו', וזהו עדי עד בבחי' נצחיות דא\"ס בלי הפסק ושיעור כלל מטעם הנ\"ל וד\"ל. אך הנה במקום<sup data-n=\"1625\">12</sup> גדולתו ית' שם אתה מוצא ענוותנותו שירד וצמצם את אורו העצמי הנ\"ל הנק' שמו הגדול להיות נמשך ונגלה בבחי' השתלשלות עו\"ע להיות נק' חכים ומבין ורחמן כו', הגם שמצד עצמו' אא\"ס הנ\"ל לאו<sup data-n=\"1626\">13</sup> דאית בי' מכל אינון מדות כלל כי הוא אור פשוט בתכלית האחה\"פ כידוע, וז\"ש לך<sup data-n=\"1627\">14</sup> ה' הגדולה והגבורה כו' כידוע. אמנם ע\"י בחי' ריבוי צמצומים נמשך השפעת אא\"ס עד למטה מטה מאד, דהיינו עד בחי' מלכותו ית' להחיות רוח שפלים בע\"ג כמ\"ש מלכותך<sup data-n=\"1628\">15</sup> מכ\"ע כו' ומלכותו<sup data-n=\"1629\">16</sup> בכל משלה בירידות המדריגות עד שמהווה גם לבחי' הצומח ודומם הגשמי וכמ\"ש דאין<sup data-n=\"1630\">17</sup> לך עשב שאין לו מזל והמזל מקבל מעליון הימנו עד בחי' מל' דעשי' המהווה כל עולם העשי' ובמל' דעשי' מלובש מל' דיצי' ובמל' דיצי' מל' דבריאה ובמל' דבריאה מל' דאצי' עד בחי' מל' דא\"ס שנק' שמו הגדול שלפני כל ההשתלשלות כנ\"ל וד\"ל.\n<b>והנה</b> כדי להמשיך מבחי' שמו הגדול הנ\"ל שלמעלה מכל ההשתלשלות דקו\"ח כו' להיות נק' חכים ומבין כו' גדול וגבור כו' ומקור כל תענוגי העוה\"ב כנ\"ל עד למטה מטה כנ\"ל היינו ע\"י בחי' יעקב<sup data-n=\"1631\">18</sup> שנק' בריח התיכון המבריח מן הקצה לקצה כידוע (והוא בחי' קו האמצעי דת\"י שעולה עד הכתר בבחי' הפנימי' שבו ששם הארת אא\"ס עצמו מבחי' שמו הגדול הנ\"ל כמ\"ש בתיקונין אא\"ס<sup data-n=\"1632\">19</sup> מלגיו כתרא עילאה מלבר כו' ומבריח לקצה התחתון ג\"כ והוא עד בחי' נה\"י סוף העשי' כידוע).\n<b>וביאור</b> הדבר הנה כתיב לא<sup data-n=\"1633\">20</sup> יעקב יאמר עוד שמך כ\"א ישראל כו', פי' ישראל<sup data-n=\"1634\">21</sup> לי ראש כי ברא<sup data-n=\"1635\">22</sup> כרעא דאבוה הוא ומאחר שנאמר בני<sup data-n=\"1636\">23</sup> בכורי ישראל",[["1623","10","<b>כי עמך מקור חיים</b>: תהלים לו, י. וראה לקו\"ת ויקרא הוספות נא, ד. תו\"ח שמות תרמה, ב. ובכ\"מ."],["1624","11","<b>דעוה\"ב שנברא רק ביו\"ד</b>: מנחות כט, ב. ובכ\"מ."],["1625","12","<b>במקום גדולתו ית' שם אתה מוצא ענוותנותו</b>: ראה מגילה לא, א. והערת כ\"ק אדמו\"ר זי\"ע בסה\"מ ה'ש\"ת ע' 40. ליקוט פירושים ומ\"מ לתניא פ\"ד."],["1626","13","<b>לאו דאית בי' מכל אינון מדות כלל</b>: ראה ת\"ז בהקדמה ד\"ה פתח אליהו."],["1627","14","<b>לך ה' הגדולה והגדולה</b>: דהי\"א כט, לא."],["1628","15","<b>מלכותך מכ\"ע</b>: תהלים קמה, יג."],["1629","16","<b>ומלכותו בכל משלה</b>: תהלים קג, יט."],["1630","17","<b>דאין לך עשב שאין לו מזל</b>: ראה ב\"ר פ\"י, ו. זח\"א רנא, א. זח\"ב קעא, ב. זח\"ג פו, א. מו\"נ ח\"ב פ\"י. אגה\"ק ס\"כ."],["1631","18","<b>יעקב שנק' בריח התיכון</b>: ראה זח\"א א, ב. זח\"ב קעה, ב. ועוד. וראה אוה\"ת ויחי שצה, א."],["1632","19","<b>אא\"ס מלגאיו כתרא עילאה מלבר</b>: ת\"ז סוף תי' כב."],["1633","20","<b>לא יעקב יאמר עוד שמך</b>: בראשית לב, כט."],["1634","21","<b>ישראל לי ראש</b>: ראה דרמ\"צ טו, ב בשם הזוהר."],["1635","22","<b>ברא כרעא דאבוה הוא</b>: רש\"י כתובות צב, א ד\"ה כבע\"ח. תוס' יבמות ג, א ד\"ה מקמי. יונת אלם רפ\"ב. וראה עירובין ע, ב."],["1636","23","<b>בני בכורי ישראל</b>: שמות ד, כב. וראה תניא פ\"ב ובליקוט פירושים ומ\"מ שם."]]],[2101000262,"הרי הבן שרשו במוח האב והוא נק' כרעא דאבוה וזהו לי ראש כו'. והענין הוא להיות ידוע שיש ג' כחות באדם שנק' נר\"נ משכן הנשמה במוח והרוח בלב והנפש בכבד וג' כחות רוחניי' הללו הן בחי' כחות היולים לא כשאר הכחות שבאברי האדם שכל א' כח פרטי מצוצמם רק לפי ערך חיות אותו האבר בפרט בלבד, אבל ג' כחות הללו הן הנה בחי' כחות היולים דהיינו שכל א' מהם הוא כח היולי כללי שנכללים בו כמה מיני כחות של אברים פרטיי' ואינו בא עדיין בערך לבחי' ההתחלקות לפרטי ניתוח הכחות של האברים לכל א' כפי טבעו ומזגו רק כולן כא' כלולים בו בהעלם, אך אח\"כ מתחלקים ממנו ריבוי הפרטי' של האברי' בניתוח רוחני וגשמי בכל א' לפי טבעו, וזהו הנק' כח היולי כידוע (בטפה שנק' כח היולי להיותה כוללת כל פרטי התחלקות האברי' בהעלם גדול כו' כמ\"ש במ\"א). אמנם ג' כחות נר\"נ הנה היותר עליון נק' כללי יותר והתחתון הימנו נכלל בו ואינו כללי כ\"כ רק לכלול מה שמסתעפי' ממנו בלבד והתחתון הימנו נק' פרט לגביו והוא כללי ג\"כ אבל רק במיעוט היותר אחרון כמו דמיון ענפי האילן שהשרשי' הן הכלליי' לכל ענפי האילן והענפים שבאמצעו כוללים כל מה שיסתעף מהם וכן עד ענף היותר אחרון ומכח הצומח שבשרשי' יצמח הכל כו'. כך בחי' נר\"נ הנה בחי' הכח הראשון המקור הכולל הכל הוא הנשמה שבמוח שכל הכחות כלולים בה כידוע דגידי המוח מתפשטי' בכל האברי' וגם מה שהלב פליג חיות לכל האברי' נכלל במוח ונק' כח היולי הכללי יותר מכולם, ואחריו מסתעף כח היולי פרטי יותר והוא כח הרוח שבלב, אמנם הוא בחי' כח היולי כללי לכל החיות שבדם האברי' שלמטה הימנו המלובש בכבד והנפש הוא הדם שבכבד שולח חיות ג\"כ לכל האברי' אבל מקבל מן הלב תחלה והלב מקבל מן המוח, והן ג' כלים לנר\"נ בבחי' כחות היוליי' כלליי' וכאו\"א נכלל בעליון הימנו כנ\"ל בדמיון האילן וכמ\"ש כי<sup data-n=\"1637\">24</sup> האדם עץ השדה כו'. ונמצא מובן עכ\"פ מכ\"ז שע\"י משכן הנשמה אשר במוח דוקא שהוא כח ההיולי הכללי יותר מתפשט על ידו דוקא כל פרטי חיות הנפש עד ציפורן הרגל, ולפ\"ז הרי הנשמה שבמוח כמו בחי' ממוצע שע\"י יומשך מן כלל עצם הנפש להתמשך בכל פרט ופרט של ניתוח האברי' עד היותר אחרון כו'. וככל הדוגמא הזאת באדם שלמטה יובן בבחי' האדם העליון כמ\"ש על<sup data-n=\"1638\">25</sup> הכסא דמות כמראה אדם כו'. דהנה כתיב לכבודי<sup data-n=\"1639\">26</sup> בראתיו יצרתיו אף עשיתיו, שהן ג' מדריגות דנר\"נ הנ\"ל, נשמה בבריאה בחב\"ד שבמוח ורוח ביצי' ונפש בעשי', שמתלבשי' בג' כלים מוחא ולבא וכבדא כו' כנ\"ל (וכללות כולם הוא בחי' אדם דבריאה שנק' אדם קדמון ולמטה נק' אדה\"ר כו') וידוע בדרז\"ל דישראל<sup data-n=\"1640\">27</sup> עלו במח' שבמוחין חב\"ד כו' דהיינו בבחי' המוחין שבראש וז\"ש ישראל לי ראש וכמ\"ש בני בכורי ישראל כמו הבן ששרשו במוח האב כו', וע\"כ ע\"י נשמות ישראל בשרשם למעלה בבחי' נשמה שבמוחין העליונים נמשך הארת אא\"ס מבחי' שמו הגדול הנ\"ל (שהוא כדמיון אור הנפש עצמה באדם למטה) לכל ההשתלשלו' דקו כו' בבחי' התחלקות פרטי פרטיות עד סוף עולם העשי' אך שהולך ובא מכלל לפרט שלו כנ\"ל",[["1637","24","<b>כי האדם עץ השדה</b>: דברים כ, יט."],["1638","25","<b>על הכסא דמות כמראה אדם</b>: יחזקאל א, כו."],["1639","26","<b>לכבודי בראתיו יצרתיו אף עשיתיו</b>: ישעי' מג, ז."],["1640","27","<b>דישראל עלו במח'</b>: ב\"ר בתחילתו. ובכ\"מ."]]],[2101000263,"בג' מיני כחות דנר\"נ כו' דהיינו שנמשך מבחי' המוחין דא\"ק לבחי' רוח שביצי' שהן בחי' כללות המדות דאצי' ומשם נמשך לבחי' המל' שנק' נפש בכלל ועד\"ז מאצי' לבי\"ע הנה תחלה כללות ההארה מאיר בנשמת אדה\"ר ששרשו בבריאה (כמו בחי' א\"ק בכללות דבי\"ע כמ\"ש לכבודי בראתיו יצרתיו כו') וממנו מקבלים האבות שהן המרכבה לבחי' חג\"ת והוא בחי' רוח שביצי' ואח\"כ מתפשט בס\"ר נש\"י שכלולים בע' נפש דיעקב, ועד\"ז באצי' יש ג\"כ בחי' בי\"ע ובחי' הבריאה שבאצי' הוא בחי' א\"ק שבאצי' שהוא אור אבא או א\"א וע\"י ומשם נמשך אל האבות שהן בחי' חג\"ת דז\"א שהוא בבחי' יצי' ואח\"כ במל' דאצי' שכוללת ס\"ר נשמות, והן ע' נפש דיעקב וכידוע בפי' שמע שם ע' כו'. וזהו דרך כללות, ודרך פרטות יש בס\"ר נש\"י ג\"כ בחי' חב\"ד חג\"ת נה\"י והן שנק' ראשי בנ\"י או עיני העדה וכה\"ג. ויש נשמות שבבחי' מדות דיצי' ויש נשמות שבבחי' נפש דעשי' ונק' בחי' עקביי', ובכללות דא\"ק נק' עקבות משיחא, וכן בפרט בציור קומת אדם תתאה דמל' דאצי', וזהו בחי' יעקב עקביי' כרע' דאבוה שהן נשמות שבעקבות משיחא בבחי' עקביי' דא\"ק בכלל ושרשם במוחין לי ראש ולכך אמר לו לא יעקב יקרא שמך כ\"א ישראל לי ראש להיות שרשם הראשון הוא בחי' אדם דבריאה בחי' כח היולי הכללי יותר כנ\"ל, וע\"כ ע\"י נשמות ישראל דוקא נמשך מבחי' מל' דא\"ס שלפני הקו שנק' שמו הגדול עד למטה מטה בסוף בחי' העקביי' דעשי' וגם להיות בחי' תענוג גשמי בא\"י ארץ חטה ושעורה<sup data-n=\"1641\">28</sup> כו' בחי' ג\"ע דעשי' ממקור כל התענוגים דעוה\"ב שבבחי' מל' דא\"ס כנ\"ל. וזהו ענין יעקב שנק' בריח התיכון שמבריח מן הקצה לקצה כנ\"ל וד\"ל.\n<b>והנה</b> אמרו בזהר דתלת קשרין הן<sup data-n=\"1642\">29</sup> ישראל מתקשראן באוריי' ואוריי' בקוב\"ה כו' דהנה הגם שמבואר למעלה שע\"י שרש נש\"י שעלו במח' כו' הן כמו בחי' אמצעי להמשיך מבחי' עצמות אא\"ס ב\"ה בכל העולמות עדיין לא יובן דבר זה דהאיך אפשר להיות בחי' ממוצע מאחר ששרש נש\"י הוא רק בבחי'<sup data-n=\"1643\">30</sup> החכ' שבראש ובעצמו' אא\"ס אמרו לאו דאית לי' מכל אינון מדות כלל וכמ\"ש חכים ולא בחכ' ידיע' כו' וכמא' לית מחת\"ב (אפי' מח' דא\"ק כו') ואם מפני שאמר כל הנק' בשמי לכבודי כו' שהן שרש נש\"י כנ\"ל הרי אין זה רק בבחי' המוחין דחכ' כו' כנ\"ל. אך הנה ע\"ז אמר הטעם משום דתלת קשרין הן ישראל מתקשראן באוריי' ואוריי' בקוב\"ה כו', שיש עוד ממוצע למעלה שמחבר קוב\"ה וישראל והוא אוריי' דמתקשראה בקוב\"ה שהוא בחי' עצמו' אא\"ס שנק' שמו הגדול כנ\"ל, וזהו פי' ברוך<sup data-n=\"1644\">31</sup> ה' אלקי ישראל מן העולם ועד העולם, פי' אלקי ישראל מפני שעלו במח' לי ראש, אך כדי שיומשך מבחי' עצמות אא\"ס שלמעלה זהו שאמר ברוך ה' כו' מעלמא דאתכסיי' שהוא בחי' העלם אור עצמותו ממש שנק' שמו הגדול לעלמא דאתגלי' עולם דעקודי' נקודי' כו' נאצל ונברא כו' שנמשכו מבחי' הקו כו' (והיינו שיומשך ממל' דא\"ס בג\"ר דא\"ק ויהי' נק' אלקי ישראל לי ראש כנ\"ל) ובחי' ברכה",[["1641","28","<b>ארץ חטה ושעורה</b>: דברים ח, ח."],["1642","29","<b>בזוהר דתלת קשרין הן</b>: זח\"ג עג, א. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ ת\"ש ע' 61."],["1643","30","<b>בבחי'</b>: בכת\"י ב: מבחי'."],["1644","31","<b>ברוך ה' אלקי ישראל מן העולם ועד העולם</b>: תהלים קו, מח."]]],[2101000264,"והמשכה זו היא ע\"י התורה דוקא משום דמתקשראה בקוב\"ה עצמו שהוא עצמות אא\"ס כנ\"ל. ולהבין זה יש להקדים תחלה ענין מ\"ש בתורה ואהי'<sup data-n=\"1645\">32</sup> אצלו אמון שעשועי' יום כו'. דהנה בחי' מל' דא\"ס שלפני הקו כנ\"ל שנק' שמו הגדול נק' ג\"כ בשם בחי' התעגוג הפשוט שבעצמו' א\"ס ב\"ה ונק' בל' המקובלי' הראשוני' בשם שעשוע המלך בעצמותו (כמ\"ש בס' עמק המלך ע\"ש) ומ\"ש<sup data-n=\"1646\">33</sup> אוריי' מתקשרא בקוב\"ה היינו שנמשך בחי' הארה מאור אותו התענוג והשעשועי' הפשוטי' שבעצמותו ממש לבחי'<sup data-n=\"1647\">34</sup> החכ' שבתורה כמו שהיא בשרשה בעצמו' אא\"ס שהוא<sup data-n=\"1648\">35</sup> המדע כו', כי אוריי' מח\"ע שבעצמות א\"ס נפקת. ועד\"מ שאנו רואים בחכמת אדם שתאיר פניו בתענוג גדול מעצמו' התענוג הפשוט שבעצמו' נפשו ע\"י שחידש איזה חכמה חדשה כמו ר'<sup data-n=\"1649\">36</sup> אבהו דצהבו פניו מפני שמצא תוספתא חדת' וכה\"ג, והיינו מפני ששרש החכ' קבועה בנפש בבחי' עצמיות (ע\"כ עצם התענוג מתלבש בה וע\"כ כל המהות של הנפש נק' ע\"ש החכמה שבה נפש המשכלת או נפש המדברת וכמ\"ש במ\"א). וע\"כ ראשית גילוי התענוג העצמי הוא בכח החכמה כו'. וכך יובן למעלה שבחי' ראשי' גילוי אור תענוג ושעשוע המלך שבעצמו' ממש הכל הוא בחכ' שבתורה וז\"ש ואהי' אצלו כו' שעשועי' וזהו<sup data-n=\"1650\">37</sup> אוריי' מתקשרא בקוב\"ה שהוא עצמות השעשועי' וישראל שנמשכו מתענוג של הטפה שבמוחין שבראש מתקשראן בבחי' התענוג והשעשועי' שבעצמו' חכ' דא\"ס שהוא התורה, ווהו ישראל מתקשראן באוריי' כו'. ונמצא ע\"י התענוג שבאוריי' הוא בחי' ממוצע ממש להמשיך מעצמו' השעשועי' למטה ע\"י ישראל דמתקשראן באוריי'. ונמצא שניהם אמת, דגם דלית מחתפ\"ב אפי' מח' וחכ' דא\"ק, אבל שרש חכ' שבתורה שהיא בחי' עצמיות חכמתו דא\"ס ב\"ה בה נתפס כמ\"ש דאוריי' מתקשרא בקוב\"ה וכמ\"ש ה'<sup data-n=\"1651\">38</sup> קנני ראשית דרכו. וזהו שאמרו בשביל<sup data-n=\"1652\">39</sup> התורה שנק' ראשי' וגם בשביל ישראל שנק' ראשי' תבואתו מטעם הנ\"ל, אך התורה למעלה מישראל כו', ומאמצעות בחי' ג' קשרין הללו בג' מדריגות דעונג העליון נמשך ונשתלשל הארת העונג האלקי גם עד למטה מטה להיות בבחי' מקור כל תענוגי העוה\"ב כנ\"ל עד בחי' תענוג הגשמי דארץ חטה שמקבל מג\"ע דעשי' כו' (ובזה מתורץ מ\"ש ועמך<sup data-n=\"1653\">40</sup> כולם צדיקים לעולם ירשו ארץ שהוא העוה\"ב שמזה מביא ראי' דכל ישראל יש להם חלק לעוה\"ב לפי שמשרשם נמשך שרש התענוג של העוה\"ב וזהו ירשו ארץ שיורשים את שלהם כו' וד\"ל).",[["1645","32","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1646","33","<b>ומ\"ש</b>: בכת\"י ב: וז\"ש."],["1647","34","<b>לבחי'</b>: בכת\"י ב וכת\"י ג: והוא בחי'."],["1648","35","<b>שהוא המדע</b>: רמב\"ם הל' יסוה\"ת פ\"ב ה\"י. מו\"נ ח\"א פס\"ח. שמונה פרקים פ\"ח. תניא פ\"ב ובליקוט פירושים ומ\"מ שם."],["1649","36","<b>ר' אבהו דצהבו פניו</b>: ראה ירושלמי שבת פ\"ח ה\"א."],["1650","37","<b>וזהו</b>: בכת\"י ב: וזהו ישראל מתקשראן באורייתא אורייתא. ."],["1651","38","<b>ה' קנני ראשית דרכו</b>: משלי ח, כב."],["1652","39","<b>בשביל התו' שנק' ראשית</b>: תנחומא (באבער) ר\"פ בראשית פיסקא ג' וה'. לק\"ט שם. רש\"י ורמב\"ן שם. וראה ב\"ר שם. ויק\"ר פל\"ו, ד."],["1653","40","<b>ועמך כולם צדיקים. . דכל ישראל יש להם חלק לעוה\"ב</b>: ישעי' ס, כא. סנהדרין צ, א."]]],[2101000265,"<b>ובכ\"ז</b> מובן מארז\"ל ויתר<sup data-n=\"1654\">41</sup> הקב\"ה על עון ע\"ז ג\"ע וש\"ד ולא ויתר על עון ביטול תורה כו'. ולכאורה הנה זה המאמר פלאי מאד, דאם ר\"ל על איש שעובר על ג' עבירות הללו החמורות ע\"ז ג\"ע וש\"ד ולא ביטל מעולם מצות ת\"ת שויתר לו על ג' הללו, הלא נאמר ולרשע<sup data-n=\"1655\">42</sup> אמר מה לך לספר חוקי כו'. אלא הכונה כך הוא שע\"י שאר עבירות גם כמו ג' עבירות החמורות הנ\"ל אין גלות השכינה כ\"כ כמו ע\"י ביטול תורה שגלות השכינה הוא ענין ובחי' הסתלקות אור האלקי מכללות נש\"י ומתלבשת בע' שרים וגם שיהי' ריבוי עוונות וחטאים כשלג ילבינו ע\"י המשכות י\"ג מדה\"ר וכה\"ג והיינו אמרו ויתר הקב\"ה שמוותר ומרבה לסלוח אבל לא ויתר על ביטול תורה ולא מצד העון שהוא חמור יותר מגזל ועריות וכה\"ג אלא מטעם שביטול תורה הוא הגורם ביותר בחי' גלות השכינה בע' שרים מכל העוונות כו'. ולהבין זה הנה ידוע מ\"ש בזהר דרמ\"ח<sup data-n=\"1656\">43</sup> פיקודין נק' רמ\"ח אברי' דמלכא ושס\"ה ל\"ת הן בחי' שס\"ה גידין כי כל אבר הוא מבשר גידין ועצמות כו', וענין הגידין שבהן הוא בחי' סיבוב הילוך הדם הוא הנפש בכל האברים ועצם הגידים הן בחי' כלים שעל ידן יצא האור והחיות דרך אידים דקים להתחלק החיות בכל אבר ואבר לפי מזגו וטבעו כו'. וכן יובן למעלה בבחי' רמ\"ח אברי' דמלכא שהן רמ\"ח מ\"ע רמ\"ח בחי' המשכת גילוי אוא\"ס באצי' בבחי' כלים מכלים שונים כמו חסד דרוע' ימינא וכה\"ג וכידוע ושרש הל\"ת בבחי' שס\"ה גידין שברמ\"ח אברי' דמלכא הללו (להיות הל\"ת מבחי' הגבורות והוא בבחי' דם הוא הנפש שהוא מבחי' הגבורות ושרש רמ\"ח מ\"ע מבחי' החסדי' וכמ\"ש במ\"א שמזה הטעם שרש הל\"ת גבוהי' ממ\"ע וז\"ש שמי<sup data-n=\"1657\">44</sup> עם י\"ה שס\"ה כו') והנה כשבנ\"י אין מקיימין איזה מ\"ע ועוברין על איזה ל\"ת ודאי נעשה בחי' פגם וחסרון גילוי אור האלקי בא' מרמ\"ח אברי' דמלכא (שלכך א' ועשיתם<sup data-n=\"1658\">45</sup> כאילו עשאוני כו') אמנם לזה יש תיקון למלאות החסרון והפגם שברמ\"ח אברי' כו' ע\"י המשכת מקור הרחמים רבים כנ\"ל. אך ע\"י עון ביטול תורה הנה הפגם והחסרון הוא בבחי' הכלי של בחי' ח\"ע שמשם שרש התורה כנ\"ל דאוריי' מח\"ע נפקת, והיינו שנעשה בחי' מסך והסתר שלא יאיר ממקור התענוג הפשוט גם בחכ' שבעצמו' הנ\"ל מפני שאין קול קורא בתורה להמשיך אא\"ס מבחי' ראשי' גילוי השעשועי' העצמיי' בחכמתו העצמית, וז\"ש אין<sup data-n=\"1659\">46</sup> קורא בשמך דהיינו בשמו הגדול הנ\"ל שהוא עצמות אא\"ס מקור כל התענוגי' העליונים אין קורא וממשיך משם גילוי אור התענוג בחכ' שבתורה כו', ובסיבת זה מסתלק אא\"ס מכל העולמות כי בחי' החכ' שבראש כולל כל פרטי ההשתלשלו' דאורות בכלים מכלים שונים כידוע במשל המוחין שבראש האדם שכוללים כל חיות רמ\"ח אברים כו', וע\"כ דוקא ע\"י ביטול תורה נעשה בחי' גלות השכינה למטה יותר מכל העונות ולא ויתר הקב\"ה למחול",[["1654","41","<b>ויתר הקב\"ה על עון ע\"ז ג\"ע וש\"ד</b>: ירושלמי חגיגה פ\"א ה\"ז. פתיחתא דאיכ\"ר פי' ב."],["1655","42","<b>ולרשע אמר מה לך לספר חוקי</b>: ראה תהלים נ, טז. וראה סנהדרין קו, ב. ובכ\"מ."],["1656","43","<b>דרמ\"ח פיקודין נק' רמ\"ח אברי' דמלכא</b>: ראה ת\"ז תי' ל. זח\"ב קיח, א. וראה תניא פ\"ד ובליקוט פירושים ומ\"מ שם."],["1657","44","<b>שמי עם י\"ה שס\"ה כו'</b>: זח\"א כד, א ועוד. ת\"ז בתחילתו. וראה בארוכה לקו\"ת פקודי ג, ב."],["1658","45","<b>ועשיתם כאילו עשאוני</b>: זח\"ג קיג, א. וראה ויק\"ר פל\"ה, ז."],["1659","46","<b>אין קורא בשמך</b>: ראה ישעי' סד, ו."]]],[2101000266,"העון כי אין זה מצד העון אלא מטעם בחי' ההסתרה על כלי החכ' שלא יאיר אור ממקור הראשון כנ\"ל וד\"ל. ובזה יובן מ\"ש על<sup data-n=\"1660\">47</sup> מה אבדה הארץ על עזבם את תורתי כו' ופי' ארץ כמ\"ש השליך<sup data-n=\"1661\">48</sup> משמים ארץ כו' שהוא בחי' גלות השכינה שע\"י ביטול תורה יותר מכל העונות וארז\"ל מפני מה חרב בהמ\"ק מפני<sup data-n=\"1662\">49</sup> שלא ברכו בתורה תחלה. ולכאורה אינו מובן מ\"ש ברכו בתורה, דהל\"ל על התורה מהו בתורה הלא הברכה היא לפני קריאת התורה ולא בתורה כו'. אך הענין הוא שלא המשיכו בחי' ראשי' המשכת גילוי אא\"ס בתענוג שבחכ' וזהו פי' ברכו לשון המשכה מעצמות אא\"ס בחכ' שבתורה. ומ\"ש תחלה היינו להיות כי בתורה נמשך מבחי' ראשי' הגילוי דעצמו' אא\"ס עצמות השעשועי' ולכך חרב בהמ\"ק מטעם הנ\"ל בענין ביטול תורה שגורם ביותר בחי' גלות השכינה וד\"ל.\n<b>והנה</b> בחי' הגלות נמשל לשינה כמ\"ש ויקץ<sup data-n=\"1663\">50</sup> כישן ה' עורה למה תישן ה' וכיוצא. ולכאורה זה פלא גדול וכי יש בחי' שינה לפני המקום כו' הלא אין לו גוף כו'. אך הענין הוא כנ\"ל בענין גלות השכינה שהוא בחי' הסתלקות אור אלקי מכללות נש\"י וגם<sup data-n=\"1664\">51</sup> בשרש שרש כנ\"י הראשון שנק' לי ראש כנ\"ל גם שם מסתלק אור עצמות המאציל מבחי' המוחין שבראש (דא\"ק בכלל ובז\"א בפרט כו') וזהו הנק' בחי' שינה למעלה כבי' שנק' בחי' דורמיטא שהוא הסתלקות המוחין מפני בחי' ההסתר והמכסה שנעשה ע\"ג המוחין שמסיבת זה תפול השינה. עד\"מ בחי' שינה באדם למטה שהשינה<sup data-n=\"1665\">52</sup> באה ע\"י המאכל שאוכל הוא המביא לידי שינה כי פסולת המאכל שלא נברר בקיבה עולה מן הכבד ללב ומלב למוח עולים אידים גשמיי' שנעשה מפסולת המאכל ונעשין כמו מכסה ממש לכסות על המוחין להסתיר ולהעלים בלתי יוכל אור השכל להאיר בכלי המוחין, והוא בחי' השינה במוח. וממילא גם ב' כחות האחרים ההיולים בלב וכבד שהן בחי' רוח ונפש ג\"כ עולין בבחי' הסתלקות למעלה בכח היולי שבמוחין הכללי, כי נר\"נ כל א' עולה בעליון הימנו כנ\"ל, ואז ממילא לא נשאר בלב ג\"כ רק בחי' קיסטא דחיותא מבחי' רוח החיים שבלב ורק כח התנועה בנפש הוא הדם שבכבד ולא כח ההרגש כו', ומפני זה בלתי מתפשטין ג' כחות היולים הללו נר\"נ בניתוח התחלקות האברים כמו בהקיץ שהשכל מאיר במוח ומתפשט ללב ומלב לכבד ומתחלקי' לכל פרטי האברים כו', וע\"כ ממילא מובן שבבחי' שינה שבנשמה שבמוח ממילא נכלל בחי' שינה שבכל האברים שמקבלים מלב וכבד כו'. ולמעלה יובן מזה שבחי' שינה העליונה במוחין דא\"ק בכלל כמו בזמן הגלות שנאמר עורה למה תישן ה' כו' ממילא נכלל בזה בחי' שינה בשאר האורות דרוח ונפש בכלל ובפרטי האורות המתלבשים בכלים מכלים שונים עד סוף האצי'. ולזה אמר בזהר קוב\"ה<sup data-n=\"1666\">53</sup> בגלותא אסתלק לעילא לעילא, קוב\"ה",[["1660","47","<b>על מה אבדה הארץ</b>: ירמי' ט, יא."],["1661","48","<b>השליך משמים ארץ</b>: איכה ב, א."],["1662","49","<b>מפני מה חרב. . בתורה תחלה</b>: ראה נדרים פא, א. ב\"מ פה, ב. פתיחתא דאיכ\"ר פיסקא ב."],["1663","50","<b>ויקץ כישן ה'</b>: תהלים עח, סה."],["1664","51","<b>וגם בשרש</b>: בכת\"י ב: וגם בשרש."],["1665","52","<b>שהשינה באה ע\"י המאכל</b>: ראה יומא יח, א."],["1666","53","<b>קוב\"ה בגלותא אסתלק לעילא לעילא</b>: זח\"ג כ, ב. וראה זח\"א רי, א."]]],[2101000267,"בחי' ז\"א בפרט או בחי' א\"ק בכלל ובגלותא הוא בחי' הסתלקות האורות מן הכלים בנר\"נ שבאים מלובשים במוחא לבא וכבדא שנק' בי\"ע כנ\"ל, וע\"כ יש מקום אז ליניקות החיצוני' דע' שרים. עד\"מ אדם הישן שאינו מרגיש בזבובים היונקים מנקבי העור גופו וגם בפניו כו'. וכידוע דע' שרים מקבלי' מאחוריי' כו', וזהו הן הן<sup data-n=\"1667\">54</sup> גבורותיו גוים מרקדין בהיכלו והוא שותק כו' ולזה אמר ויקץ כישן ה' וכמ\"ש קומה<sup data-n=\"1668\">55</sup> ה' וממילא יפוצו אויביו שהוא רק כדמיון אדם שקם מן השינה וכמו בזמן אחשורוש שנאמר בלילה<sup data-n=\"1669\">56</sup> ההוא נדדה שנת המלך כו' וסיבת השינה בא מבחי' פסולת הרע דנוגה שלא נברר עדיין שעולה בנר\"נ להיות כמו בחי' מסך מסתיר על בחי' מוחין העליוני' בכלל ובפרט כנ\"ל, אבל בזמן בהמ\"ק מפני הקרבנות שביררו לכל הע' שרים הנה לא ינום ולא יישן כו', ולכך ביטל<sup data-n=\"1670\">57</sup> יוחנן כה\"ג את המעוררי' שאו' עורה למה תישן כו'. ומשחרב<sup data-n=\"1671\">58</sup> בהמ\"ק אין לו להקב\"ה בעולמו רק ד\"א של הלכה לעוררו בזה מבחי' השינה העליונה הנ\"ל וכמ\"ש השמיעני<sup data-n=\"1672\">59</sup> את קולך קלא דאוריי' כו' לפי שע\"י קול דתורה נמשך מעצמו' התענוג הפשוט להאיר בכלי המוחין דח\"ע כנ\"ל וה\"ז כמו שנתעורר איש מן השינה שיאיר אור השכל מלמעלה הימנו כו'. ובעון ביטול תורה גורמים ביותר בחי' השינה מטעם זה לפי שאין התעוררות מלמעלה מן החכ' כו' ולכך נק'<sup data-n=\"1673\">60</sup> בחי' גלות השכינה שהוא בחי' השינה הוא ביותר ע\"י עון ביטול תורה מכל העוונות כנ\"ל וד\"ל.\n<b>וזהו</b> עולת תמיד העשוי' בהר סיני לריח ניחוח כו'. פי' ריח ניחוח הוא ריח הקרבנות שמעוררים מבחי' השינה למעלה עד\"מ בנפש האדם למטה הנה אנו רואים שע\"י הריח טוב והחזק שיריח יתעורר מיד. ויש בזה ב' דברים, הא' שע\"י ריח הטוב והחזק יסתלק בחי' המכסה מן האידים הגשמיים מעל המוח כנראה בחוש וחוזר ונמשך אור וחיות במוחין בהתחדשות ומן המוח ללב ולכבד וכל ג' כחות היולים הללו עם כל פרטיהם מתחדשי' באור וחיות חדש ממש. והב' הוא אחר שהריח הטוב עולה למוח מיד חוזר הוא לירד למטה מן המוח אל הלב (והוא בנקב הב' שבחוטם שהוא בחי' שוב כו') ונעשה בחי' נחת הרוח ותענוג גדול המשיב את הנפש כו', והוא הנק' ניחוח שבא למטה בלב מלמעלה כו'. וכל אלה הוא למעלה ע\"י הריח של הקטר חלב ודם מן הקרבנות. כי הגם שהחלב ודם גשמי ה\"ז בחי' העלאה ובירור משרש הבהמה בבחי' פני שור למעלה ועד\"ז עד למעלה כמו באדם ריח המאכל וכמ\"ש לחמי<sup data-n=\"1674\">61</sup> לאשי ריח ניחוחי כו'. והנה החלב הוא בחי' המובחר של הדם דהיינו בחי' אור התענוג שבנפש מלובש בחלב שנברר המובחר מן הדם וכמו חלב<sup data-n=\"1675\">62</sup>",[["1667","54","<b>הן הן גבורותיו גוים מרקדין בהיכלו והוא שותק</b>: ראה יומא סט, ב. יל\"ש נחמי' רמז תתרעא."],["1668","55","<b>קומה ה'</b>: במדבר י, לה."],["1669","56","<b>בלילה ההוא נדדה</b>: אסתר ו, א."],["1670","57","<b>ביטל יוחנן כה\"ג את המעוררים</b>: סוטה מז, א. ובכ\"מ."],["1671","58","<b>ומשחרב ביהמ\"ק. . ד\"א של הלכה</b>: ברכות ח, א."],["1672","59","<b>השמיעני את קולך</b>: שה\"ש ב, יד. ראה זח\"ג סא, א. ריג, א."],["1673","60","<b>נק'</b>: בכת\"י ב וכת\"י ג ליתא תיבה זו."],["1674","61","<b>לחמי לאשי ריח ניחוחי</b>: במדבר כח, ב."],["1675","62","<b>חלב ודשן תשבע נפשי</b>: תהלים סג, ו."]]],[2101000268,"ודשן תשבע נפשי בעונג כו', וכמו שנראה בחוש הטבעי שישמן אדם בחלב מרובה רק ע\"י התענוגים שמקבל תמיד, וכן בעל תענוג ביותר יותר יתמלא חלב כו' ולמעלה ג\"כ ע\"י בחי' התענוג הגשמי שנתעלה מהקטר החלבים של הקרבנות מעוררי' למעלה בחי' ריח ניחוח טוב בבחי' תענוג דוקא, והוא ע\"י בחי' ארי' דאכיל קרבנין שנתמלא עי\"ז בבחי' התענוג העליון והיינו בחי' המשכת תענוג העליון מלמעלה מעלה עד למטה מטה, וזהו ריח ניחוח עד\"מ נח\"ר שנמשך מן עליי' הריח אל הלב בתענוג מורגש מאד כנ\"ל. וז\"ש בקרבן נח וירח<sup data-n=\"1676\">63</sup> ה' את ריח הניחוח ויאמר לא אוסיף עוד כו', ונמצא ע\"י ריח הקרבנות נתעורר מבחי' השינה כמו עד\"מ הריח העולה שמסיר המכסה כנ\"ל, ועוד שנמשך בחי' ניחוח מעצמות התענוג העליון עד למטה מטה כו'. וזהו פי' ריח ניחוח להוי' שנאמר בכל הקרבנות, פי' ניחוח לשון המשכה מלמעלה למטה לשם הוי' (שהוא בחי' א\"ק בכלל או ז\"א בפרט כנ\"ל), ולכך ביטל יוחנן כה\"ג את המעוררי' כנ\"ל וד\"ל.\n<b>(והנה</b> עכשו תפלות<sup data-n=\"1677\">64</sup> במקום קרבנות תקנום כידוע ואמר<sup data-n=\"1678\">65</sup> בזהר דשעת צלותא שעת קרבא וכמ\"ש בחרבי<sup data-n=\"1679\">66</sup> ובקשתי ותרגומו<sup data-n=\"1680\">67</sup> בצלותי ובעותי ואמר עוד בזהר<sup data-n=\"1681\">68</sup> דמאן דקטיל לחווי' יהבין לי' ברתא דמלכא כו', ולהבין כ\"ז הנה כמו שע\"י<sup data-n=\"1682\">69</sup> תמיד של שחר הי' מכופר עון ביטול תורה של לילה וע\"י תמיד של בה\"ע הי' מכפר על עון ביטול תורה דיום מטעם הנ\"ל שהקרבנות דתמידין הן לבחי' ריח ניחוח להוי' לעורר מבחי' השינה כמו ע\"י התורה כו' כך עכשו ע\"י תפלה של שחר ומנחה וערבית שהן במקום תמידין דוקא כידוע).\n<b>וביאור</b> הדבר איך יש בחי' ריח ניחוח גם בתפלה. הנה אמר בזוהר<sup data-n=\"1683\">70</sup> דכד אתכפי' סט\"א אסתלק יקרא דקוב\"ה כו' וגם ארז\"ל במקום<sup data-n=\"1684\">71</sup> שבע\"ת עומדין כו'. והענין הוא כמ\"ש איזהו<sup data-n=\"1685\">72</sup> גיבור הכובש את יצרו, שהוא בחי' בע\"ת<sup data-n=\"1686\">73</sup> דמשכי' לי' בחילא יתיר כמ\"ש בזהר דהיינו לכבוש יצרו בין בועשה טוב בין בסו\"מ. וביאור הדבר ידוע להיות כי במ\"ע יש ג\"כ גבורה אינו דומה שונה פרקו מאה פעמים",[["1676","63","<b>וירח ה' את ריח הניחוח</b>: בראשית ח, כא."],["1677","64","<b>תפלות במקום קרבנות תקנום</b>: ברכות כו, ב. ובכ\"מ."],["1678","65","<b>ואמר בזהר דשעת צלותא שעת קרבא</b>: ראה זח\"ג רמג, א. זח\"א רמ, ב. לקו\"ת תצא לד, ג. לה, ג."],["1679","66","<b>בחרבי ובקשתי</b>: בראשית מח, כב."],["1680","67","<b>ותרגומו בצלותי ובעותי</b>: ראה ג\"כ ב\"ב קכג, א."],["1681","68","<b>בזהר דמאן דקטיל לחווי' יהבין לי' ברתא דמלכא</b>: ראה ת\"ז תכ\"א (מג, א). תי\"ג (כט, ב). וראה לקו\"ת שם לה, ג."],["1682","69","<b>שע\"י תמיד של שחר הי' מכופר עון בטול תורה של לילה</b>: ראה במדב\"ר פכ\"א, כא. תנחומא פנחס יג. ובכ\"מ."],["1683","70","<b>בזוהר דכד אתכפי' סט\"א אסתלק יקרא דקוב\"ה</b>: ראה זח\"ב סז, ב. קכח, ב. קפד, א. והערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ח ע' 167."],["1684","71","<b>במקום שבע\"ת עומדין</b>: ברכות לד, ב. וראה הערת כ\"ק אדמו\"ר זי\"ע בסה\"מ תש\"ט ע' 183. לקו\"ש חי\"ד ע' 361."],["1685","72","<b>איזהו גבור הכובש את יצרו</b>: אבות פ\"ד מ\"א."],["1686","73","<b>בע\"ת דמשכי' לי' בחילא יתיר כמ\"ש בזוהר</b>: זח\"א קכט, ב. וראה אגה\"ת פ\"ח."]]],[2101000269,"לק\"א<sup data-n=\"1687\">74</sup> כו' להיות היפוך הטבע והרגילות כו', ובחי' גבורה הוא לכבוש הטבע המנגד כו'. וז\"ש ושבתם<sup data-n=\"1688\">75</sup> וראיתם בין עובד אלקים כו', וכל שאינו שונה ק\"א פעמים אינו נק' עובד אלקים. ולכאורה למה לא אמר שם הוי'. אך הענין כמארז\"ל על הנעלבין ואינן עולבין כו' על<sup data-n=\"1689\">76</sup>יהם או' הכתוב כצאת השמש בגבורתו. ולכאורה מה שייך לזה פסוק זה דוקא. אך הענין הוא כידוע בפי' כי<sup data-n=\"1690\">77</sup> שמש ומגן הוי' אלקי', דשם אלקי' הוא בחי' מגן ונרתק לשם הוי' להעלים ולהסתיר כו', ומזה נמשך שרש הטבע כו' ונק' עובד אלקים<sup data-n=\"1691\">78</sup> (שהוא גי' הטבע) כשמהפך הטבע לפי שעובד ומתקן לשם אלקים שרש הטבע מפני התגברות אור שם הוי' לצאת מנרתק ומגן המסתיר שהוא שם אלקים. וז\"ש כצאת השמש שהוא שם הוי' עצמו' המאור בגבורתו לצאת מנרתקו, כמארז\"ל לעתיד<sup data-n=\"1692\">79</sup> יוציא חמה מנרתקה כו'. והוא ע\"י בחי' הגבורות שלמטה כמו איזהו הנק' גיבור הכובש את יצרו בסו\"מ בהיפוך הטבע גם מתאוות היתר למשול ברוח המתאווה וכובשו וכך למעלה דרכו<sup data-n=\"1693\">80</sup> של איש לכבוש כו' כמו שיגבר אור השמש עצמו כו' ויתגלה מבחי' שמו הגדול סובב הכללי להשפיע עד למטה מטה כנ\"ל, כי באתדל\"ת אתדל\"ע כידוע וד\"ל. וזהו מאן דקטיל לחוויא דקטיר לרגלוהי דנוק'<sup data-n=\"1694\">81</sup> כו' שהוא נוגה דמפתי לאתתא כו' בסו\"מ וע\"ט יהבין לי' ברתא דמלכא שהוא שם אד' או שם אלקים, כי נק' עובד אלקים מטעם הנ\"ל וד\"ל. ופי' יהבין לי' שלא יסתיר שם<sup data-n=\"1695\">82</sup> אד' ואלקים ויכול תמיד להמשיך מעצמות אא\"ס באבי\"ע כו' וד\"ל. וכמו שע\"י בחי' גבורה כך ע\"י בחי' חסד כמו ע\"י צדקה וחסד נתעורר אור חסד עליון להאיר בהתגברות כמ\"ש כי<sup data-n=\"1696\">83</sup> גבר עלינו חסדו להיות ח\"ס דלי\"ת לשם אד' דלית לה כו' שלא יסתיר ולא יהי' יניקה לחיצוני' ג\"כ כלל וכלל כי יגרשו מכח בחי' הגבורות שבחסד עליון זה וד\"ל. וזהו בחי' ריח ניחוח שבתפלה לעורר ע\"י ביטול רצון מלמטה בבחי' גבורו', והוא נעשה בחי' הריח לעורר למעלה בחי' תגבורת חסד עליון שנק' ניחוח כו', והיינו ע\"י מלחמה שיתגבר על יצרו וקטיל לחוויא לאכפי' לסט\"א בב' יצריך כו', ונק' שעת קרבא ותרגום בחרבי ובקשתי כו' ויהבין לי' ברתא דמלכא דא צלותא שהוא גילוי אור הוי' באד'. וע\"כ כמו שע\"י התמידין הי' כפרת עוונות ביום ולילה כנ\"ל כך ע\"י התפלה מטעם דאתכפי' סט\"א כו' (והיינו אפי'<sup data-n=\"1697\">84</sup> נחש כרוך על עקבו לא יפסיק התפלה כו').",[["1687","74","<b>אינו דומה שונה פרקו מאה פעמים לק\"א</b>: חגיגה ט, ב. וראה תניא פט\"ו ובליקוט פירושים ומ\"מ שם."],["1688","75","<b>ושבתם וראיתם בין עובד אלקים</b>: מלאכי ג, יח."],["1689","76","<b>על הנעלבין ואינן עולבין. . כצאת השמש בגבורתו</b>: יומא כג, א. ובכ\"מ. שופטים ה, לא."],["1690","77","<b>כי שמש ומגן ה' אלקים</b>: תהלים פד, יב. וראה שעהיחוה\"א פ\"ד ואילך."],["1691","78","<b>אלקים (שהוא גי' הטבע)</b>: פרדס שי\"ב פ\"ב. וראה הערת כ\"ק אדמו\"ר זי\"ע באוה\"ת שמות ע' כט."],["1692","79","<b>לעתיד יוציא חמה מנרתקה</b>: ראה נדרים ח, ב, ע\"ז ג, ב. וראה תניא פכ\"ו ובליקוט פירושים ומ\"מ שם."],["1693","80","<b>דרכו של איש לכבוש</b>: ראה קדושין ב, ב."],["1694","81","<b>לחויא דקטיר לרגלוהי דנוק'</b>: ראה ת\"ז תכ\"ו (עב, א)."],["1695","82","<b>שם אד' ואלקים</b>: בכת\"י ב: שם אלקים."],["1696","83","<b>כי גבר עלינו חסדו</b>: תהלים קיז, ב."],["1697","84","<b>אפי' נחש כרוך על עקבו</b>: ברכות ל, ב."]]],[2101000270,"<b>ומעתה</b> י\"ל מ\"ש עולת תמיד העשוי' כו' מהו העשוי' כו'. דהנה מה שעכשיו בחי' התפלה ובזמן בהמ\"ק התמידין נק' עולת תמיד לריח ניחוח כבר היא עשוי' בהר סיני גם קודם שנאמרה פ' התמידי', להיות שבהר סיני כשקיבלו ישראל את התורה הי' בחי' גילוי אא\"ס מעצמותו ממש מבחי' שמו הגדול כמ\"ש אנוכי <sup data-n=\"1698\">85</sup>פי' מי שאנוכי סתימו דכ\"ס כו'. והנה סיבת בחי' הירידה הזאת הוא מפני שנתאוה<sup data-n=\"1699\">86</sup> הקב\"ה להיות לו דירה בתחתוני' דוקא, כי סוף מעשה עבמ\"ת כידוע. וזהו העשוי' מכבר בהר סיני להיות לריח ניחוח מבחי' בירורי נוגה בסו\"מ וע\"ט ממעשה התחתוני' כנ\"ל. אך איך יכול להיות עכשיו ג\"כ בבחי' הבירור דסומוע\"ט במ\"ע ול\"ת כמו במ\"ת לעורר מבחי' עצמות אא\"ס אנכי מי שאנכי כו' הנה הטעם הוא לפי שבמ\"ת מפני עוצם בחי' ההתגלות מעצמו' אא\"ס ב\"ה כשירד ה' על הר סיני ואמר אנוכי כו' נזדככו אז בנ\"י מחומריות גופם לגמרי כמ\"ש ויחרד<sup data-n=\"1700\">87</sup> כל העם אשר במחנה כו' בבחי' ביטול המציאות ממש, וכמארז\"ל על<sup data-n=\"1701\">88</sup> כל דיבור ודיבור פרחה נשמתן ממש כו' ועלה שרש נשמתם במקור חוצבם בעצמות אא\"ס שלפני הקו כו'. וידוע דאנוכי ולא יהי' לך מפי הגבורה שמענום<sup data-n=\"1702\">89</sup> כו' שעי\"ז פרחה נשמתן כי שאר הדברות מפי משה שמעו כמ\"ש דבר<sup data-n=\"1703\">90</sup> אתה עמנו ואל ידבר עמנו אלקים פן נמות כו', ואנוכי כולל כל רמ\"ח מ\"ע<sup data-n=\"1704\">91</sup> ולא יהי' לך כולל כל שס\"ה ל\"ת ודבר ה' יקום לעולם וגם עכשיו דבריו חיים וקיימים. וע\"כ גם עכשיו יש בכאו\"א מישראל בחי' גילוי אא\"ס מבחי' אנוכי כו' כמו במ\"ת להמשיך מבחי' עצמו' התענוג כו' ע\"י רמ\"ח מ\"ע הכלולים באנכי וע\"י ביטול הרצון במל\"ת לאכפי' ממשיך ג\"כ מבחי' העצמו' כנ\"ל. והיינו לריח ניחוח שבכל המצות שנעשה ונגמר בזמן מ\"ת, וזהו עולת תמיד העשוי' בה\"ס וקאי על בנ\"י שמעלין תמיד ריח ניחוח טוב בבחי' הבירורי' דסומוע\"ט שזה עשוי מכבר בהר סיני מטעם הנ\"ל וד\"ל.\n<b>לריח</b> ניחוח אשה לה' כו'. הנה י\"ל מה שפעם אמר אשה<sup data-n=\"1705\">92</sup> ריח ניחוח לה' ובכאן אמר תחלה לריח ניחוח ואח\"כ אשה לה', וכך יש כמה פסוקי' בקרבנות שפעם מקדי' אשה לריח ניחוח ופעם מקדי' ריח ניחוח לאשה כו'. אך הענין הוא דבפי' אשה יש ב' מדריגות א' בחי' דכר וב' בחי' נוק', כי אשה ואיש שניהם לשון אש כמו ואל<sup data-n=\"1706\">93</sup> אישך תשוקתך ולזאת<sup data-n=\"1707\">94</sup> תקרא אשה כי אל אישה תשוקתה ברשפי אש שלהבת, והאיש הוא בחי' דכר. וזהו ההפרש בין אש דדכר לנוק' בדכר אש יו\"ד",[["1698","85","<b>אנכי פי' מי שאנכי</b>: שמות כ, ב. וראה זח\"א קסז, ב. זח\"ג רנז, ב. לקו\"ת פינחס פ, ב. שם ראה לא, ד."],["1699","86","<b>שנתאוה הקב\"ה להיות לו דירה בתחתונים דוקא</b>: ראה תנחומא נשא טז. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. וראה תניא פל\"ו. ובכ\"מ."],["1700","87","<b>ויחרד כל העם אשר במחנה</b>: שמות יט, טז."],["1701","88","<b>על כל דבור ודבור פרחה נשמתן</b>: שבת פח, ב."],["1702","89","<b>דאנכי ולא יהי' לך מפי הגבורה שמענום</b>: מכות כד, א. ובכ\"מ."],["1703","90","<b>דבר אתה עמנו</b>: שמות כ, יט."],["1704","91","<b>ואנכי כולל כל רמ\"ח מ\"ע</b>: זח\"ב צא, א. וראה תניא פ\"כ ובליקוט פירושים ומ\"מ שם."],["1705","92","<b>אשה ריח ניחוח לה'</b>: ויקרא א, ט. ועוד."],["1706","93","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1707","94","<b>ולזאת תקרא אשה</b>: ראה בראשית ב, כג."]]],[2101000271,"ובנוק' אש ה\"א, והוא בחי' המשכת מ\"ד דדכורא שנמשך ברשפי אש התשוקה להשפיע נק' אש יו\"ד דחכמה מקור המשכת מ\"ד כידוע, ובחי' העלאת מ\"נ דנוק' נק' אש ה\"א ברשפי אש התשוקה לקבל השפע כו' (כידוע בדרז\"ל איש<sup data-n=\"1708\">95</sup> ואשה זכו שכינה ביניהם לא זכו אש אוכלתן, כי אותיו' י\"ה דאיש ואשה מתחברין יחד כשזכו להתקדש ביחוד כו'). וכן יובן באש הקרבנות, דהנה ידוע דאש על הקרבן מצוה<sup data-n=\"1709\">96</sup> להביא מן ההדיוט ונק' אש של הדיוט כמ\"ש אש<sup data-n=\"1710\">97</sup> תמיד תוקד על המזבח כו' וכשמקריב הקרבן באש של הדיוט אח\"כ נמשך בחי' אש שלמעלה הרוחני האלקי ובזהר<sup data-n=\"1711\">98</sup> נק' בשם ארי' דאכיל קרבנין כו' והוא האש שנמשך מבחי' הגבורות העליונות דפני ארי' שבמרכבה כו', והרי האש של הדיוט הוא בחי' העלאה למעלה כמו העלאת מ\"נ דאש דנוק' ע\"כ נק' אשה לשון נוק'. ובחי' אש שלמעלה דארי' כו' בא בבחי' המשכה מלמעלה למטה כמו בחי' אש דאיש שנק' המשכת מ\"ד להשפיע כנ\"ל, וה\"ז בחי' יחוד משפיע ומקבל. וע\"כ נאמר פעם אשה בבחי' מ\"ד ופעם בבחי' מ\"נ כפי אופן הקרבן, והיינו כשמקדי' לומר ריח ניחוח<sup data-n=\"1712\">99</sup> אשה לה' היינו בבחי' מ\"ד דדכורא שנק' ניחוח אשה לה' מלמעלה למטה כמו התפלה שבמקום תמידין שנמשך מלמעלה אחר בחי' ההעלאה מלמטה כו', וכאשר מקדי' לומר אשה לריח ניחוח ר\"ל בבחי' העלאת מ\"נ דנוק' אש ה\"א שיעלה למעלה לריח ניחוח לה' להיות אח\"כ המשכת מ\"ד כמ\"ש אש תמיד תוקד שהוא בחי' העלאת מ\"נ התמידי'. אך מ\"ש עולת תמיד העשוי' הכונה על בחי' אשה ריח ניחוח שבא מלמעלה למטה כמובן מתוך כל הנ\"ל וד\"ל.\n<b>והנה</b> ארז\"ל האכל<sup data-n=\"1713\">100</sup> יאכל בב' אכילות כו' א' אכילת מזבח והב' אכילת אדם והוא מה שהכהנים<sup data-n=\"1714\">101</sup> אוכלין אחר ההקרבה ע\"ג המזבח ובעלים מתכפרין כו'. וכך הוא למעלה א' בחי' אכילת מזבח העליון הוא ענין יחוד הנ\"ל באש שלמטה ואש שלמעלה שאש שלמטה הוא מן בחי' הבהמה שנקרבה ועלה בשרשה בבחי' פני שור כו' ונמשך מבחי' פני ארי' לאכול הקרבן ונק' בחי' אש שלמעלה וכ\"ז אינו אלא בבחי' המרכבה דפני ארי' כו'. אבל הנה כתיב ועל<sup data-n=\"1715\">102</sup> הכסא דמות כמראה אדם שע\"ג המרכבה כו', וכמו שמבואר בענין יחוד הנ\"ל כך יש בחי' יחוד יותר עליון והוא בבחי' אכילת אדם שע\"ג הכסא כו', דהיינו כידוע שיש ב' בחי' אדם א' בחי' אדם תתאה שבמרכבה כמ\"ש ופני<sup data-n=\"1716\">103</sup> אדם לארבעתן (ובזוהר<sup data-n=\"1717\">104</sup> נק' אנפי זוטרא או כרובי'",[["1708","95","<b>איש ואשה זכו שכינה ביניהם</b>: סוטה יז, א."],["1709","96","<b>מצוה להביא מן ההדיוט</b>: ראה עירובין סג, א. זח\"ג רנה, א."],["1710","97","<b>אש תמיד תוקד על המזבח</b>: ויקרא ו, ו."],["1711","98","<b>ובזהר נק' בשם ארי' דאכיל קרבנין</b>: זח\"א ו, ב. זח\"ב רעח, א. זח\"ג יז, א."],["1712","99","<b>על. . ניחוח</b>: בכת\"י ב: על בחי' מ\"ד לריח ניחוח אשה."],["1713","100","<b>האכל יאכל בב' אכילות</b>: זבחים יג, ב. ובכ\"מ."],["1714","101","<b>שהכהנים אוכלין. . ובעלים מתכפרין</b>: פסחים נט, ב. ובכ\"מ."],["1715","102","<b>ועל הכסא דמות כמראה אדם</b>: יחזקאל א, כו."],["1716","103","<b>ופני אדם לארבעתן</b>: ראה יחזקאל א, י. והערת כ\"ק אדמו\"ר זי\"ע בהמשך מים רבים תרל\"ו ע' נא."],["1717","104","<b>ובזוהר נק' אנפי זוטרא או כרובי' כרביא</b>: ראה זח\"א יח, ב. ובכ\"מ. וראה סוכה ה, ב. חגיגה יג, ב."]]],[2101000272,"כרביא כו') והב' בחי' אדם עילאה שעל הכסא כו' כמ\"ש כמים<sup data-n=\"1718\">105</sup> הפנים לפנים כן לב האדם לאדם, דהיינו לפי ערך בחי' העלאת מ\"נ דאדם התחתון שבמרכבה לגבי אדם העליון כך נמשך אור בחי' מ\"ד מבחי' אדם העליון לאדם התחתון למהוי<sup data-n=\"1719\">106</sup> אחד באחד שהוא בחי' יחוד זו\"נ בכלל, וכמ\"ש לבבתני<sup data-n=\"1720\">107</sup> אחותי כלה כו' כידוע. וגם כאן הוא בדרך הנ\"ל, דלפי ערך בחי' תשוקת רשפי אש שלהבת י\"ה מבחי' אדם התחתון שהוא בחי' המל' כמ\"ש רשפיה<sup data-n=\"1721\">108</sup> רשפי אש כו' וכמ\"ש ואל<sup data-n=\"1722\">109</sup> אישך תשוקתך כו' כך נמשך ג\"כ בחי' אש שלמעלה דאיש שהוא בחי' מ\"ד דז\"א כמ\"ש ה'<sup data-n=\"1723\">110</sup> איש כו' ברשפי אש האהבה וכמ\"ש מה<sup data-n=\"1724\">111</sup> יפית כו' אהבה בתענוגי' מלמעלה למטה הבאה ברשפי אש התלהבות התענוג כו' והוא הנק' אש שלמטה ואש שלמעלה בבחי' אכילת אדם כנ\"ל בענין אש שלמטה ואש שלמעלה באכילת מזבח (וב' מיני יחודי' הללו הוא ההפרש בין בחי' אכילה לבחי' התפלה כמ\"ש במ\"א בענין פתח<sup data-n=\"1725\">112</sup> במזבח וסיים בשולחן כו'). וז\"ש עולת תמיד כו' לריח ניחוח אשה לה' להיות מקור כל בחי' המשכת מ\"ד דז\"א ממקור הגבורות העליונות שנמשך בבחי' הריח (דחוטמא<sup data-n=\"1726\">113</sup> דע\"י מבחי' חיי דחיין) מעצמות אא\"ס ב\"ה כנ\"ל וד\"ל.",[["1718","105","<b>כמים הפנים לפנים</b>: משלי כז, יט."],["1719","106","<b>למהוי אחד באחד</b>: ראה זח\"ב קלה, א."],["1720","107","<b>לבבתני אחותי כלה</b>: שה\"ש ד, ט."],["1721","108","<b>רשפיה רשפי אש</b>: שה\"ש ח, ו."],["1722","109","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1723","110","<b>ה' איש כו'</b>: שמות טו, ג."],["1724","111","<b>מה יפית כו' אהבה בתענוגים</b>: שה\"ש ז, ז."],["1725","112","<b>פתח במזבח וסיים בשולחן</b>: ברכות נה, א."],["1726","113","<b>דחוטמא דע\"י מבחי' חיי דחיין</b>: ראה זח\"ג קל, ב."]]],[2101000273,"<h3>להבין שרשי הדברים</h3>\n<b>להבין שרשי הדברים </b>\n<b>להבין</b><sup data-n=\"1727\">1</sup> שרשי הדברי' הנ\"ל. הנה להבין שרש ענין ישראל לי ראש כו'. יש<sup data-n=\"1728\">2</sup> להקדי' תחלה שרש ענין בחי' אורות וכלים מהו. דהנה לא כמו שמובן לכאור' בספרי המקובלים הראשונים והאחרונים דבכל מציאו' שכבר נתהוו' מן המאציל יש ב' מדריגות אור וכלי כמו מציאת החכמה שנאצלה מן המאציל יש בה ב' מדריגות בחי' אור ובחי' הכלי בחי' האור נק' אור החכ' ובחי' הכלי נק' כלי החכ' (כמבואר<sup data-n=\"1729\">3</sup> בפרד\"ס<sup data-n=\"1730\">4</sup> בשער עצמות וכלים וגם בע\"ח מובן לכאורה כן בכמה דוכתי) דא\"כ מה שנק' אור החכ' הוא מציאת גוף החכמה עצמה ובחי' כלי החכ' הוא רק בחי' הגבלת האור והמציאות עצמו, והוא ג\"כ בחי' השפעת האור למטה. דלפ\"ז הרי א\"א לומר בפי' המאמר<sup data-n=\"1731\">5</sup> דס\"י ע\"ס בלי מ\"ה כלומר בלי מהות ומציאות אחר שבחי' האורות",[["1727","1","<b>להבין שרשי הדברים</b>: קטע מביאור זה נדפס (בשינויים ותוס' הגהות) באוה\"ת פינחס ע' א'קמו. קיצורים והגהות נדפסו באוה\"ת שם כרך ה' ע' א'תרעז. חלק מהמאמר הובא ג\"כ בהמשך מים רבים תרל\"ו פרקים קד-קח. ובאוה\"ת על ענינים ע' רסג."],["1728","2","<b>יש להקדים תחלה שרש ענין בחי' אורות וכלים</b>: ראה ג\"כ בהנסמן בספר הערכים חב\"ד כרך ד' ע' קז וע' תקלב."],["1729","3","<b>כמבואר</b>: בכת\"י ב וכת\"י ג: כמובן."],["1730","4","<b>בפרד\"ס בשער עצמות וכלים</b>: פ\"ד."],["1731","5","<b>המאמר דס\"י ע\"ס בלי מה</b>: פ\"א מ\"ב."]]],[2101000274,"דע\"ס גם הן בחי' מציאות ומהות דבר מה כנ\"ל. וגם א\"א לפרש לפ\"ז המאמר דאיהו<sup data-n=\"1732\">6</sup> וחיוהי חד דקאי על בחי' האורות דע\"ס דאיך מתייחדי' לגמרי בבחי' העצמות אחר שהן במספר עשר מציאות עשר<sup data-n=\"1733\">7</sup> ולא תשע כו' וגם הן בבחי' מציאות ומהות דבר מה ועצמות אא\"ס מושלל מכל בחי' מציאות וכמ\"ש לאו<sup data-n=\"1734\">8</sup> דאית לך מכל אינון מדות כלל כי הוא ית' בעצמו אור פשוט בתכלית האחדות הפשוטה כידוע. אלא בהכרח לומר בענין ב' מדריגות דאור וכלי שבע\"ס דלא כמובן לכאורה בסה\"ק דקאי על מציאות הנאצלים אלא<sup data-n=\"1735\">9</sup> הוא בחי' גילוי אור המאציל להאציל את מציאת הנאצל וגופו של מציאת הנאצל הוא הנק' בחי' כלי של האור כמו ספי' חכמה שנאצלה מן המאציל הנה בחי' גילוי האור והשפע להאציל למציאת החכמה נק' אור החכמה וכאשר כבר נאצל מציאת החכ' הרי נק' מציאת החכמה עצמה בשם בחי' כלי לאור של המאציל שהאציל לחכמה. וא\"כ אין הפי' בכלי החכ' שהחכמה כבר ישנה במציאות והכלי הוא רק בחי' הגבלת מציאותה בלבד אלא גופה של מציאת החכ' נק' כלי והיא עצמה בחי' הגבלת האור שלה דהיינו אור הנשפע מהעצמות להאציל את מציאותה הרי בעצמות מציאותה היא מגבלת לאור הזה כו'. ולפ\"ז יתפרש שפיר מ\"ש בס\"י דע\"ס בלי מה בלי מהות ומציאות כלל, כי כל בחי' האור של כל ספי' אינו בגדר מציאות ומהות מדה וספי' עדיין אלא רק שהוא בחי' גילוי אור הנשפע מן המאציל להאציל אותו המציאות כנ\"ל. ולכך אמר ג\"כ דאיהו וחיוהי חד ממש, כי לפי פי' זה הרי כל בחי' האורות דע\"ס מתייחדי' בבחי' עצמי' המאציל בתכלית היחוד אחר שהן מושללים ג\"כ עדיין מכל מציאות ספי' ומדה כנ\"ל וד\"ל.\n<b>אך</b> הנה י\"ל ביאור דבר זה איך יהי' בחי' גוף מציאת הספי' נחשב לבחי' כלי להגביל את האור כו'. ותחלה י\"ל היטב ביאור ענין ובחי' האצי' מהו. כי הנה הטעם שנק' בשם אצילות דוקא ידוע לפי שהוא ענין האצלה והפרשה כמ\"ש במשה ויאצל<sup data-n=\"1736\">10</sup> מן הרוח על ע' הזקנים וכן כתיב ואצלתי<sup data-n=\"1737\">11</sup> מן הרוח כו'. וביאור זה ידוע שלשון ואצלתי או ויאצל אין הכונה שעיקר מציאותו של הרוח נבואה שבמשה ירד ונח בע' הזקנים שא\"כ היו נביאים כמותו ממש, וידוע שלא היו שוים במדריגה עמו כלל שהרי אלדד ומידד שנתנבאו במחנה הי' זה לפלא בעיני יהושע רק משה אמר מי<sup data-n=\"1738\">12</sup> יתן והי' כל עם ה' נביאים כי יתן ה' את רוחו ממש עליהם כו'. אלא פי' אצילות הרוח היינו רק הארה בעלמא שהופרשה להאיר מרוחו של משה על הזקנים (כמו<sup data-n=\"1739\">13</sup> בשאול שנחה עליו הרוח ונתנבא גם הוא גם שלא הי' ראוי כלל לנבואה, וכך ע' הזקנים לא היו ראוים לנבואת רוחו של משה כלל רק שהאיר עליהם הארה בעלמא).",[["1732","6","<b>דאיהו וחיוהי חד</b>: ת\"ז בהקדמה לפני ד\"ה קום יחזקאל."],["1733","7","<b>עשר ולא תשע</b>: ס\"י פ\"א מ\"ד."],["1734","8","<b>לאו דאית לך מכל אינון מדות כלל</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["1735","9","<b>אלא הוא</b>: בכת\"י ב וכת\"י ג: אלא בחי' האור הוא."],["1736","10","<b>ויאצל מן הרוח</b>: במדבר יא, כה. וראה סה\"מ תקס\"ז ע' תכט."],["1737","11","<b>ואצלתי מן הרוח</b>: במדבר יא, יז."],["1738","12","<b>מי יתן והי' כל עם ה' נביאים</b>: במדבר יא, כט."],["1739","13","<b>כמו בשאול שנחה עליו הרוח</b>: ראה שמואל-א י, י."]]],[2101000275,"<b>ואותה</b> ההארה כשהאירה בכלי השגתם הגם שנאצלה מרוחו של משה ממש מ\"מ בבוא הארה זו בכלי השגתם הרי הוגבלה ההארה ונתגלית רק לפי מציאות השגתם בלבד וע\"כ לא נק' נביאים כמשה וכמו שהעיד הכתוב ולא<sup data-n=\"1740\">14</sup> קם נביא עוד כו' וד\"ל. ואמנם למעלה הם משאר הנביאים שהרי אמרו משה<sup data-n=\"1741\">15</sup> קיבל תורה מסיני ומסרה ליהושע ויהושע לזקנים וזקנים לנביאים הרי זקנים למעלה מנביאים, דהיינו שנבואתם<sup data-n=\"1742\">16</sup> בזה ולא בכה כשאר הנביאים, וא\"כ י\"ל מהו עצם מדריגתם. אך הענין הוא דאעפ\"י שנגבל הארת רוחו של משה בכלי השגתם מ\"מ יש להם קצת ערך ויחוס אל גופו ומהותו של רוחו ממש<sup data-n=\"1743\">17</sup> מצד בחי' ההארה שהופרשה ונחה עליהם כו' וד\"ל. וכמ\"כ יובן בפי' אצי' העליונה בבחי' אורות דע\"ס שנאצלו מן המאציל הנה אין הכונה שנמשך ממהות ועצמות המאציל אלא רק בחי' הארה בעלמא שהופרשה והובדלה והוא הנק' בשם אור כלומר אור המאיר ומתפשט מן המאציל לחוץ ממנו כמ\"ש ויאצל מרוחו של משה כמו אור החכ' היינו בחי' אור המאיר מעצמי' המאציל להיות מציאת החכ' כנ\"ל, וכן פי' אור החסד או אור הגבורה, וכמו מרוחו של משה שהאציל על הע' זקנים שנגלה עליהם הרוח כפי השגת כאו\"א כך למעלה הרי נגלה אור המאציל להאציל ע\"ס עשר ולא תשע והאור שנגלה בע\"ס הוא הנק' ע\"ס בלי מה בלי מהות ומציאות ע\"ס עדיין וגופו של מציאת הנאצל מהארת המאציל הן הי\"ס דאצי' והן הנק' בחי' כלים לאורות דהיינו המגבילים את האורות הנמשכים מן העצמות להיות מתגלים באיזה מציאות דבר מה כספי' חכמה וחסד וכה\"ג (אבל מצד עצמותו לאו מכל אינון מדות כלל דהיינו מצד השפעת אור המאציל כנ\"ל) כמו הגבלת רוחו של משה בכלי השגת כאו\"א מהזקנים כנ\"ל וד\"ל.\n<b>ומעתה</b> יובן שרש ענין ישראל לי ראש שהוא בחי' חב\"ד דז\"א ודרך כלל הוא בחי' (חכ' שבחסד או חכ' שבגבורה דהיינו בחי') הארת השכל במדות וכמו ג' חללי המוחין באדם מוח החכ' ומוח הבינה כו' שהמה בראש האדם ונק'<sup data-n=\"1744\">18</sup> בס\"י חכ' בראש כו'. וביאור הדברי' הנה יובן עפ\"י ענין הנ\"ל בהפרש אשר בין בחי' האורות לבחי' הכלים דבחי' האורות הוא למעלה עדיין מבחי' התגלות מציאו' דבר מה רק שהוא השפעת המאציל עדיין כו' וממילא הוא למעלה מבחי' התחלקות ומבחי' ההתכללות כידוע דבחי' ההתכללו' תלוי' בבחי' ההתחלקות דכל מה שנחלק השפע לריבוי התחלקות ככה ירבה בה בחי' ההתכללות דבר מזולתו בכמה אופני' שונים ועד\"מ המחלק דבר מה לחלקים כל מה שיחלק לריבוי חלקים ביותר יותר יהי' ביכולתו לעשות התכללות בריבוי מכמה חלקים כו'. וככה יובן למשכיל למעלה, דהנה הע\"ס הנק' אורות עדיין למעלה מבחי' התחלקות עשר כנ\"ל וממילא אין בהם בחי' ההתכללות דהיינו שאין החכ' כלולה מחסד והחסד אינו כלול מהחכ' לפי שאין החכ' נק' עדיין בשם מציאות כלל וכ\"ש שאינו מתחלק לי\"ס להיות כלול מחסד וכן",[["1740","14","<b>ולא קם נביא עוד</b>: דברים לד, י. וראה רמב\"ם הל' יסוה\"ת פ\"ז ה\"ו. ובכ\"מ."],["1741","15","<b>משה קיבל תורה מסיני</b>: אבות פ\"א מ\"א."],["1742","16","<b>שנבואתם בזה ולא בכה כשאר הנביאים</b>: ראה ספרי ר\"פ מטות (פיס' קנג)."],["1743","17","<b>ממש</b>: בכת\"י ב וכת\"י ג: של משה."],["1744","18","<b>ונק' בס\"י חכ' בראש</b>: ראה זח\"א כו, ב."]]],[2101000276,"אין החסד ניכר במציאות עצמו עדיין ומכ\"ש שאינו מתחלק לי\"ס להיות כלול מחכ' וכה\"ג. ונמצא מה שאנו מוצאים שיש בחי' התכללות בי\"ס דאצי' דהיינו שהחכ' כלולה מהחסד ונק' חסד שבחכ' והחסד כלול מן החכמה ונק' חכ' שבחסד וכיוצא בה בשאר התכללות מחסד לגבורה ושאר המדות אין זה אלא כאשר כל ספי' וספי' מתחלקת לי' וי' ליו\"ד כו' שאז יש בחי' התכללות בחכ' מחסד ונק' חסד שבחכ' ובחסד יש התכללות מחכ' ונק' חכ' שבחסד, ועי\"ז יוכל להיות התכללות מחכ'<sup data-n=\"1745\">19</sup> בחסד בכמה אופני' כנ\"ל. אבל כאשר אין כל ספי' מתחלקת ליו\"ד הרי אין בחי' החכ' כלולה מבחי' החסד כלל אלא בחי' חכ' בפ\"ע ובחי' חסד בפ\"ע כו'. וזהו ההפרש בין בחי' האורות לבחי' הכלים דבבחי' הכלים המגבילים האורות להיות מתגלים באיזה מציאות ומהות כנ\"ל שם הוא בחי' ההתחלקות ובחי' ההתכללו' דהיינו שכל ספי' וספי' מתחלקת לי\"ס ויש חסד בחכמה וחכ' בחסד כנ\"ל וממילא יתכללו יחד. והטעם לבחי' ההתחלקות וההתכללו' בבחי' הכלים דוקא היינו לפי שכאשר האור ניכר במציאות יש ודבר מה כמו מציאת השכל הנה בהכרח שימצא בו חלקים רבים כמו שכל המטה כלפי חסד ושכל המטה כלפי דין ועונש הרי יש כאן ב' חלקי מיני שכל ונק' חסד שבחכ' וגבורה שבחכ'. וככה יתחלק לי' מדריגות וכן אור מציאת החסד הרי מתחלק עפ\"י טעם ושכל לאותו החסד אם כך או כך, והוא נק' חכמה שבחסד כלומר העיקר הוא מדת החסד אך שכלול מטעם ושכל לאותו החסד כידוע. והרי נמצא בחסד חלק מן השכל ובשכל נמצא חלק מן החסד, ועי\"ז יוכלל כל השכל בחסד, וכ\"ז מטעם בחי' ההתחלקות לי' כלים בחכ' וחסד ע\"כ יוכללו זב\"ז, משא\"כ בבחי' האורות כו' וד\"ל. וזהו ענין ישראל לי ראש דהיינו כאשר בחי' ע\"ס דאצי' הן באין בבחי' הכלים ומתכללי' זע\"ז עד שיש חסד בחכ' וחכמה בחסד אזי גם בבחי' המדות דז\"א יש בחי' התכללות והוא הנק' בחי' חב\"ד דז\"א, דהיינו בחי' חכמה שבחסד כלומר הטעם ושכל להחסד שהחסד מתנהג עפ\"י שכל וטעם. אבל אין זה ערך לעצמיות השכל קודם שמתפשט במדות הנק' בחי' חכ' עצמה שהיא מהות ופרצוף בפ\"ע, רק מפני שיש חסד בחכ' ע\"כ מתכלל גם חכמה בחסד כנ\"ל וד\"ל.\n<b>והנה</b> כל ענין הנ\"ל בבחי' ההתכללות כמו מחכ' לחסד שהוא מפני בחי' הכלים שמגבילי' האור לי' חלקים כו' הנה זהו רק דרך כללות בלבד דהיינו שכל אור נחלק לי' אבל בחי' פרצוף הוא כאשר יש בחי'<sup data-n=\"1746\">20</sup> כלים בכל פרטי התחלקו' וכדמיון פרצוף אדם שהוא בציור אברים וכל אבר כלול מג' מיני כלים פנימי ואמצעי וחיצון כו' וכמ\"ש בע\"ח די\"ס דז\"א שבי' כלים נחלקים לג' מדריגות פנימי ואמצעי וחיצון ונק' סת\"ר ראש תוך סוף, והלמ\"ד כלים הללו יורדי' ומתלבשי' בג' עולמות בי\"ע י' כלים הפנימי' נעשי' בחי' נשמה בבריאה וי'<sup data-n=\"1747\">21</sup> כלים<sup data-n=\"1748\">22</sup> האמצעי' נעשי' בחי' רוח ביצי' והחיצוני' נעשי' בחי' נפש בעשי' כו'. וזהו עיקר ההפרש בין שרש הנשמו' לשרש המלאכי' דשרש הנשמות נמשך מבחי' הכלים הפנימי' ושרש המלאכי' נמשך מחיצוניו' הכלים כמ\"ש<sup data-n=\"1749\">23</sup> בע\"ח. וביאור כ\"ז הנה בכל אור וספי' יש ג'",[["1745","19","<b>מחכ' בחסד</b>: בכת\"י ב: בחכ' מחסד."],["1746","20","<b>בחי' כלים</b>: בכת\"י ב וכת\"י ג: בחי' ג' כלים."],["1747","21","<b>וי'</b>: בכת\"י ב: ונשמות יו\"ד."],["1748","22","<b>כלים</b>: בכת\"י ב וכת\"י ג ליתא תיבה זו."],["1749","23","<b>כמ\"ש בע\"ח</b>: ראה שער פרקי הצלם פ\"ו."]]],[2101000277,"מדריגות, בחי' חב\"ד חג\"ת נה\"י ולנגד ג' כלים אלה יש ג' כלים דחב\"ד נק' כלים הפנימי' וכלים דחג\"ת נק' כלים האמצעיי' וכלים דנה\"י נק' כלים החיצוני'. וביאור זה הנה ידוע בע\"ח דבחי' ז\"א עיקרו ט' ספי' בלבד (רק שמתגדל בג' כלים הנ\"ל ונעשה טפ\"ט ג\"פ) דהיינו שכל ספי' כלולה מג' מדריגות חב\"ד חג\"ת נה\"י כנ\"ל. וביאור זה עד\"מ מבשרי אחזה דאנו רואים מדת החסד באדם שהיא כלולה מג' אלה בחי' חכ' שבחסד ובחי' חסד שבחסד ובחי' נצח שבחסד. בחי' חכ' שבחסד הוא השכל והטעם של אותו החסד, ובחי' חסד שבחסד הוא בחי' עצם מהות ההשפעה של אותו החסד כמו שהיא, ובחי' נצח שבחסד הוא כאשר אותה ההשפעה של החסד נגלית ונמשכת למקבל ונק' בחי' ירכין לבר מגופא, פי' כי גופא הוא בחי' חג\"ת בחי' עצמי' השפע, וגילוי השפע לחוץ שהוא בחי' חיצוני' ההשפעה נק' ירכין כמו הרגלים שמוליכין לגוף להלאה ממקומו העצמי כו'. וכ\"ז בבחי' האור של החסד עצמו ולנגד ג' אלה יש ג' מיני כלים, הא' בחי' הכלים הפנימי' שמגבילים לאור הפנימי ביותר והוא לבחי' חב\"ד שבחסד, והב' הכלים האמצעיי' שמגבילים לבחי' חג\"ת שבחסד, והג' בחי' כלים החיצוני' שמגבילי' לחיצוני' האור שהוא בחי' נה\"י שבחסד שנק' גילוי השפע לחוץ. ומפני שבג' כלים אלה מתגלי' ג\"פ כל הט\"ס שבז\"א הרי נעשה טפ\"ט ג\"פ שעולה רמ\"ג וה\"ח המגדילי' עולה רמ\"ח כו' כמ\"ש בע\"ח ומבואר כ\"ז במ\"א באריכות וד\"ל. וזהו ההפרש בין שרש המלאכי' לשרש הנשמות דשרש הנשמו' נמשך מבחי' פנימי' הכלים שמגבילים לחב\"ד דז\"א בדרך כלל, ושרש המלאכי' נמשך מבחי' חיצוני' הכלים שמגבילים לבחי' נה\"י דז\"א, ולכך נק' המלאכים בחי' רגלין כי שרשם מבחי' כלים דנה\"י שנק' ירכין לבר מגופא כו'.\n<b>ולהבין</b> זה בתוס' ביאור הנה יש להקדי' להבין מ\"ש בע\"ח דהמל'<sup data-n=\"1750\">24</sup> נקנית בשלושים מעלות כו', ושלשים מעלות הללו היינו בחי' למ\"ד כלים דז\"א פנימי' ואמצעי' וחיצוני' רת\"ס כנ\"ל שמהם נבנה עיקר בנין הנוק' כמ\"ש בע\"ח בכמה דוכתי דמי'<sup data-n=\"1751\">25</sup> כלים הפנימי' דז\"א נמשך בחי' ע\"ס דבריא' ומהאמצעי' נמשך בחי' ע\"ס דיצי' כו' והוא בחי' נר\"נ דמל' שנעשי' מלמ\"ד כלים הללו דהיינו שמבחי' כלים דחב\"ד דז\"א נבנה בחי' חב\"ד דנוק' דז\"א, ומבחי' כלים דחג\"ת דז\"א נבנה בחי' חג\"ת דנוק' דז\"א, ומבחי' כלים החיצוני' דנה\"י דז\"א נבנה בחי' נה\"י דנוק' כו', וזהו דרך כללות. ודרך פרט היינו שמכל בחי' כלי שבספי' דז\"א נבנה בחי' האור שבמל' (והיינו<sup data-n=\"1752\">26</sup> מ\"ש בזהר שהמלכות היא נמשכת מעשיראה דכולהו כו', דהיינו כמו מבחי' מל' שבחסד דז\"א נבנה אור החסד שבמל' ועד\"ז כל בנין ע\"ס דמל' כו'). ונמצא הרי מובן מזה דרך פרט שנמשך מבחי' כלי החכ' שבחסד דז\"א שנק' כלי פנימי בחי' אור החכ' שבמל' וכאשר יורד האור ומתלבש זב\"ז חב\"ד בחג\"ת כו' היינו שנמשך בחי' חכ' שבמל' בחסד שבמל' ע\"י אמצעו' בחי' הכלי דחסד דז\"א שממנו יבנה בחי' חסד",[["1750","24","<b>דהמל' נקנית בשלשים מעלות</b>: אבות פ\"ו מ\"ו. וראה אוה\"ת דרושים לר\"ה ע' א'תג."],["1751","25","<b>דמי'</b>: בכת\"י ב וכת\"י ג: דע\"י."],["1752","26","<b>והיינו מ\"ש בזהר שהמל' היא נמשכת מעשיראה דכולהו</b>: ראה זח\"ג רנג, ב. ועוד."]]],[2101000278,"שבמל'. הרי מחכ' שבחסד דז\"א נמשך ומתלבש בחכ' שבחסד דמל', ועד\"ז גם בנצח שבחסד שבמל' מאיר מבחי' נצח שבחסד דז\"א ע\"י אמצעות כלי דנצח דחסד שבז\"א כו' וד\"ל. ועד\"ז כל פרטי הספי' דז\"א נמשכים במל', והיינו מ\"ש דבשלשים מעלות דז\"א נבנה בחי' המל' כו'.\n<b>ומעתה</b> יובן ג\"כ שרש ההפרש בין נשמו' למלאכי'. דהנה שרש הנשמות נמשך מבחי' יחוד וזיווג גופני דזו\"נ כידוע בפי' אור<sup data-n=\"1753\">27</sup> זרוע לצדיק שהוא בחי' המשכת מ\"ד דז\"א שנמשך דוקא מבחי' המוחין חב\"ד והיינו מבחי' כלים דחב\"ד כו', וכן בחי' העלאת מ\"נ דנוק' כמ\"ש אשה<sup data-n=\"1754\">28</sup> כי תזריע כו' ג\"כ נמשכים מבחי' המוחין שלה דוקא, ואע\"פ שיוצא השפע' הטפה מבחי' נה\"י דז\"א מ\"מ שרשו נמשך מבחי' המוחין המוגבלי' בכלים כו' כמשל הבן שנמשך ממוח האב כידוע, והיינו שרש מחצב תולדות הנשמות שנק' בנים כמ\"ש בני<sup data-n=\"1755\">29</sup> בכורי ישראל בנים<sup data-n=\"1756\">30</sup> אתם לה' כו', אבל שרש מחצב התהוות המלאכים נמשך מבחי' כלים החיצוני' דז\"א שנק' ירכין כלומר בחי' נצח והוד שמגלין השפע בבחי' חיצוניו' בלבד כנ\"ל, וגם במל' אינו אלא בחי' רגלין דנוק' כו'. ואע\"פ שגם בבחי' נצח שבחסד דז\"א ונוק' דז\"א יש ג\"כ מהארת המוחין חב\"ד דז\"א ע\"י בחי' התלבשות דחב\"ד בחג\"ת וחג\"ת בנה\"י כנ\"ל, דהיינו שהחכ' מתלבש בחסד וחסד בנצח כו'. מ\"מ כ\"ז אינו אלא בחי' חיצוני' השפע כו', משא\"כ בחי' המוחין חב\"ד שבנצח דז\"א ההמשכת מ\"ד שהוא בחי' פנימי' השפע כו'. וזהו עיקר ההפרש בין נשמו' למלאכים גם בהיותם בשרש ומדריגה א' בבחי' החסדי' או בבחי' הגבורות כמו נשמת א\"א ע\"ה שנק' איש החסד כמ\"ש תתן<sup data-n=\"1757\">31</sup> אמת ליעקב חסד לאברהם מפני שהי' מרכבה לבחי' חסד דז\"א מצד שרש נשמתו שנמשכה מבחי' הכלי' הפנימי' דחכ' שבחסד דז\"א כו'. משא\"כ בחי' מדריגה דמיכאל הגם ששרשו ג\"כ מבחי' החסד אבל הוא רק מבחי' נצח שבחסד, והגם שבו מלובש גם מבחי' החכ' שבז\"א כנ\"ל אבל אינו אלא בחי' חיצוני' השפע, ועד\"ז גבריאל ויצחק כו' וד\"ל. ונמצא דאפי' מי שאין לו רק נפש דעשי' מ\"מ שרשו מבחי' פנימי' הכלים דז\"א דעשי' והוא גבוה ממלאך דעשי' שנמשך מחיצוני' הכלים כו', כי גם מיחוד זו\"נ דעשי' נולדי' נשמו' אלא שהן בבחי' נפש, ואותן שביצי' הן בבחי' רוח כו' כמ\"ש בזהר ובע\"ח. ובכ\"ז יובן הטעם שאין אומרי' המלאכי' קדושה למעלה עד שיאמרו ישראל למטה כו' כמ\"ש<sup data-n=\"1758\">32</sup> בזהר ע\"פ גבורי כח עושי דברו כו' וכמ\"ש חונה<sup data-n=\"1759\">33</sup> מלאך ה' סביב ליראיו סביב דוקא וד\"ל. ובכ\"ז מובן בתוס' ביאור יותר ענין ישראל לי ראש וגם ישראל<sup data-n=\"1760\">34</sup> נק' ראשי' כו' להיות שרשם מבחי' פנימיו' הכלי' דחב\"ד דז\"א כנ\"ל וכמארז\"ל ישראל<sup data-n=\"1761\">35</sup> עלה במח' כו' וד\"ל.",[["1753","27","<b>אור זרוע לצדיק</b>: תהלים צז, יא."],["1754","28","<b>אשה כי תזריע</b>: ויקרא יב, כ."],["1755","29","<b>בני בכורי ישראל</b>: שמות ד, כב."],["1756","30","<b>בנים אתם לה'</b>: דברים יד, א."],["1757","31","<b>תתן אמת ליעקב חסד לאברהם</b>: מיכה ז, כ."],["1758","32","<b>כמ\"ש בזוהר ע\"פ גבורי כח עושי דברו</b>: זח\"ג קצ, ב. וראה בארוכה אוה\"ת פנחס ע' א'רד. ובכ\"מ."],["1759","33","<b>חונה מלאך ה' סביב ליראיו</b>: תהלים לד, ח."],["1760","34","<b>ישראל נק' ראשית</b>: ראה מדרשים ר\"פ בראשית. ובכ\"מ."],["1761","35","<b>ישראל עלה במח'</b>: ב\"ר בתחילתו. ובכ\"מ."]]],[2101000279,"<b>אך</b> עדיין י\"ל עדיין למה אמר בפי' ישראל לי ראש מאחר דקאי רק בבחי' חכ' שבמדות שנק' חב\"ד דז\"א כנ\"ל, וכל ראש הוא בבחי' החכ' עצמה שנק' ראשי' כמ\"ש ראשי' <sup data-n=\"1762\">36</sup>חכ' ונק' ראש כמ\"ש קורא<sup data-n=\"1763\">37</sup> הדורות מראש כו', ומכ\"ש באמרו לי ראש דמשמע דראשי' דחכ' גם לי הוא בבחי' הביטול וכמ\"ש והחכ'<sup data-n=\"1764\">38</sup> מאין תמצא כו'. אך הענין הוא דמה שהחכ' נק' ראשי' הוא מטעם שבה הוא ראשי' הגילוי מאא\"ס להיות מתגלה במציאת ומדריגות פרטי דבר מה. וכמשל באדם, הנה ראשי' גילוי אור עצם הנפש בגוף הוא בבחי' החכ' והמוחין שבראש ומשם הוא אשר מתפשט האור והחיות לכל האברי' שבגוף פנימי' וחיצוני' עד ציפורן הרגל. כידוע בספרי הטבעיי' שיש גידים דקים במוחין שבראש (הנק' נערווין בל\"א) שהמה מתפשטי' בכל אבר ואבר מאברי הגוף גם באברים הפנימי' בריאה ולב וכיוצא ונק' גידי ההרגשה שע\"י גידי מוח הללו שנמצא בכל אבר האדם מרגיש כאב באותו אבר כשיפול בו קלקול או מכה ובלעדי הגידים דקים הללו לא הי' מרגיש כאב כלל (וכידוע בנסיון שהוכה איש חייל אחד בידו ונתקלקל רק הגיד של המוח שביד והי' כל ידו שלם רק שלא הי' מרגיש בה כאב הכאת פצע וגם כשהוא נתן אותה במים רותחין כו'). וגידי המוחין עצמם כשהן בראש המה כוללים לכל מיני החיות הנמצא בכל האברי' פנימי' וחיצוני' ונק' מיתרים והגידי' שמתפשטי' מהם בתוך כל אבר בפרט נק' עצבים והוא מלשון חיבור כמו חבור<sup data-n=\"1765\">39</sup> עצבים כו' שמחבר כל אבר בזולתו וכולם מתחברין במוחין שבראש להיות כח התנועה נמצאת בכל אברי האדם מיד שיעלה ברצון שבמח' ומוחין כמו לפשוט ידו או לכופפה מיד שיעלה במח' שבמוח כו' וכמ\"ש במ\"א. וכמ\"כ יובן בדוגמא למעלה בבחי' המוחין העליוני' ששם הוא ראשי' ההתחלקות וההתגלו' מאא\"ס להאציל או\"כ שהן כדמיון אור וחיות שבאברי אדם כמו שאמר חסד<sup data-n=\"1766\">40</sup> דרועא ימינא כו' וכמ\"ש כמראה<sup data-n=\"1767\">41</sup> אדם בציור רמ\"ח אבריו פנימי וחיצוני' ושם מ\"ה דחכ' איהו ארח כל האצי' כו', דהיינו בחי' הארת אור החכ' המתפשט בכולם דרך צינורות דקים וכמ\"ש כולם<sup data-n=\"1768\">42</sup> בחכ' כו', וכמו המוחין שבראש האדם שהמה כוללים כל החיו' שבאברי' כך בחי' החכ' דאצי' כולל כל ההשתלשלו' דאדם העליון כמ\"ש בע\"ח דאור אבא הוא שרש כל האצי' כו' שמשם מתפשט לכל או\"כ שנק' חיוהי וגרמוהי כו' וד\"ל.\n<b>וז\"ש</b> ישראל לי ראש, כי הנה ראש הוא בחי' גידי המוחין עצמם שנק' ראש מטעם הנ\"ל שמתפשטי' בכל האברי' וכללות השתלשלותם הוא שנמשכין בחג\"ת דז\"א ונק' חב\"ד שבמדות, ואח\"כ מתפשטי' בנה\"י וע\"י אמצעי' ג' כלים דחב\"ד כו' כנ\"ל מתפשטי' עד שיש בחי' חכ' גם בחסד שבמל' שמקבל מנצח דחסד דז\"א וכיוצא. ובזה יובן איך שיוכל להתהוות בריאה מוגבלת מאור המאציל כמו מאור",[["1762","36","<b>ראשית חכ'</b>: תהלים קיא, י."],["1763","37","<b>קורא הדורות מראש</b>: ישעי' מא, ד."],["1764","38","<b>והחכ' מאין תמצא</b>: איוב כח, יב."],["1765","39","<b>חבור עצבים</b>: הושע ד, יז."],["1766","40","<b>חסד דרועא ימינא</b>: ת\"ז בהקדמה ד\"ה פתח אליהו."],["1767","41","<b>כמראה אדם</b>: יחזקאל א, כו."],["1768","42","<b>כולם בחכ'</b>: תהלים קד, כד."]]],[2101000280,"חסד שבחכמה דאצי' הבא בהתלבשו'<sup data-n=\"1769\">43</sup> עד נצח שבחסד דז\"א ומשם במל' עד נצח שבחסד שבמל' ומשם מתהווה בחי' חסד דבריאה מאין ליש כמו נשמת אברהם או מלאך מיכאל ששרש<sup data-n=\"1770\">44</sup> שניהם מקבלי' מבחי' החסד כנ\"ל. אמנם בלתי בחי' החכ' לא הי' מתהווה בחי' חסד מוגבל מחסד המאציל, וכמו משל גידי המוח שמתפשטין ממוחין שבראש גם עד ציפורן הרגל כו'. והנה כ\"ז הוא בבחי' הארת המוחין בבחי' גילוי דוקא עד\"מ גידי המוחין שבאדם, אבל בחי' אור החכ' עצמה קודם שתאיר בגילוי במוחין הוא אור נעלם עדיין מבלי ימצא בו בחי' התחלקות אור וחיות של האברי'. וכמו שאנו רואים שבעצם הנפש שבאור חכ' עצמה קודם התלבשותה בגוף אין שינוי כלל בין בריא' לבריאה בין בנפש אדם בין בנפש בהמה. כי הנה אנו רואים שיש חושים משתנים לבריאה זו מזולתה בנפשו' האדם שזה יש לו חוש הראי' בתוקף יותר מזולתו או חוש השמיעה וחוש הריח וכמ\"כ כחות הפנימי' כמו כח השכל או כח המדו' והדיבור כולם משתני' מאד בין אדם לחבירו. וגם בנפשו' הבהמות יש שינויי' רבים כאלה בחושיהם הגשמיי' כמו שיוכל להיות חוש הריח בבהמה וחי' זו יותר מזולתה, ויש חוש אחר שהוא בתוקף בזולתו יותר, ויש שחסירים חושי' לגמרי בחי' זו וישנה בזולתה. וכ\"ז אינו שינוי כלל בעצם נפש האדם ונפש הבהמה רק באופן התלבשותם בחומר גופם הטבעי באדם למינהו ובבהמה למינה כו'. והמופת ידוע מאשר לא יפגם ויחסר כח מכחות הנפש גם כשיפגם פגם וחסרון באבר א' כמו בחסרון היד והעין והאזן שהרי כח המוליד מוליד בדומה לו, וגם שהוא סומא וקיטע יוליד ולד שלם כו', וזהו הוראה גמורה שבעצם הנפש עדיין אין בה התחלקו' אור וחיות נגלה במציא' עד שיפול בו שינוי מצד חסרון האבר כו' וד\"ל. ובכ\"ז מובן פי' לי ראש משום דגם בחי' המוחין שבראש הנק' ראש אינו אלא בחי' גילוי לגבי עצם אור החכמה שלמעלה מבחי' התחלקות (והוא נק' אור אבא דטמיר ונעלם והיינו בחי' חי' כו'). וגם הרי החכ' עצמה נמשכה מאין ליש וכמ\"ש והחכ' מאין כו', ע\"כ אמר לי ראש כו'. אך כשמתפשט בחג\"ת ונה\"י בכלים מכלים שונים נק' ישראל, והוא בחי' ז\"א דאצי' שכולל ו\"ק יום א' חסד ויום ב' גבורה כו' אך עליהם נאמר קורא הדורות מראש כו' וד\"ל.\n<b>והנה</b> ארז\"ל כשם<sup data-n=\"1771\">45</sup> שא\"א לעולם בלא רוחות כך א\"א לעולם בלא ישראל וזה המאמר פלאי לכאורה דמה שייכות יש לרוחות המנשבות בעולם עם ישראל לדמותן זע\"ז כו'. אך הענין הוא משום דשרש בחי' הרוח למעלה הוא בחי' ת\"ת ממוצע בין חו\"ג כידוע דהרוח ממוצע בין אש ומים והוא מדתו של יעקב שנק' בריח התיכון שמבריח מן הקצה לקצה, והיינו מדריגת ישראל ולכך דימה את הרוח עם ישראל דכשם שא\"א לעולם בלא רוחות המנשבות כך א\"א לעולם בלא ישראל כו'.",[["1769","43","<b>בהתלבשו'</b>: בכת\"י ב: בהשתלשלות."],["1770","44","<b>ששרש</b>: בכת\"י ב וכת\"י ג: שמקבלים."],["1771","45","<b>כשם שא\"א לעולם בלא רוחות כך א\"א לעולם בלי ישראל</b>: תענית ג, ב. זח\"ב ה, ב."]]],[2101000281,"<b>ולהבין</b><sup data-n=\"1772\">46</sup> ביאור הדברי' הנה יש להקדי' תחלה בשרש ענין הרוח, דהנה ידוע שיש ד' יסודות אש רוח מים עפר ויסוד האש גבוה במעלה מכולן, וע\"כ אנו רואים שיש בטבע האש לעלות למעלה מעלה מכל היסודו' גם מיסוד הרוח, שהרי אין בטבע הרוח לעלות למעלה כ\"כ רק הוא מתפשט לצדדיו בלבד. אמנם הנה אעפ\"י שיש הוראה בטבע האש שעולה למעלה שהוא יותר נעלה מכל היסודות מ\"מ במהות מציאות האש הנה אנו רואי' שהוא למטה הרבה במדריגה ממציאת הרוח שהרי האש גשמי הוא ונתפס במישוש וגם נתפס בחוש הראות שנראה לעין גשמי, משא\"כ יסוד הרוח שהוא כמו האויר שאינו נתפס במישוש כלל כי הוא דק יותר, וגם אינו נתפס בראות מפני דקותו, וגם אם נראה לעין קצת הוא נראה בדקות גדולה, ומכ\"ש הרוח שאינו האויר אלא הוא כח רוחני הדוחה את האויר לצדדיו (ולמעלה הן המלאכי' שנאמר בהן עושה<sup data-n=\"1773\">47</sup> מלאכיו רוחות וכמו רוח<sup data-n=\"1774\">48</sup> אלקים מרחפת כו') שאינו נראה כלל, ומ\"מ מציאותו נודע בהתגלו' גדולה כמו רוח חזק מאד שמשמיע קול רעש גדול כידוע. אך הענין הוא דאש היסודי הרוחני הוא אויר דק בתכלית מופשט מכל גשם הנתפס במשקל או בראות כלל והאש הגשמי עולה למקור חוצבו וכמ\"ש במ\"א בענין אור מים רקיע שהאור<sup data-n=\"1775\">49</sup> הזה הוא למעלה מן האויר שנק' יסוד הרוח כו' והאויר שלמטה הימנו שיש לו תפיס' במשקל ובראות בדקות עכ\"פ הוא ממוצע בין יסוד המים ובין יסוד האש הדק הנ\"ל, והיינו הרוח שיש בו כח הדוחה את האויר למעלה או למטה וירידתו למטה הוא ענין יסוד המים כמו שמתהווה הענן מהגשמת האויר וירידתו למטה כמ\"ש<sup data-n=\"1776\">50</sup> הרמב\"ם דאידי הארץ עולין נ\"א<sup data-n=\"1777\">51</sup> מיל מן הארץ ונעשין אויר גשמי מעט מעט בירידתם למטה מטה עד שמתגשמי' ונעשי' עבים ועננים גשמיי' להמטיר מטר, והוא ע\"י כח הדוחה את האויר למטה והיינו הרוח שנק'<sup data-n=\"1778\">52</sup> בגמ' זיקי דמקמי מיטרא כמ\"ש משיב הרוח ואח\"כ מוריד הגשם, וגם פעולת הרוח להעלות העבים הכבדי' שירדו בתחתית הארץ להיו' עולין למעלה וימטירו מטר על מקומות הצריכים וכמ\"ש מעלה<sup data-n=\"1779\">53</sup> נשיאי' מקצה הארץ (והיינו<sup data-n=\"1780\">54</sup> כמ\"ד דעבים מן הים מתמלאים ולא מן הים ממש אלא מלחלוחית האידין שעולין מן הים יותר מן היבשה וגם מטעם זה הרוחות חזקות יותר בים מיבשה כידוע).\n<b>והנה</b> יש עוד רוח שנק' בגמ' זיקא דבתר מיטרא, והוא הרוח המנשב על עפר הארץ ממש ונכנס בתוך תוך חלקי עפר הארץ, ופעולתו הוא שמחליש הקושי והיבשות שיש בעפר הארץ ומרפה ארעא להיות מתלחלחת הטיב מן המטר כדי",[["1772","46","<b>ולהבין. . יש להקדים תחילה בשרש ענין הרוח</b>: בהבא להלן ראה המשך מים רבים תרל\"ו פק\"ד ואילך. וראה ג\"כ ביאוה\"ז מד, א. סידור רעג, ג. אוה\"ת תרומה ע' א'שצט. אוה\"ת תזריע כרך ב' ע' תקיט ואילך."],["1773","47","<b>עושה מלאכיו רוחות</b>: תהלים קד, ד."],["1774","48","<b>רוח אלקים מרחפת</b>: בראשית א, ב."],["1775","49","<b>שהאור</b>: בכת\"י ב וכת\"י ג: שהאויר."],["1776","50","<b>כמ\"ש הרמב\"ם דאידי הארץ עולין נ\"א מיל מן הארץ</b>: פיה\"מ ברכות פ\"א, מ\"א. וראה ג\"כ מאמרי אדהאמ\"צ ויקרא ח\"א ע' קנד."],["1777","51","<b>נ\"א</b>: בכת\"י ג: כ\"א."],["1778","52","<b>שנק' בגמ' זיקי דמקמי מיטרא</b>: ראה תענית ג, ב."],["1779","53","<b>מעלה נשיאים מקצה הארץ</b>: תהלים קלה, ז."],["1780","54","<b>והיינו כמ\"ד דעבים מן הים</b>: תענית ט, ב."]]],[2101000282,"שתוציא כחה הטיב להצמיח כל צמח. ונמצא יש ברוח כח המעלה וכח הדוחה, כח הדוחה את האויר הוא בעננים כנ\"ל וכח המעלה הוא המנשב בארץ להעלות רוח של כח הצומח שבארץ ע\"י שמרפה ארעא ומחליש כח הארץ כנ\"ל. וכ\"ז מפני שיסוד הרוח הוא בחי' ממוצע בין יסוד האש ויסוד המים כנ\"ל, וטבע יסוד המים לירד מגבוה לנמוך כמו הגשמת האויר מחמת יסוד המים שיורד מטה מטה והן המים שבעבים שיורדין מגבוה לנמוך, וטבע יסוד האש שעולה למעלה במקור חוצבו שהוא אש יסודי הנ\"ל שאינו יורד למטה מטה כלל וכלל כנ\"ל (וכמ\"ש בס' המחקר שיסוד האש היסודי הנ\"ל איננו אויר שיחי' האדם ממנו וכבר נסו והעלו לשם בגובה<sup data-n=\"1781\">55</sup> חיה אחת ומתה כי רוח החיים שבאדם ובהמה הוא מקבל מבחי' הרוח שנק' אויר סתם כנ\"ל וד\"ל). ומפני שיסוד הרוח שנק' אויר סתם ממוצע וכלול מבין שני היסודו' הרוחניי' דאש ומים הנ\"ל ע\"כ יש בכחו שני הפכי' הנ\"ל להיות בו כח הדוחה את האויר וכח המעלה את אויר הארץ שתוציא צמחה כי כל צמח אינו מצמיח רק מיסוד הרוח שמורכב ממים ועפר והעפר שאיננו מצמיח הוא מחסרון יסוד הרוח כמו האבן או העפר שקשה כסלע אעפ\"י שיש באבן מיסוד המים כמ\"ש אבנים<sup data-n=\"1782\">56</sup> שחקו מים וכתיב הכה<sup data-n=\"1783\">57</sup> צור ויזובו מים. ונמצא מובן שכל העלאת כח הרוח<sup data-n=\"1784\">58</sup> המצמיח שבארץ הוא מחמת יסוד הרוח המנשב בארץ (כי<sup data-n=\"1785\">59</sup> רוח אייתי רוח כו' וכמ\"ש בסוף ס' הע\"ח דד' חלקי דצח\"ם הן ד' יסודות דארמ\"ע והדומם הוא העפר והצומח הוא הרוח והחי הוא המים (והוא ב' מדריגות שברוח רוח הדוחה למטה שממנו מתהווה המים וממנו<sup data-n=\"1786\">60</sup> יחי' רוח החי כנ\"ל וגם ממנו יצמח כל צמח כנ\"ל, והב' בחי' יסוד האש שכלול בו שהוא בחי' מדבר דהיינו מקור מחצב רוח האדם דוקא שע\"ז אמר כי רוח<sup data-n=\"1787\">61</sup> האדם הוא העולה למעלה ורוח הבהמה היא היורדת למטה. וב' מיני רוחות הללו דאדם ובהמה זה עולה למעלה וזה יורד למטה הכל כלול ביסוד הרוח מפני שהוא בחי' ממוצע מאש ומים כנ\"ל וד\"ל). וגם כל ירידת העבים להמטיר מטר הוא מן הרוח, והן ב' מיני רוחות זיקא דמקמי מיטרא וזיקא דבתר מיטרא. וע\"כ הרוח אינו נראה ומ\"מ מציאותו נודע בהתגלות גדולה כנ\"ל, וכ\"ז מפני שהוא ממוצע מאש ומים יחד, וכמו רוח הבל הלב שמורכב מאש ומים כו'. וע\"כ ארז\"ל דא\"א לעולם כלל בלא רוחות המנשבי' בעולם לפי שכל חיות צומח וחי הכל מן הרוחות המנשבות כנ\"ל, והעיקר הוא בחי' כח המעלה וכח המדחה שברוח שבזה תלוי כל חיות ד' חלקי דצח\"מ שבעולם כנ\"ל וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למשכיל<sup data-n=\"1788\">62</sup> למעלה בהיות ידוע בשרש בחי' הרוח למעלה שהוא בחי' הת\"ת הממוצע בין חו\"ג שנק' אש ומים והוא<sup data-n=\"1789\">63</sup> מדתו של יעקב שנק'",[["1781","55","<b>בגובה</b>: בכת\"י ב ליתא תיבה זו."],["1782","56","<b>אבנים שחקו מים</b>: איוב יד, יט."],["1783","57","<b>הכה צור ויזובו מים</b>: תהלים עח, כ."],["1784","58","<b>הרוח</b>: בכת\"י ב וכת\"י ג: הרוחני."],["1785","59","<b>כי רוח אייתי רוח</b>: זח\"ב קסב, ב. וראה אוה\"ת בראשית רפו, א."],["1786","60","<b>וממנו. . כנ\"ל</b>: בכת\"י ב: וממנו רוח החיים כנ\"ל."],["1787","61","<b>רוח האדם הוא העולה למעלה</b>: קהלת ג, כא."],["1788","62","<b>למשכיל</b>: ע\"כ נמצא בכת\"י ג וחסר הסיום."],["1789","63","<b>והוא מדתו של יעקב שנק' בריח התיכון</b>: זח\"ב קעה, ב. ועוד. וראה אוה\"ת ויחי שצה, א."]]],[2101000283,"בריח התיכון המבריח מן הקצה לקצה כנ\"ל, דהיינו בחי' הקו האמצעי שכולל ב' הקוין חח\"נ בג\"ה כידוע, וידוע דקו האמצעי עולה עד<sup data-n=\"1790\">64</sup> הכתר שנק'<sup data-n=\"1791\">65</sup> אויר קדמון שהוא למעלה מבחי' חו\"ב או חו\"ג שבב' הקוין (והוא בדוגמת האש היסודי למטה וכמ\"ש במ\"א). והענין הוא ע\"ד הנ\"ל ברוח הגשמי שהוא דק מן האש הגשמי ויש בו כח הדוחה את האויר להיות יורד מטה והיו<sup data-n=\"1792\">66</sup> למים בעבים ועננים כו' כך בחי' הרוח דקו האמצעי דת\"ת יש בכחו להמשיך מבחי' הכתר להיות יורד למטה והוא מקור כל בחי' מיין דכורין שהן מי החסדי' שיורדי' למטה מטה מבחי' אור אבא עד בחי' מ\"ד דז\"א שנמשכי' לבחי' מל' דאצי' שנק' ג\"כ<sup data-n=\"1793\">67</sup> רוח כמשל הזרע דמ\"ד גשמיו' שנק' רוח כמ\"ש כי<sup data-n=\"1794\">68</sup> רוח יזרעו כו', והוא טפת מי החסדי' ובתוכה יש כח רוחני ממש שהוא עיקר המוליד ומצמיח תולדה חדשה כמו ולד וכן בזריעת התבואה כו' וכל צמיחה הוא מיסוד הרוח דוקא כנ\"ל רק שהוא מורכב ביסוד המים כו', וגם יש בכחו כח המעלה את הרוח כמו ברוח הגשמי שבכחו להעלות רוח כח המצמיח שבארץ כנ\"ל (והוא הנק' כח המ\"ד המעלה מ\"נ) דהיינו שהוא נותן כח במ\"נ להעלות כו' משום דרוח אייתי רוח כנ\"ל, שהרי כמשל כח המצמיח שבארץ כך הוא למעלה ענין כח העלאת מיין נוקבין ועד\"מ למטה מיין נוקבי' גשמיי' כמ\"ש אשה<sup data-n=\"1795\">69</sup> כי תזריע כו' וכמארז\"ל דמן<sup data-n=\"1796\">70</sup> האודם דנוק' ממנו מתהווה בשר כו' והן נק' ג\"כ רוח שמלובש בזרע מי הגבורות דנוק' שעולין מלמטה למעלה כמ\"ש בזוהר אשדי מיין לקיבלי' כו' וכמ\"ש במ\"א. והנה הכח שמעלה בחי' רוח דמ\"נ הוא נמשך ג\"כ מכח המ\"ד ונק' כח המעלה מ\"נ כידוע, והוא כמשל הרוח המנשב בארץ לעורר ולהעלות כח המצמיח שבה כנ\"ל. ונמצא יש ברוח המ\"ד בחי' ירידה ובחי' עלי' וכלשון המאמר דרוח אייתי רוח ואמשיך רוח כו', וכ\"ז מפני שהוא כלול מאש ומים יחד וכנ\"ל בענין זיקא דמקמי מיטרא וזיקא דבתר מיטרא כו', וע\"כ ממילא מובן דכשם שא\"א לעולם הגשמי בלא רוחות המנשבי' מלמעלה<sup data-n=\"1797\">71</sup> למטה ומלמטה למעלה כנ\"ל כן א\"א לעולם העליון הנאצל שהוא בחי' מ\"ד ומ\"ן וזו\"ן ואו\"א בלא בחי' רוחות המנשבות בקו האמצעי שיש בכחו מקור המשכות מ\"ד ומקור העלאות מ\"נ והוא מדתו של יעקב שנק' בריח התיכון שמבריח בקצה העליון דפנימי' הכתר ומבריח עד קצה התחתון שבמל' להוציא צמחה בהעלאת מ\"נ כו' וד\"ל.\n<b>ובכ\"ז</b> יובן ג\"כ שרש התורה והמצות. דהנה המצות<sup data-n=\"1798\">72</sup> נק' בגמרא בשם פירות כמ\"ש גבי עגלה ערופה שצריכה נחל איתן אשר לא נזרע כו' דלא עביד פירות מאי פירות מצות כו'. והנה התורה נק' רוח כי שרש התורה הוא ג\"כ בבחי' קו",[["1790","64","<b>עד הכתר שנק' אויר קדמון</b>: ראה ת\"ז תס\"ט (קד, ב). ז\"ח צו, ג. ענין זה נמצא ג\"כ בהמשך מים רבים תרל\"ו ע' קיב, ושם הגירסא שנק' אור קדמון. ראה ת\"ז ת\"ע (קלה, ב). לקוטי לוי יצחק לזוהר נשא ע' שנה. ס' הערכים חב\"ד ח\"ד ע' תעט ואילך."],["1791","65","<b>שנק' אויר קדמון</b>: ראה מ\"מ וציונים שבסוף הספר."],["1792","66","<b>והיו למים</b>: בכת\"י ב: והי' למטה."],["1793","67","<b>ג\"כ</b>: בכת\"י ב: ליתא תיבה זו."],["1794","68","<b>כי רוח יזרעו</b>: הושע ח, ז."],["1795","69","<b>אשה כי תזריע</b>: ויקרא יב, כ."],["1796","70","<b>דמן האודם דנוק' ממנו מתהווה בשר</b>: נדה לא, א."],["1797","71","<b>מלמעלה. . רוחות המנשבות</b>: בכת\"י א ליתא תיבות אלו, וכנראה הוא דילוג המעתיק."],["1798","72","<b>המצות נק' בגמ' בשם פירות</b>: סוטה מו, א."]]],[2101000284,"האמצעי דת\"ת דז\"א וכולל ב' קוין שהרי עיקר מצות התורה הוא בהבל קול הדיבור וכמ\"ש ודברת<sup data-n=\"1799\">73</sup> בם כו' ואשים<sup data-n=\"1800\">74</sup> דברי בפיך כו' והוא נק' רוח<sup data-n=\"1801\">75</sup> ממללא שמורכב מאש ומים כנ\"ל, וגם התורה כתיב בה מימינו<sup data-n=\"1802\">76</sup> אש דת למו כו' וכתיב הקול<sup data-n=\"1803\">77</sup> קול יעקב דהיינו קול דתורה כמבואר בזוהר בכמה מקומות. והענין הוא לפי שהתורה היא ג\"כ בחי' ממוצע להמשיך מקור כל המשכות מ\"ד ומקור כל העלאות מ\"נ כנ\"ל בשרש בחי' הרוח למעלה שהרי ידוע שיש כמה מצות שהן בחי' המשכת מ\"ד כמו מצות הצדקה שכוללת כל המצות שבקו הימין חח\"נ כו' כמו מצות תפילין וצצית בחכ' ומצות שבתות ויו\"ט בחו\"ב ותרומות ומעשרות או כמו פסח וסוכות בחסדי' פנימי' ומקיפי' וכי<sup data-n=\"1804\">78</sup>וצא, וכל מצות הקרבנות הוא בקו השמאל בבחי' העלאת מ\"נ והרבה מצות נכללים בזה. אך הנה התורה הוא המקור להמשיך החסדי' במצות ששייכי' לבחי' החסדי' ולהעלות מ\"נ במצות ששייכי' בבחי' הקו השמאל כי מתניתין<sup data-n=\"1805\">79</sup> מלכתא כשגוזר ואומר שזה מצוה וזה אינו מצוה עפ\"י החכ' שבתורה דוקא ויש כמה מיני מ\"ד ומ\"נ במצות וכולן תלויי' בכח רוח חכמה שבהבל הדיבור באותיות התורה דוקא וכמ\"ש ואשים דברי בפיך לנטוע שמים בהמשכת מ\"ד וליסוד ארץ בהעלאת מ\"נ, וכן כתיב אם<sup data-n=\"1806\">80</sup> לא בריתי כו' חוקות שמים וארץ כו'. וע\"ז רמזו רז\"ל באמרם אין<sup data-n=\"1807\">81</sup> העולם מתקיים אלא בהבל תשב\"ר, בהבל דוקא ואין<sup data-n=\"1808\">82</sup> דומה הבל שיש בו חטא כו' כשם שא\"א לעולם בלא רוחות המנשבות. אבל המצות הן הצומחים מארץ העליונה אחר נשיבת רוח קול התורה כמו זיקא דבתר מיטרא שפועל להוציא צמח הארץ כנ\"ל, ולכך נק' המצות פירות וד\"ל.\n<b>אך</b> הנה בגלות הוא בבחי' שינה כמ\"ש עורה<sup data-n=\"1809\">83</sup> למה תישן כו', והיינו בחי' ישראל לי ראש הנ\"ל שהוא בחי' חב\"ד דז\"א כו' הוא בבחי' שינה וצריך לעוררו בבחי' קול דתורה. אבל בביטול תורה מסתלק אא\"ס שבחב\"ד ואינו נק' לי ראש כנ\"ל. וע\"כ עיקר הגלות הוא על ביטול תורה כמ\"ש על<sup data-n=\"1810\">84</sup> מה אבדה הארץ כו' וכמארז\"ל שויתר<sup data-n=\"1811\">85</sup> הקב\"ה על ע\"ז כו' ולא ויתר על ביטול תורה. כי הנה הגם שעבדו ע\"ז ה\"ז פגם בדבר א' פרטי בלבד כמו שאר ל\"ת כשעובר על לאו אחד כמו גזל ועריות וכיוצא. כי בחי' ע\"ז שלהם אינה כע\"ז באוה\"ע עכשיו, אלא הייתה כמו ענין הכישוף וכיוצא שהוא רק להקטיר הקטורת בעבודות שונות כדי להמשיך ממזלות העליונים השפעות גשמיות וכמ\"ש הנשים לירמיהו ומאז<sup data-n=\"1812\">86</sup> חדלנו לקטר למלאכת השמים",[["1799","73","<b>ודברת בם</b>: דברים ו, ז."],["1800","74","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["1801","75","<b>רוח ממללא</b>: ת\"א בראשית ב, ז."],["1802","76","<b>מימינו אש דת למו</b>: דברים לג, ב."],["1803","77","<b>הקול קול יעקב</b>: בראשית כז, כב. וראה זח\"א קנא, א. ובכ\"מ."],["1804","78","<b>כי</b>: בכת\"י ב: כמו."],["1805","79","<b>מתניתין מלכתא</b>: ביצה כח, ב."],["1806","80","<b>אם לא בריתי</b>: ירמי' לג, כה."],["1807","81","<b>אין העולם מתקיים אלא בהבל תשב\"ר</b>: שבת קיט, ב. זח\"א א, ב. ובכ\"מ."],["1808","82","<b>ואין דומה הבל שיש בו חטא</b>: שבת שם."],["1809","83","<b>עורה למה תישן</b>: תהלים מד, כד."],["1810","84","<b>על מה אבדה הארץ</b>: ירמי' ט, יא."],["1811","85","<b>שויתר הקב\"ה על ע\"ז</b>: ירושלמי חגיגה פ\"א ה\"ז. פתיחתא דאיכ\"ר פיסקא ב."],["1812","86","<b>ומאז חדלנו לקטר למלאכת השמים</b>: ראה ירמי' מד, יח."]]],[2101000285,"חסרנו כל כו', והוא איסור לאו בלבד אבל לא שכפרו בעיקר ח\"ו, ע\"כ לא הי' החורבן בשביל עון זה בלבד אלא על עון ביטול תורה שנוגע לכללות כל המצות. כי הגם שעברו על לאו דע\"ז מ\"מ הי' מקיימין כל המצות ושומרין כל ל\"ת והיו מאמינים בה' בכל דבר כנראה ומובן בכתובי' הרבה, וגם אחאב שאל בנביאי ה' והאמין לדבר ה' וכמבואר<sup data-n=\"1813\">87</sup> בדרז\"ל דדורו של אחאב אעפ\"י שרשעי' היו באיסור דע\"ז מ\"מ תלו בטחונם בהקב\"ה בכל צרה או מלחמה כו'. אך עון דביטול תורה נוגע לביטול כל המצות משום דאוריי'<sup data-n=\"1814\">88</sup> מח\"ע נפקת כידוע ומבואר למעלה בפי' לי ראש שראשי' הגילוי דאא\"ס הוא בחכ' שבראש דוקא ומתפשטת בגידי המוח בהתחלקות רבות לכל האברי' כו'. וידוע דרמ\"ח פיקודין נקראי' רמ\"ח אברי' דמלכא שהן בחי' כלים דע\"ס דז\"א ואם אין אא\"ס מאיר בחכ' שבראש ממילא מסתלק מקור השפע לכל רמ\"ח אברי' דמלכא שמקבלי' מבחי' המוחין שבראש כנ\"ל. וא\"כ ע\"י ביטול מצות ת\"ת למטה ששרשה בבחי' החכ' שבראש ממילא יש ביטול לכל המצות כו'. וע\"כ ארז\"ל בראשי' בשביל התורה<sup data-n=\"1815\">89</sup> שנק' ראשי' כמ\"ש ה' קנני ראשי' דרכו כו' שהוא בחי' החכ' שבראש הנק' לי ראש ואח\"כ הנה מתפשט מבחי' החכ' שבראש לכל האברי', והוא הנק' ישראל שהוא בחי' חב\"ד דז\"א כלומר בחי' המוחין שמתפשטי' במדות שבלב ומשם דופק רוח החיים בכל האברי'. וע\"י ביטול תורה לא יש המשכה כלל בחב\"ד שבז\"א מבחי' החכ' עצמה, וממילא הרי המוחין בבחי' שינה עד\"מ באדם התחתון בשעה שהוא ישן הרי בחי' המוחין שבראש מסתלקי' למעלה מן השכל וגם רוח החיים שבלב מסתלק למעלה ולא נשאר רק דפיקו דלבא בחשאי מאד שהוא<sup data-n=\"1816\">90</sup> רק קיסטא דחיותא כו' כמ\"ש בזהר ומבואר במ\"א וד\"ל.\n<b>אך</b> הנה ע\"י מצות ת\"ת למטה מעוררי' המוחין העליוני' מן בחי' השינה כמ\"ש השמיעני<sup data-n=\"1817\">91</sup> את קולך כי קולך ערב, והוא<sup data-n=\"1818\">92</sup> קלא דאוריי' דוקא כמ\"ש בזהר, לפי שהתורה שרשה בבחי' החכ' שבמוחין שבראש וע\"י הקריאה בתורה בהבל הדיבור דוקא, כי התורה שרשה למעלה בבחי' רוח שהוא בחי' קו האמצעי שעולה עד הכתר כנ\"ל, והרי ממשיך אא\"ס בחכ' עי\"ז. וזהו כמארז\"ל שלא<sup data-n=\"1819\">93</sup> חרב בהמ\"ק אלא מפני שלא ברכו בתורה תחלה, פי' שלא המשיכו אא\"ס בחכ' שבתורה ע\"י הברכה שאו' אקבו\"צ על ד\"ת, על דוקא. וד\"ל. וזהו ג\"כ מ\"ש בראשי' בשביל ישראל שנק' ראשי' כו' לפי ששרש ישראל למעלה הוא בבחי' חב\"ד דוקא ומקבלי' מבחי' אור החכ' עד<sup data-n=\"1820\">94</sup>",[["1813","87","<b>וכמבואר בדרז\"ל דדורו של אחאב</b>: ראה ירושלמי פאה פ\"א ה\"א. וראה ס' מאמרי אדה\"ז עה\"ת ע' עג (ובהמ\"מ שם). ועל ענינים ע' פו (ובהמ\"מ שם)."],["1814","88","<b>דאוריי' מח\"ע נפקת</b>: זח\"ב פה, א. קכא, א."],["1815","89","<b>בראשית בשביל התורה</b>: תנחומא (באבער) ר\"פ בראשית פיסקא ג' וה'. לק\"ט שם. רש\"י ורמב\"ן שם. וראה ב\"ר שם. ויק\"ר פל\"ו, ד."],["1816","90","<b>שהוא רק קיסטא דחיותא כו' כמ\"ש בזוהר</b>: זח\"א פג, א."],["1817","91","<b>השמיעני את קולך</b>: שה\"ש ב, יד."],["1818","92","<b>והוא קלא דאורייתא דוקא כמ\"ש בזוהר</b>: זח\"ג סא, א. ריג, א."],["1819","93","<b>שלא חרב ביהמ\"ק אלא מפני שלא ברכו בתורה תחלה</b>: ראה נדרים פא, א. ב\"מ פה, ב. פתיחתא דאיכ\"ר פיסקא ב."],["1820","94","<b>עד</b>: בכת\"י ב ליתא תיבה זו."]]],[2101000286,"שנק' לי ראש כו', וע\"כ ע\"י ישראל דוקא נמשך אא\"ס בחכ' שבתורה, וכנ\"ל בענין המאמר דכשם שא\"א לעולם בלא רוחות כך א\"א בלא ישראל, מפני ששרשם ג\"כ בבחי' הרוח שהוא בחי' ת\"ת דז\"א שנק' בריח התיכון כו' כנ\"ל. וע\"י ביטול תורה גם בכאו\"א מישראל גורם בחי' שינה בבחי' חב\"ד דז\"א שהוא ישראל דלעילא כו', לפי שכל נפש מישראל אפי' קל שבקלים יש לו שרש בבחי' ז\"א דאצי' שהוא ישראל דלעילא שהרי בחי' למ\"ד כלים דז\"א פנימי' ואמצעי' וחיצוני' מתפשטין בבי\"ע ונעשים נר\"נ, נשמה בבריאה רוח ביצי' ונפש בעשי'. וכל א' מישראל אפי' פחות הערך יש לו נפש דעשי' עכ\"פ, והרי שרש נפש דעשי' בבחי' י' כלים החיצוני' דז\"א. וגם זה ידוע דכל א' מישראל גם פחות הערך שאין לו רק נפש דעשי' עכ\"פ מ\"מ יש לו כל בחי' נר\"נ אלא שאין בגילוי אצלו רק בחי' נפש דעשי', ובחי' הרוח שלו נשאר בהעלם ביצי' ובחי' נשמה שלו נשאר בהעלם בבריאה. כי כל עולם כלול מג' מדריגות בי\"ע שהן נר\"נ כו', והרי ארז\"ל דאע\"ג<sup data-n=\"1821\">95</sup> דאיהו לא חזי מזלי' חזי כו', וגם בחי' רוח ונשמה שלו שנשארי' בהעלם בבריאה ויצי' נק' בחי' מזלי' לגבי בחי' נפש דעשי' שמתגלה למטה, וכמ\"כ שרש נר\"נ דבריאה יצי' עשי' בבחי' למ\"ד כלים דאצי' נק' בחי' מזלייהו שלהם כו'. וא\"כ ע\"י ביטול תורה דנפש דעשי' ג\"כ גורם בחי' שינה במוחין דז\"א מאחר שמוחין דז\"א מתפשטין בג' מיני כלים באצי' ונעשי' נר\"נ בבי\"ע כו'. וז\"ש אין<sup data-n=\"1822\">96</sup> קורא בשמך כו' דקאי על ביטול תורה, כי הקורא בתורה קורא וממשיך אא\"ס בחב\"ד כו' ולהיפך אפי' א' שקורא בתורה שכינה עמו לקבל מבחי' המוחין דז\"א כו' וד\"ל.\n<b>והנה</b> י\"ל שרש ענין השינה למעלה מהו, דהנה אנו רואים בבחי'<sup data-n=\"1823\">97</sup> שינה הגשמי' למטה שאינה באה לאדם רק בסיבת המאכל שאוכל כידוע, ויש בזה ענין עמוק מאד. דלכאורה יפלא דבר הזה במאד, שהרי אור השכל מתלבש במוחין שבראש תמיד מפני שהמוח הוא כלי וחומר מוכן לקבל צורת אור השכל כמו כח הראי' בכלי העין, ולמה ישתנה אור השכל שלא יאיר אורו בכלי המוח ויסתלק גם מלחשוב ולהרהר במוח מפני שאכל מאכל בשר או לחם, וגם ישתנה אור וכח הראי' מלהתלבש בחומר כלי העין כשאכל מאכל כו'. אך הענין הוא משום דבחי' השכל שבכלי המוח הוא עיקר נפש השכלית הנק' בחי' מדבר והמוחין שבראש הן בחי' הכלי שלה. וכאשר אוכל האדם מאכל בשר או לחם שהוא בחי' חי ובחי' צומח שהן למטה ממדריגת בחי' מדבר והמאכל מתעכל ונברר הפנימי' שבו ועולה למוח כידוע, הנה מפני שבחי' החי דבשר וצומח דלחם הן דברי' זרים נבדלים ומרוחקים מבחי' מדבר שהוא אור השכל ע\"כ בהעלותם לכלי המוח ויתערבו כחם בכח וחומר המוח שבראש אזי יסתלק אור השכל ולא יאיר בכלי המוח לפי שאין החי וצומח מהדברי' המוכנים לקבל צורת השכל כלל, וכמו זר נחשבו לגביו. ומזה באה סיבת השינה בכלי המוח שהוא הסתלקות השכל והמח' מכלי המוח עד שגם אור וכח",[["1821","95","<b>דאע\"ג דאיהו לא חזי מזלי' חזי</b>: מגילה ג, א."],["1822","96","<b>אין קורא בשמך</b>: ישעי' סד, ו."],["1823","97","<b>בבחי' שינה. . בסיבת המאכל שאוכל</b>: ראה יומא יח, א. ובהבא להלן ראה ג\"כ תו\"ח שמות נב, א ואילך. ביאוה\"ז להצ\"צ ע' קצט. ובכ\"מ."]]],[2101000287,"הראי' שבכלי העין יסתלק ויסגור עיניו בשינה, מפני שיניקת כח הראי' באה מכח ואור השכל שבמוח כידוע. ומ\"ש הרמב\"ם דהקיטורי' העבים העולים מפסולת המאכל דוקא הוא הגורם בחי' השינה גם זה אמת משום דבחי' פנימי' החיות שבמאכל עולה לכלי המוח ומתהפך לבחי' דקות כלי המוח ממש לקבל תוס' אור השכל כנראה בטבע אוכל המאכל שמחזק לאור השכל שיאיר בתוס' וכמא'<sup data-n=\"1824\">98</sup> ר\"נ עד דלא אכילנא בשרא דתורא כו', וכן לחם בגי' מזלא כו' (וכמ\"ש במ\"א בענין אין<sup data-n=\"1825\">99</sup> התינוק יודע לקרות אבא עד שיטעום טעם דגן דוקא כו'. אך פסולת המאכל שהוא בחי' חי ולא נהפך ונכלל בבחי' מדבר הוא אשר נחשב לגבי השכל כמו דבר זר לבלתי ישכון אור השכל בכלי המוח, והיינו הקיטורים העבים שעולים בכלי המוח שמבלבלי' לאור השכל עד שאינו מתיישב כלל בכלי המוח ויסתלק מעט מעט עד שמסתלק לגמרי גם מלחשוב מחשבה בעלמא לא יוכל כי הקיטורים הזרים הללו כמו מכסה גשמיו' מכסים על המוח לבלתי יקבל המוח צורת אור השכל כו'. אך לפ\"ז למה התינוק שאינו אוכל לחם ובשר יוכל לישן. הענין הוא מפני שיונק חלב שהוא דבר היוצא מן החי שלמטה ממדריגת נפשו השכליו' שבכלי מוח התינוק אעפ\"י שאין בנפשו השכלית רק כח המדמה בלבד. ומזה הטעם יתורץ מה שהבהמה תישן אעפ\"י שאין לה נפש השכלי' כלל, כי יש לה כח המדמה עכ\"פ לצייר דבר מה במוחה הגשמי ולרוץ לדבר הנחמד לה ולברוח מדבר השנאוי לה, ומפני שאוכלת בחי' צומח כשעורי' ותבן שלמטה מבחי' הדמיון שבמוחה הגשמי ע\"כ תפול במוחה תרדמה ושינה מפסולת הקיטורי' שנחשבו כמו זר כו' (וגם אוכלת בשר החי כמו הארי והדוב שטורפין בשר החי ואוכלין, מ\"מ נחשב כמו זר לגבי כח המדמה שבנפשו הבהמיות כו'). ומה שיש שינה לולד במעי אמו היינו מפני שהוא<sup data-n=\"1826\">100</sup> אוכל מה שאמו אוכלת כו' אע\"פ שנק' אכילה פנימי' בלא בירור פסולת כלל, וכמ\"ש<sup data-n=\"1827\">101</sup> במ\"א ע\"פ רפאות תהי לשרך, שמקבל החיות דרך הטבור כו' מ\"מ יש בו בחי' שינה כשאמו ישינה כו' וד\"ל).\n<b>והנמשל</b> מבחי' שינה הגשמי' הנ\"ל יובן למשכיל למעלה ברוחניו' דנפש אלקי', וממנה יובן למעלה מעלה בבחי' שינה באצי' בחב\"ד דז\"א כו' כנ\"ל. דהיינו כמו שמבואר למעלה בשינה הגשמי' שמבחי' פסולת המאכל שלא נהפך לבחי' מדבר כמו זר נחשב וגורם הסתלקות השכל כו', כך מפני התמשכות האדם בנפשו הבהמיו' אחר גשמיות שנק' בחי' חי לגבי בחי' נפש האלקי' שנק' אדם כו' כמו זר נחשב ומכסה על כלי המוח ששם משכן נר\"נ שבאדם ששרשם בבי\"ע כנ\"ל לבלתי ישכון אור הנפש האלקי' בעשי', ולא יאיר בבחי' רוח ביצי' ולא יאיר אור הנשמה בבריאה כו', עד שגם שרשם בבחי' כלים דז\"א יסתלקו בבחי' שינה כו'. וכללות בחי' השינה למעלה הוא בחי' הסתלקות המוחין דאו\"א מכלי חב\"ד דז\"א",[["1824","98","<b>וכמא' ר\"נ עד דלא אכילנא בשרא דתורא</b>: ב\"ק עב, ב."],["1825","99","<b>אין התינוק יודע לקרות אבא</b>: ברכות מ, א. וראה סידור שער בהמ\"ז קז, ג ואילך."],["1826","100","<b>שהוא אוכל מה שאמו אוכלת</b>: נדה ל, ב."],["1827","101","<b>וכמ\"ש במ\"א ע\"פ רפאות תהי לשרך</b>: משלי ג, ח. וראה תו\"א מג\"א (הוספות) קכד, ב."]]],[2101000288,"שנק' ישראל לי ראש כנ\"ל עד שלא יאיר אא\"ס גם בחכ' שהוא מקור המוחין שבז\"א כנ\"ל. וכ\"ז מפני בחי' הקיטורי' העבי' שעולין מבחי' נוגה דבי\"ע המכסים על כלי חב\"ד דז\"א כאשר אינם מתבררי' יפה יפה כמשל פסולת המאכל שאינו נברר ונחשב כמו זר כו'. והיינו בזמן הגלות דוקא שהע' שרים דנוגה לא נתבררו וגוברין על כלי המוחין כו', וכמ\"ש<sup data-n=\"1828\">102</sup> בזהר קוב\"ה בגלותא אסתלק לעילא לעילא, שהוא בחי' הסתלקות המוחין מחב\"ד דז\"א הנק' דורמיטא כידוע. אבל בזמן בהמ\"ק כתיב הנה<sup data-n=\"1829\">103</sup> לא ינום ולא יישן שומר ישראל. וכמ\"ש<sup data-n=\"1830\">104</sup> במשנה יוחנן כ\"ג ביטל את המעוררי' שהיו או' עורה למה תישן כו', לפי שבזמן בהמ\"ק היו הקרבנות מבררי' כל הע' שרים דנוגה דבי\"ע ונבדל הפסולת דנוגה מן הטוב לגמרי, וכאשר אין פסולת עולה למוח ממילא אין מכסה על המוח למנוע<sup data-n=\"1831\">105</sup> הארת אור החכ' כו' והוא בחי' עינא<sup data-n=\"1832\">106</sup> פקיחא דלא נאים כלל, שנחשב מז' תיקונין דגלגלתא דא\"א שלמעלה גם מבחי' ח\"ס שהרי מסתלק לפרקים גם כח המשכיל מפני מניעת הכלי דמוח החכ' כמו מסיבת פסולת המאכל, משא\"כ בבחי' עינא פקיחא וכמ\"ש במ\"א וד\"ל.\n<b>והנה</b> בזמן בהמ\"ק יש עוד טעם אחר שלא הי' אז בחי' שינה כלל למעלה מלבד הטעם הנ\"ל מפני בירורי נוגה שע\"י הקרבנות. דהנה בקרבנות כתיב לחמי<sup data-n=\"1833\">107</sup> לאשי ריח ניחוחי כו', דמשמע שיש בהן ב' דברי', הא' בחי' הבירורי' דנוגה כמשל הלחם שמתברר ממנו הפסולת כו' כנ\"ל, ועוד יש בקרבנות שהנברר מהן ע\"ג המזבח עולה למעלה לריח ניחוח, וענין הריח שרשו בבחי'<sup data-n=\"1834\">108</sup> חוטמא דע\"י כמ\"ש ותהילתי <sup data-n=\"1835\">109</sup> אחטם לך וכמאמר לבעל<sup data-n=\"1836\">110</sup> החטם אני מתפלל כו'. כי הנה כתיב כל<sup data-n=\"1837\">111</sup> אשר נשמת רוח חיים באפיו וכתיב ויפח<sup data-n=\"1838\">112</sup> באפיו נשמת חיים, דמשמע שעיקר מהות הנשמה הוא באף וחוטם דוקא, וכמארז\"ל<sup data-n=\"1839\">113</sup> במס' שבת בענין מפקחין עליו את הגל עד החוטם דוקא ולא עד הלב בלבד, כי גם שיצא רוח החיים מן הלב יוכל להיות שעוד נשמתו בו בחוטם כו'. וגם בעדות אשה עגונה אמרו שאין<sup data-n=\"1840\">114</sup> מעידין אלא על פרצוף פנים עם החוטם, כי<sup data-n=\"1841\">115</sup> החוטם הוא עיקר הפרצוף פנים דאדם מפני שבו עיקר נשמת רוח",[["1828","102","<b>וכמ\"ש בזוהר קוב\"ה בגלותא אסתלק לעילא לעילא</b>: זח\"ג כ, ב. וראה ג\"כ זח\"א רי, א."],["1829","103","<b>הנה לא ינום ולא יישן שומר ישראל</b>: תהלים קכא, ד."],["1830","104","<b>וכמ\"ש במשנה יוחנן כה\"ג ביטל את המעוררי'</b>: סוטה מז, א."],["1831","105","<b>למנוע</b>: בכת\"י ב: ליגע."],["1832","106","<b>עינא פקיחא דלא נאים</b>: זח\"ג קכט, ב. וראה תו\"א מג\"א קיז, א. תו\"ח וירא קב, א. קו, ג. קיח, א."],["1833","107","<b>לחמי לאישי ריח ניחוחי</b>: במדבר כח, ב. ובהבא להלן ראה ג\"כ עט\"ר שער יוהכ\"פ בסופו. שערי אורה ד\"ה בכ\"ה בכסלו פי\"ג ופכ\"ה. סה\"מ תקס\"ב ע' סד. ובכ\"מ."],["1834","108","<b>בבחי' חוטמא דע\"י</b>: זח\"ג קל, ב. ובכ\"מ."],["1835","109","<b>ותהלתי אחטם לך</b>: ישעי' מח, ט."],["1836","110","<b>לבעל החוטם אני מתפלל</b>: זח\"ג שם."],["1837","111","<b>כל אשר נשמת רוח חיים באפיו</b>: בראשית ז, כב. וראה ישעי' ב, כב."],["1838","112","<b>ויפח באפיו נשמת חיים</b>: בראשית ב, ו."],["1839","113","<b>וכמארז\"ל במס' שבת בענין מפקחין עליו את הגל</b>: ראה יומא פג, א. פה, א."],["1840","114","<b>שאין מעידין אלא על פרצוף פנים עם החוטם</b>: יבמות קכ, א."],["1841","115","<b>כי החוטם הוא עיקר הפרצוף פנים דאדם</b>: ראה זח\"ג קל, א. קלז, ב. זח\"ב קכב, ב. ז\"ח יתרו לד, ב. ובכ\"מ."]]],[2101000289,"החיים כמ\"ש ויפח באפיו נשמת חיים, ומן האף נמשך הרוח החיים דרך המוח ללב כו', וע\"כ אמר לבעל החוטם אני כו'. והענין הוא לפי שיש באדם ה' מדרגות נרנח\"י ומשכן הנשמה בכלי המוח והרוח בלב והנפש בכבד כידוע דמוחא ולבא וכבדא הן ג' כלים לג' אורות דנר\"נ. אך בחי' חי' ויחידה אין להם בחי' כלים להכיל אורם רק הן שוכני' בבחי' מקיף והעלם. וביאור הדבר הנה מ\"ש ויפח באפיו נשמת חיים דוקא ולא אמר נשמה סתם, הכונה על בחי' חי' וכמ\"ש<sup data-n=\"1842\">116</sup> בזהר ע\"פ נפש החי' כו' והוא בחי' מקיף דחכ' שלמעלה מהגבלת אור בכלי. וז\"ש במשיח והריחו<sup data-n=\"1843\">117</sup> ביראת ה' כו', וארז\"ל דמוריח ודאין. פי' שלא מהגבלת אור החכ' בכלי המוח ידון דינים ומשפטים שזהו נק' למראה עיניו כו', אלא מוריח מבחי' ריח החוטם ששם משכן בחי' חי' שנק' נשמת חיים ולמעלה הוא בחי' חוטמא דע\"י ששם שורה בחי' מקיף דאור אבא דטמיר ונעלם כו' וד\"ל (ולזה<sup data-n=\"1844\">118</sup> רמז על ר\"ג לבעל החוטם להיותו גדול הדור בחכ' ונק' ג\"כ פני הדור, כי עיקר הפרצוף פנים הוא בחי' המוחין שבראש שמאירים בפני' כמ\"ש חכמת<sup data-n=\"1845\">119</sup> אדם תאיר פניו, ומקור המוחין הנעלם שורה בחוטם, וזשרז\"ל דאין מעידין על פרצוף פנים אלא עם החוטם דוקא וד\"ל).\n<b>והנה</b> הריח שמריח בחוטם הרי הוא בחי' העלאה למעלה מן בחי' נשמת רוח חיים שבחוטם, כי הנשימה<sup data-n=\"1846\">120</sup> שבחוט' יש בה בחי' רצוא ושוב כנשימה שבפה וכדפיקא דלבא, והנשימה שבחוטם שעולה למעלה הוא לבחי'<sup data-n=\"1847\">121</sup> חיי דחיין כמ\"ש בזהר שהוא בחי' יחידה שלמעלה מבחי' חי' וע\"כ נק' חיי דחיין כו' ומשם ימשיך בנשימה השניה המשכה חדשה, כנראה באיש הישן שתמיד בכל רגע עולה נשימה מן החוטם למעלה וחוזר ושב למטה. אך הנה בשינה ההעלאה וההמשכה שבחוטם אינה מוספת אור וחיות חדש רק שתקיים קיום חיות הנשמה שבמוח ורוח שבלב שלא יסתלקו בלבד. אמנם ע\"י הריח שמריח בחוטם מגיע בחי' התעוררו' יתירה לבחי' יחידה שנק' חיי דחיין וימשיך תוס' אור וחיות חדש גם בבחי' חיה שבחוטם ובנשמה שבמוח כו'. שע\"י הריח שבחוטם יתעורר גם מן השינה שכבר נסתלקו הארת המוחין כו'. משא\"כ ע\"י דבר אחר זולת הריח לא יקיץ מן השינה ולא יעורר כלל בבחי' יחידה התעוררו' חדשה, שהרי המאכל שיאכל אדם הגם שיאכל כל מיני מעדנים שיערבו לנפשו ותשבע נפשו ותתענג בהם מאד, וידוע שבודאי יתחזק עי\"ז כח השכל וכח התענוג להטיב חסדו לכל גם לרעי' כו', מ\"מ לא יתעורר בבחי' יחידה שבנפשו התעוררו' רוח יתירה כלל רק הכל על מעמדו הראשון כו', ומכ\"ש שלא יעוררו אותו מן השינה כו'. אבל ע\"י הריח הטוב והחזק שיריח בחוטמו יתעורר כח התענוג שבנפשו ביותר עד שנדמה לו כרוח ונפש חדשה ניתן בקרבו כו'. לפי ששרש המאכל אינו מגיע אלא בבחי' נשמה שבמוח",[["1842","116","<b>וכמ\"ש בזהר ע\"פ נפש החי'</b>: ראה זח\"א יג, א."],["1843","117","<b>והריחו ביראת ה'. . דמוריח ודאין</b>: ישעי' יא, ג. סנהדרין צג, ב."],["1844","118","<b>ולזה רמז על ר\"ג לבעל החוטם</b>: ראה תענית כט, א."],["1845","119","<b>חכמת אדם תאיר פניו</b>: קהלת ח, א."],["1846","120","<b>הנשימה שבחוט'</b>: בכת\"י ב: הנשמה שבמוח."],["1847","121","<b>לבחי' חיי דחיין כמ\"ש בזוהר</b>: זח\"ג קל, ב."]]],[2101000290,"שהוא רק בחי' הגבלת האור דחכ' בכלי וכמ\"ש<sup data-n=\"1848\">122</sup> בזהר ע\"פ אכלו ריעי' כו' או\"א כו'. אבל שרש הריח בחוטם הוא בבחי' חיה שעולה בבחי' יחידה להמשיך משם תוס' אור מרובה על עיקר ההארה שמאיר מכבר בחו\"ב כו'. וע\"כ ארז\"ל ע\"פ<sup data-n=\"1849\">123</sup> כל הנשמה תהלל י\"ה זה הריח דוקא שהנשמה נהני' ממנו ולא הגוף כו', דהיינו המשכת מקיפי' דחי' יחידה לחו\"ב כו'. ולזה הטעם יש הפרש בין הריח והמאכל גם בגשמיו', והוא מה שאנו רואים שהמאכל יפיג טעמו במעט זמן משא\"כ הריח שלא יפיג ריחו לעולם מפני ששרשו בבחי' מקיף דאבא ושרש המאכל דלחם הוא בבחי' החכמה המוגבלת בכלי המוח כו'. ולזה אמרו דחמרא<sup data-n=\"1850\">124</sup> וריחא דוקא פקחין ממקור החכמה כו' וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למשכיל למעלה בבחי' שרש ריח הקרבנות דכתיב בהו ריח ניחוח כו'. דהנה גוף הקרבן דבהמה וכבש שרשו מבחי' פני שור כו' שנפל בשבירה כידוע, ומתברר ע\"ג המזבח באש שלמעלה שאוכל הקרבן כמ\"ש לחמי כו', והוא בחי' בירורי' דנוגה כנ\"ל. אך מה שנק' עוד בשם ריח ניחוח היינו לאחר הבירור דנוגה שעולה בחי' הגבורו' שלהם שנבררו למעלה מעלה בשרש ומקור כל הגבורות דקדושה, והוא בחי' הריח דחוטמא דע\"י כמ\"ש וירח<sup data-n=\"1851\">125</sup> ה' את ריח הניחוח כו' (וכן בבגדי עשו החמודות כתיב וירח<sup data-n=\"1852\">126</sup> את ריח בגדיו ויברכהו כו' כמ\"ש במ\"א). והטעם הוא בהיות שבחי' הגבורות העליונות דריח שבחוטמא דע\"י הוא ממשיך מבחי' חיין דחיין שהוא בחי' מל' דא\"ס שמאיר בפנימי' ע\"י כי בחי' ע\"י הוא בחי' ממוצע בין המאציל לנאצלי' כידוע, וכמשל הנשימה גשמי' שבחוטם למטה ע\"י הריח שממשיך מבחי' יחידה שבאדם כנ\"ל באריכות. וזהו ריח<sup data-n=\"1853\">127</sup> ניחוח לשון נחות דרגא שחוזר וממשיך מחיי דחיין כו', והיינו מפני בחי' תוקף ותגבורת הכח של הריח דוקא הוא שמעורר התעוררו' יתירה בבחי' חיי דחיין כו' ונק' בחי' גבורה דע\"י כו'. והענין הזה יובן ע\"ד דוגמא למטה מדברי' גשמיי' החריפי' ביותר כמו סמים החריפי' ביותר כסממני הרפואות וכיוצא שמפני עוצם ותוקף כחם החזק מאד יקראו בשם סם, וע\"כ ביכולתם לרפאות כל חולי קשה ונק' סם חיים להחיות נפש האדם ברוח וחיות חדש וחזק מאד כו'. אך זהו דוקא כאשר נותנין בתערובו' ובמדה נכונה וראוי' לפי אופן קושי החולה המנגדה כידוע לרופאי', אבל כאשר אינן נותנין כפי הראוי לאדם הרי הן נקראו סם המות להמית את האדם. ונמצא יש בסממני' החריפי' ב' הפכי' לגמרי, א' שיהי' סם חיים להחיות רוח חיות מחדש, והב' להמית ולסלק החיות, והרי החיים והמיתה ב' הפכי' הן. אך הענין הוא משום דשרש הסמים החריפי' והחזקים נפלו בשבירה מבחי' תוקף ותגבורת כח הגבורו' העליונות",[["1848","122","<b>וכמ\"ש בזוהר ע\"פ אכלו ריעים כו' או\"א כו'</b>: ראה זח\"ג ד, א. ובכ\"מ."],["1849","123","<b>ע\"פ כל הנשמה תהלל י\"ה זה הריח דוקא</b>: ברכות מג, ב. וראה אוה\"ת ויקרא ע' רצו."],["1850","124","<b>דחמרא וריחא דוקא פקחין</b>: יומא עו, ב."],["1851","125","<b>וירח ה' את ריח הניחוח</b>: בראשית ח, כא. וראה סה\"מ תקס\"ב ע' כט."],["1852","126","<b>וירח את ריח בגדיו ויברכהו</b>: בראשית כז, כז. וראה אוה\"ת עה\"פ שם."],["1853","127","<b>ריח ניחוח לשון נחות דרגא</b>: ראה ג\"כ תו\"א כה, ד. לקו\"ת תצא לה, ג. שם דרושים לשמ\"ע צב, ד. סידור לג, ג. ובכ\"מ."]]],[2101000291,"שביכולתם להמשיך מבחי' חיי דחיין רוח חיים חדש תמיד כנ\"ל ונק' למעלה בחי' סם חיים, וכמ\"ש על התורה<sup data-n=\"1854\">128</sup> שנק' סם חיים למיימיני' בה להיות שרשה מבחי' גבורה דע\"י שבח\"ס כמ\"ש מימינו<sup data-n=\"1855\">129</sup> אש דת למו, אבל למשמאילים בה מתהפך להיות סמא דמותא היפך בחי' סם חיים כו', וכנ\"ל בסממני הרפואות. ונמצא מצד בחי' השבירה שנפל בבחי' גבורו' דנוגה נק' סם המות ומצד שרשם למעלה בבחי' הגבורות העליונות דע\"י נק' סם חיים (וע\"כ סמך ב' דברים הללו יחד הסולח<sup data-n=\"1856\">130</sup> לכל עוונייכי הרופא לכל תחלואייכי כו', כי סליחת עוונות הוא להמתיק גבורות קשות דנוגה שממיתים לנפש כמ\"ש רגליה<sup data-n=\"1857\">131</sup> יורדות מות ואין<sup data-n=\"1858\">132</sup> מיתוק הדין אלא בשרשו מבחי' הגבורות דע\"י שנק' סם חיים והיינו הרופא כו' וד\"ל). ובזה יובן שרש ענין ריח הקרבנות ובפרט בחי' ריח הקטורת שעולה על כל הקרבנות כמ\"ש ישימו<sup data-n=\"1859\">133</sup> קטורה באפיך כו' וכתיב שמן<sup data-n=\"1860\">134</sup> וקטורת ישמח לב, וכידוע בדרז\"ל דהקטורת<sup data-n=\"1861\">135</sup> מעשרת כו'. כי הנה מבואר בע\"ח בשרש י\"א סממני הקטורת הצרי והציפורן כו' שהן מקור חיות י\"א ארורי' דקליפה. ולכאורה יפלא דא\"כ מה מעלת הקטורת חשובה כ\"כ למעלה. אך הענין הוא די\"א סממני הקטורת כמו שהן נפלו למטה הן בחי' גבורות קשות להחיות לסט\"א וע\"ד הנ\"ל בסמים החריפי' שיכולים להמית כו', וכך בסט\"א כתיב רגליה יורדות מות, ובזהר נקראו אילנא דמותא כו'. אבל בהקטיר הי\"א סממני' הרי עולה בחי' הגבורו' הללו למעלה מעלה במקור שרשם בגבורות דקדושה עד רום המעלות בבחי' גבורו' דע\"י שנק' ריח דחוטמא כו', ששם הן נעשי' בחי' סם חיים להמשיך מבחי' חיי דחיין תוס' אור וחיות חדש כנ\"ל. וכמשל סממני הרפואות שביכולתם להחיות רוח חדש כו'. והיינו מפני עוצם תוקף כח הגבורות דסממני הקטורת למעלה מעלה, והוא הטעם לעוצם ירידתן ונפילתן למטה מטה כ\"כ להיות יניקות הקליפות מהן, כי<sup data-n=\"1862\">136</sup> כל הגבוה גבוה ביותר יותר ירד ויפול למטה מטה ביותר וכמשל הידוע ומבואר במ\"א וד\"ל.\n<b>ובכ\"ז</b> יובן שרש ענין עולת תמיד העשוי' בהר סיני לריח ניחוח כו'. פי' כי שרש ריח הקרבנות מגיע תמיד בבחי' חיי דחיין להמשיך משם אור חדש כנ\"ל, ע\"כ נק' עולת תמיד. משא\"כ עולת שבת בשבתו ועולת חודש בחדשו שאינו נק' עולת תמיד רק בשבת ור\"ח בלבד, לפי שעולת<sup data-n=\"1863\">137</sup> תמיד של שחר מכפר על עבירות בלילה ותמיד של בה\"ע מכפר על עבירות דיום, ונמצא יש סליחת העונות בתמידות יום ולילה ואין זה רק מפני בחי' ריח ניחוח התמידי' שבקרבנות שבכל יום",[["1854","128","<b>התורה שנק' סם חיים למיימינים בה</b>: ראה שבת סג, א. יומא עב, ב. זח\"א קצ, א."],["1855","129","<b>מימינו אש דת למו</b>: דברים לג, ב."],["1856","130","<b>הסולח לכל עוונייכי</b>: תהלים קג, ג."],["1857","131","<b>רגליה יורדות מות</b>: משלי ה, ה."],["1858","132","<b>ואין מיתוק הדין אלא בשרשו</b>: פע\"ח שער כונת השופר. וראה תניא פל\"א."],["1859","133","<b>ישימו קטורה באפיך</b>: דברים לג, י."],["1860","134","<b>שמן וקטורת ישמח לב</b>: משלי כז, ט. וראה בחיי ר\"פ תצוה. אוה\"ת נ\"ך ע' תרכח ואילך."],["1861","135","<b>דהקטורת מעשרת</b>: ראה בחיי שם."],["1862","136","<b>כי כל הגבוה גבוה ביותר</b>: ראה שערי אורה נח, א. סה, א. אוה\"ת שה\"ש ע' רס. ובכ\"מ."],["1863","137","<b>שעולת תמיד של שחר מכפר על עבירות של לילה</b>: במדב\"ר פכ\"א, כא. תנחומא פינחס יג. ובכ\"מ."]]],[2101000292,"שממתיקין כל גבורו' הקשות דנוגה בתמידו' וע\"כ נא' בתמיד דוקא את קרבני לחמי כו' ריח ניחוחי תשמרו להקריב כו' וד\"ל. ומ\"ש עולת תמיד העשוי' בהר סיני לריח ניחוח כו', הענין הוא לפי שבהר סיני ניתנה התומ\"צ ששרשן ג\"כ בכתר דא\"א שהוא בחי' גלגלתא דא\"א וח\"ס כו', וכנ\"ל בשרש התורה שנק' ריח לעורר מבחי' השינה כו'. אבל בחי' מקור התורה והמצות שבתרי\"ג ארחין הוא בחי' הריח שבעולת תמיד מפני שעולה ומגיע עד בחי' חיי דחיין שהוא בחי' מל' דא\"ס שמאיר בפנימי' דע\"י וא\"א כנ\"ל להמשיך משם מקור התורה והמצות שבכתר כו'. וז\"ש עולת תמיד העשוי' כבר בהר סיני להיות עולה למעלה במל' דא\"ס לריח ניחוח כדי שיומשך משם מקור התורה והמצות כו' וד\"ל וע\"כ ביטל יוחנן כה\"ג את המעוררי' שאו' עורה למה תישן ה' כו', כי בזמן בהמ\"ק מפני ריח הקטורת והקרבנות אין בחי' שינה לפני המקום כלל מטעם הנ\"ל וא\"צ למעוררי' כו'. משא\"כ בזמן הגלות אין<sup data-n=\"1864\">138</sup> להקב\"ה בעולמו אלא ד\"א של הלכה במקום היכל ק\"ק כו'. אבל התפלה עכשיו נק' ג\"כ בחי' עולת תמיד להיותה עולה תמיד מבירורי נוגה. כי<sup data-n=\"1865\">139</sup> התפלה תקנו במקום קרבן ממש כידוע, והוא<sup data-n=\"1866\">140</sup> למעלה בחי' עליי' שם ב\"ן דמל' מנוגה דבי\"ע כמ\"ש<sup data-n=\"1867\">141</sup> בזהר ע\"פ אלקי' אל דמי לך דקארי תדיר לנהורא עילאה כו', וכמ\"כ<sup data-n=\"1868\">142</sup> למען<sup data-n=\"1869\">143</sup> יזמרך כבוד ולא ידום, והוא הנק' עולת תמיד מפני שעולה תמיד כו' וד\"ל (ובחי' עולת תמיד דמל' מבי\"ע היא העשוי' בהר סיני לריח ניחוח כו' כי סוף מעשה עלה במחשבת המאציל תחלת שיהי' עולה לריח ניחוח כו'. והיינו משל<sup data-n=\"1870\">144</sup> דבת מלך שהריחה ציקי קדירה תאמר יש לה גנאי כו', ובת מלך הוא בחי' מל' דא\"ס וציקי קדירה הן גבורות דנוגה כו' והביאו לה עבדיה בחשאי היינו בש\"ע<sup data-n=\"1871\">145</sup> שנק' צלותא דלחש וכמ\"ש במ\"א וד\"ל).",[["1864","138","<b>אין להקב\"ה בעולמו אלא ד\"א של הלכה</b>: ברכות ח, א."],["1865","139","<b>כי התפלה תיקנו במקום קרבן</b>: ברכות כו, ב. ובכ\"מ."],["1866","140","<b>והוא למעלה בחי'</b>: בכת\"י ב: והוא מבחי'."],["1867","141","<b>כמ\"ש בזוהר ע\"פ אלקים אל דמי לך</b>: זח\"ב קמ, א. וראה הערת כ\"ק אדמו\"ר זי\"ע בציונים ומ\"מ לקונטרס ומעין יצא מבית ה' ע' 73."],["1868","142","<b>וכמ\"כ</b>: בכת\"י ב: וכמ\"ש."],["1869","143","<b>למען יזמרך כבוד ולא ידום</b>: תהלים ל, יג."],["1870","144","<b>משל דבת מלך שהריחה ציקי קדירה</b>: פסחים נו, א. וראה ת\"ז ת\"י (כה, א). תכ\"א (מז, א). תס\"ט (קה, א). תקוני ז\"ח קי, ג."],["1871","145","<b>בש\"ע שנק' צלותא בלחש</b>: ראה בהנסמן לעיל מת\"ז. וראה זח\"ב קלח, ב. ובכ\"מ."]]],[2101000293,"<h3>כתיב ולקחתי דגני</h3>\n<b>בעז\"ה</b>\n<b>כתיב</b><sup data-n=\"1872\">1</sup> ולקחתי<sup data-n=\"1873\">2</sup> דגני וכו' וכתיב ואספת דגנך כו', ושני כאן בזמן שישראל עושים רצונו של מקום אז נאמר ואספת דגנך ובזמן שאין ישראל עושין רצונו של מקום וכו'. ויש להבין דזה המאמר סותר מאמר אחר דרמי<sup data-n=\"1874\">3</sup> בגמ' כתיב ואספת דגנך וכתיב ועמדו<sup data-n=\"1875\">4</sup> זרים כו' ומשני כאן כשישראל עושין רצונו של מקום מלאכתן נעשית ע\"י אחרים כו', וא\"כ גם ואספת דגנך מיירי בשאין ישראל עושין רצונו של מקום כו', ויתורץ קושיא זו בהקדים להבין שרש ענין רצונו של מקום מהו. דהנה אנו אומרים ברוך<sup data-n=\"1876\">5</sup> המקום כו' וידוע דהקב\"ה נקרא מקום (וכ\"מ ממרז\"ל הוא<sup data-n=\"1877\">6</sup> מקומו של עולם כו') והטעם הוא לפי שהתהוות כל העולמות מאין ליש הוא מבחי' מל' דוקא כמ\"ש מלכותך<sup data-n=\"1878\">7</sup> מלכות כל עולמים, ובחי' מל' הוא בחי' ומדריגה אחרונה שבאורות דאצי' דהיינו בחי' התגלות אותיות בלבד וע\"כ נק' המל' שם עד\"מ קריאת שם האדם כידוע וז\"ש ברוך שם כבוד מלכותו כו', והוא הנק' בחי' ממכ\"ע דהיינו להוות מציאות עולם בגלוי ליש בעל ששה קצות מעלה ומטה מזרח ומערב צפון ודרום להיות כי כח הפועל בנפעל וכח הפועל האלקי כלול מששה קצות רוחני' בחי' מעלה ומטה ברוחניות כח האלקי היינו מה שאור<sup data-n=\"1879\">8</sup> א\"ס למעלה עד אין קץ ולמטה עד אין תכלית כו' ומזרח ומערב כו' היינו בחי' כח התפשטות הארה לד' סטרין לאורך ורוחב ימין ושמאל כו', ומששה קצות הרוחניי' האלה נמשך מאין ליש ששה קצות גשמיי' הנק' מקום גשמי, ומה שאנו אומרים ברוך המקום היינו שיומשך מבחי' ששה קצות דאצי' הנק' הקב\"ה שהוא מקור מקומו של עולם הנגלה מאין ליש מבחי' המל' כי אין הגילוי מאין ליש רק מבחי' המל' שהוא רק בחי' אותיות והיינו ה\"א אחרונה דשם הוי' הנק' עולם הדיבור אבל בחי' מדות דז\"א דאצי' הוא מקור הדבור כידוע, כמו מדת אור חסד דאצי' הוא אור עליון שאינו בא עדיין בבחי' התפשטות מאין ליש להיות מקור ושורש לנבראים, אלא נמשך מבחי' המל' שנק' דבור ונקרא עולם וכמ\"ש כי<sup data-n=\"1880\">9</sup> אמרתי עולם חסד יבנה פי' עולם הדיבור שנק' עלמא דאתגליא בחי'",[["1872","1","<b>כתיב ולקחתי דגני</b>: מאמר זה הוא מן ש\"פ נחמו תקס\"ט. (ונזכר ברשימת אדמו\"ר הצ\"צ של מאמרי ש\"פ נחמו שנדפס בסו\"ס פסקי דינים להצ\"צ, ועד\"ז באוה\"ת דברים כרך ו' ע' ב'תקעג: ”ר\"ח רמי, נחמו תקס\"ט\"). תוכן מהמאמר נמצא בקיצור בס' עבודת הלוי פ' עקב ח, ג, בכותרת: כי\"ק בעת ששמע מאדמו\"ר הזקן נ\"ע (שם הד\"ה: ואספת דגנך). וראה גם לקמן בהביאור בע' רסד וע' רפ."],["1873","2","<b>ולקחתי דגני. . ואספת דגנך. . ושני כאן בזמן</b>: הושע ב, יא. עקב יא, יד. ובגמ' ברכות לה, ב: ר' חנינא בר פפא רמי כתיב ולקחתי דגני בעתו וכתיב ואספת דגנך וגו' לא קשיא כאן בזמן שישראל עושין רצונו של מקום כאן בזמן שאין ישראל עושין רצונו של מקום."],["1874","3","<b>דרמי בגמ' כתיב ואספת דגנך</b>: בגמ' ברכות דל\"ה שם: ת\"ר ואספת דגנך כו' בזמן שישראל עושין רצונו של מקום מלאכתן נעשית ע\"י אחרים שנא' ועמדו זרים ורעו צאנכם וגו' ובזמן שאין ישראל עושין רצונו של מקום מלאכתן נעשית ע\"י עצמן שנא' ואספת דגנך כו'. וע\"ש בתוס'."],["1875","4","<b>ועמדו זרים</b>: ישעי' סא, ה."],["1876","5","<b>ברוך המקום</b>: בהגש\"פ. וראה מדות פ\"ה מ\"ד. ברכות מ, ב. ועוד."],["1877","6","<b>הוא מקומו של עולם</b>: ב\"ר פס\"ח, ט."],["1878","7","<b>מלכותך מלכות כל עולמים</b>: תהלים קמה, יג."],["1879","8","<b>שאור א\"ס למעלה עד אין קץ</b>: ראה ת\"ז תי\"ט (מ, ב). סוף תנ\"ז. זוהר חדש לד, ג."],["1880","9","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג."]]],[2101000294,"ממכ\"ע הנ\"ל נבנה מבחי' חסד דז\"א וכמ\"ש והוכן<sup data-n=\"1881\">10</sup> בחסד כסא וכידוע, וע\"ז אנו אומרים ברוך המקום להיות נמשך מבחי' מקום דז\"א במל' שנק' עולם, ונק' ג\"כ מלך וכמו חי העולמים מלך כו' לפי שעולם ומלך הכל ענין ומדריגה אחת כי היות התהוות העולם הוא בחי' מלך כמ\"ש מלכותך מלכות כ\"ע וכנ\"ל. ובזה יובן דברי<sup data-n=\"1882\">11</sup> התוס' בברכות גבי כל ברכה שאין בה שם ומל' (לפי ששם ומל' הכל א' וכנ\"ל) דה\"ה אם לא הזכיר העולם כאלו לא הזכיר שם ומל', לפי שעולם ומלך הכל א', כי חיות העולם הוא בחי' המל' בלבד כנ\"ל וד\"ל.\n<b>וענין</b> רצונו של מקום הנה הוא בחי' ההמשכה מז\"א למל' (ומבחי' מל' בבריאה וכמ\"ש בע\"ח<sup data-n=\"1883\">12</sup> דבחי' מל' דאצי' נעשית כתר לבריאה, וכן מבחי' מל' דא\"ס נעשה כתר לאצי' ונק' רצונו של מקום דאצי' כו'), ואין ההמשכה זאת אלא ע\"י בחי' ההעלאה בבחי' ביטול הרצון מלמטה למעלה הנק' ביטול היש לאין כמו וצבא<sup data-n=\"1884\">13</sup> השמים לך משתחווים וכיוצא בזה עד רום המעלות בכללות העולמות שנתהוו מאין ליש מבחי' המל', וגם בחי' המל' עצמה עולה מלמטה למעלה בבחי' ביטול כמ\"ש לך<sup data-n=\"1885\">14</sup> ה' הממלכה כו' שהרי אינה אלא בחי' אותיות ש\"מ<sup data-n=\"1886\">15</sup> בלבד, וכמו ביטול זיו השמש בגופו של מאור השמש כידוע<sup data-n=\"1887\">16</sup> בפי' כי שמש ומגן ה' אלקים דשם אלקים הוא נרתק לשמש שהוא שם הוי' וכהדין<sup data-n=\"1888\">17</sup> קמצא דלבושא מיני' ובי' כו' וד\"ל. וזהו פי' ישראל עושין רצונו של מקום שהן עושין וממשיכים בחי' רצון העליון להית מקור למציאות עולם בו\"ק מעלה ומטה כו', וזהו עיקר היחוד עליון בק\"ש בדלי\"ת דאחד כמארז\"ל תמליכהו<sup data-n=\"1889\">18</sup> בשמים וארץ וד' רוחות העולם כו' וד\"ל.\n<b>והנה</b> כאשר ישראל עושים רצונו של מקום אז נאמר ואספת דגנ\"ך כנ\"ל, והענין הוא דאסיפה זו לאסוף הדגן אינו אסיפה גשמיות אלא ר\"ל אסיפה וקיבוץ רוחני, לאסוף ולקבץ כל הניצוצות שנפלו בקליפות דהיינו כל חיות הדברים גשמיי' דדצ\"ח כמו במזון ומאכל ולבוש ששרשן מבחי' התוהו כידוע, והוא ע\"י קיבוץ ואסיפת כל מיני התקשרות רצונות זרות שבנפש הבהמית שנקשרה בתאות דברים הגשמיי' ובפרט ביגיע כפיו במו\"מ וכו', מפני בחי' ביטול הרצון מכל וכל רק לה' לבדו, שאז עולים גם כל הניצוצות דקדושה שיש בכל אשר לו במזון וכו' לה' אחד במס\"נ בתפילה, וע\"ז אמר ואספת דגנך וכו', בחי' אסיפה וקיבוץ ניצוצות הרבה מאד. וע\"ז רמזו רז\"ל דלא<sup data-n=\"1890\">19</sup> גלו ישראל לבין אוה\"ע אלא להוסיף להם גרים, וזה",[["1881","10","<b>והוכן בחסד כסא</b>: ישעי' טז, ה."],["1882","11","<b>דברי התוס' בברכות</b>: מ, ב."],["1883","12","<b>בע\"ח דבחי' מל' דאצי' נעשית כתר לבריאה</b>: ע\"ח שער העקודים (ש\"ו) פ\"ב."],["1884","13","<b>וצבא השמים לך משתחוים</b>: נחמי' ט, ו."],["1885","14","<b>לך ה' הממלכה</b>: דברי הימים א כט, יא."],["1886","15","<b>ש\"מ</b>: כ\"ה בכת\"י המעתיק: ואוצ\"ל: שם."],["1887","16","<b>כידוע בפי' כי שמש ומגן ה' אלקים</b>: תהלים פד, יב. תניא שעהיחוה\"א פ\"ז ואילך. יהל אור להצ\"צ תהלים עה\"פ. וראה בהמ\"מ בתו\"ח בראשית לב, ג. לקו\"ש חי\"ח ע' 310. וש\"נ."],["1888","17","<b>וכהדין קמצא דלבושא מיני' ובי'</b>: ראה ב\"ר פכ\"א, ה. [וראה במ\"מ בס' מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשכא]."],["1889","18","<b>תמליכהו בשמים וארץ</b>: ראה ברכות יג, ב. זח\"ג רכג, ב. ערב, א. ובכ\"מ."],["1890","19","<b>דלא גלו ישראל לבין אוה\"ע אלא להוסיף להם גרים</b>: פסחים פז, ב."]]],[2101000295,"פלא גדול לכאורה דאין<sup data-n=\"1891\">20</sup> אדם זורע קב אלא להוציא כמה כורים, ומאחר שנלמד זה מפסוק וזרעתי'<sup data-n=\"1892\">21</sup> לי בארץ א\"כ הגרים ירבו בישראל הרבה כמה פעמים מישראל, ולא ימצא גם חלק א' מריבוא גרים בישראל בכל דור, אלא הכוונה על בחי' העלאת הניצוצות שבעסק מו\"מ ובבני חיי ומזוני שתחת ממשלת כל שר משרי אוה\"ע כו' שניתוסף הרבה פעמים יותר ממספר נשמות ישראל כו' וד\"ל (והטעם שנק' בשם אסיפה הוא מפני שעולים כל הניצוצות דקדושה מטורי<sup data-n=\"1893\">22</sup> דפרודא הנק' רה\"ר דקליפה לבחי' רה\"י דקדושה כו' וכמ\"ש במ\"א וד\"ל).\n<b>אך</b> הנה יש להבין לפי זה המשך<sup data-n=\"1894\">23</sup> הפסוקים דוהי' אם שמוע כו' ונתתי מטר ארצכם יורה ומלקוש ואח\"כ אמר ואספת דגנ\"ך כו', ואם אסיפה זו רוחניות היא כנ\"ל מה שייכות יש לה עם מה שקדם ונתתי מטר ארצכם. אמנם הענין הוא דבחי' מטר זה הוא בחי' המשכה והשפעה עליונה מלמעלה למטה שנותן כח ועוז למטה שיוכלו כל הניצוצות שכבר ירדו למטה מטה לעלות למעלה מעלה (והיינו בחי' המשכת מ\"ד כדי שיהי' במקבל כח להעלות מ\"ן, כי כל בחי' העלאת ניצוצות מדצח\"מ דבחי' נוגה הנ\"ל הנק' בירורי נוגה מזה נעשה העלאות מ\"ן כידוע אך הכח הזה שיוכל להעלות ולברר כו' בא מלמעלה מהמשפיע למקבל והוא מבחי' ז\"א למל' ומבחי' מל' בבי\"ע, וזהו פי' עושין רצונו של מקום בבחי' המשכת מ\"ד אז נאמר ואספת דגנך לברר בהעלאת מ\"ן, ולא כפי' הא' דביטול היש לאין שנק' בירורי נוגה נק' עושים רצונו של מקום כו', ובמ\"א מבואר דהמשכת מ\"ד שאחר העלאת מ\"ן נק' עושין רצונו של מקום וזהו כפי' הא' אך בכאן שאומרים ונתתי מטר ארצכם ואח\"כ ואספת מיירי בבחי' מ\"ד שנותן כח להעלות מ\"ן), וזהו ונתתי מטר ארצכם כו' פי' עד\"מ המטר הגשמי שמתחלק לטיפין טיפין ומרוים את הארץ שתתן כחה להצמיח כל צמח תבואה ופירות כך נמשך בחי' מי החסדים העליונים מלמעלה בכדי שיוכל להיות צמיחה מהארץ העליונה כמ\"ש כי<sup data-n=\"1895\">24</sup> כארץ תוציא צמחה כן יצמיח ה' כו' ולמטה בכללות נשמות ישראל הנה נמשך אור חסד עליון בכאו\"א מישראל לפום שיעורא דילי' בהשגתו ועבודתו והוא בחי' אה\"ר שנמשכת מלמעלה בכל ניצוץ להיות בכחו להעלות באהבה ויראה כל הדברים הגשמיי' שבנפשו הבהמית כנ\"ל, ובחי' התחלקות אור האהבה והחסד לכאו\"א נק' מטר ארצכם כטיפי' של גשמי' שיורדים בארץ, כי כללות נש\"י נחלקים לס\"ר ניצוצות וכמ\"ש<sup data-n=\"1896\">25</sup> רז\"ל בברכת חכם הרזים ברואה אוכלסא כו' לפי שבאוכלסא של ס' ריבוא דעות והיינו ס' רבוא מיני השגות באלקות כי יש שכל מתפעל ויש שכל מתפעל כך כמ\"ש כי תוכן לבות ה' ותוכן<sup data-n=\"1897\">26</sup> רוחות ה'",[["1891","20","<b>דאין אדם זורע קב אלא אלא להוציא כמה כורים</b>: ראה פסחים שם. תו\"ח שמות מ, ג. בשלח קלג, ג. רלא, ב. משפטים רצו, א. ובכ\"מ."],["1892","21","<b>וזרעתי' לי בארץ</b>: הושע ב, כה."],["1893","22","<b>מטורי דפרודא</b>: ראה זח\"א כט, ב. קנח, א. זח\"ב רלד, א."],["1894","23","<b>המשך הפסוקים דוהי' אם שמוע</b>: עקב יא, יג ואילך."],["1895","24","<b>כי כארץ תוציא צמחה</b>: ישעי' סא, יא."],["1896","25","<b>וכמ\"ש רז\"ל בברכת חכם הרזים</b>: ברכות נח, א."],["1897","26","<b>תוכן לבות ה' ותוכן רוחות ה'</b>: משלי כא, ב. טז, ב."]]],[2101000296,"ולפי ששורש נשמות ישראל בבחי' ו\"ק דמלכות דאצי' וכאו\"א כלול מק' אלף עולה ס' רבוא וזהו ברכת חכם הרזים שנמשך ס' רבוא מיני שכליי' לבחי' חכמה עליונה שבמדות שבמל' דאצי' וכמ\"כ בחי' אור ומימי<sup data-n=\"1898\">27</sup> החסדים העליונים שנמשך לס\"ר נשמות מבחי' חסד עליון דז\"א מתחלק בכל חד לפי שורש נשמתו בבחי' המל' וע\"כ נק' מטר ארצכם כטיפין של גשמים שיורדין בארץ וד\"ל. (ופי' בעתו בעת רצון שיוכל להיות עי\"ז העלאת מ\"ן, והמטר הזה מתחלק לשני<sup data-n=\"1899\">28</sup> מדריגות יור\"ה ומלקו\"ש בשני זמנים כו' וד\"ל).\n<b>והנה</b> יש עוד בחי' אהבה רבה שלמעלה מבחי' מטר ארצכם הנ\"ל והוא בחי' אהבה רבה דבכל מאדך האמורה בפ' ראשונה דק\"ש שהיא באה מלמטה למעלה ע\"י התשובה עילאה מעומקא דלבא מחמת שצר לו מאד מעוצם רחוקו נפשו מה' אחד כמ\"ש בצר<sup data-n=\"1900\">29</sup> לך ומצאוך כו' ושבת עד ה' כו' וכן כתיב ויצעקו<sup data-n=\"1901\">30</sup> אל ה' בצר להם כו' דהיינו שיתמרמר בנפשו באמת מעומקא דלבא עד שימאס בחיי הבלו וירים קולו בבכי' מפני המרירות העצומה, כי צעקת זאת צעקה של בכי' היא כמ\"ש במרדכי ויזעק<sup data-n=\"1902\">31</sup> זעקה גדולה ומרה, והוא הנק' מי<sup data-n=\"1903\">32</sup> בוכי' כמ\"ש בזה\"ק<sup data-n=\"1904\">33</sup> מים תחתונים בוכי' אנן בעינן למהוי קדם מלכא כו'. והתחלת התשובה הזאת מעומקא דלבא בבכי' של מרירות הוא מר\"ח אלול כידוע דר\"ת<sup data-n=\"1905\">34</sup> אלול אני לדודי ודודי לי פי' אני לדודי ע\"י התשובה שישובו כנ\"י אל ה' מעומקא דלבא ואזי ממילא דודי לי שהקב\"ה מתעורר ברח\"ר למחול ולסלוח בר\"ה ויוה\"כ, וכל זמן החודש הזה אמר אני לדודי ודודי לי שכולו עת רצון מלמעלה לעורר י\"ג מדה\"ר ע\"י הבכי' בנפשו ובר\"ה ויו\"כ נמשכים ויורדים הי\"ג מדה\"ר מלמעלה למטה בלבד וד\"ל.\n<b>והנה</b> מט' באב מתחיל זמן שרש הבכי' למעלה בשורש כללות נ\"י שנק' רחל כמ\"ש קול<sup data-n=\"1906\">35</sup> ברמה נשמע כו' רחל מבכ\"ה על בניה כו' כי איננו כו', כי הנה לא כתיב רחל בוכה אלא מבכה לשון נפעל פועל יוצא שמשם נמשך התעוררות הבכי' בכללות נ\"י למטה, מפני שבט\"ב נחרב בהמ\"ק ונסתלק גילוי אור אלוקי דמל' דאצי' שנקרא שכינה וירדה למטה בגלות בע' שרים, ובחי' גילוי אורות עליונים דז\"א במל' נסתלק גם הוא למעלה מעלה וכמ\"ש בזוה\"ק<sup data-n=\"1907\">36</sup> קוב\"ה בגלותא אסתלק לעילא לעילא",[["1898","27","<b>ומימי</b>: תיבה זו אינה ברורה בהכת\"י."],["1899","28","<b>לשני מדריגות יורה ומלקוש</b>: ראה תענית ה, א. לקו\"ת במדבר ז, ב. אמרי בינה שער הק\"ש פנ\"ח."],["1900","29","<b>בצר לך ומצאוך</b>: ואתחנן ד, ל."],["1901","30","<b>ויצעקו אל ה' בצר להם</b>: תהלים קז, ו. כח."],["1902","31","<b>ויזעק זעקה גדולה ומרה</b>: אסתר ד, א."],["1903","32","<b>מי בוכי'</b>: ראה ס' דרשות התורה לר' שם טוב ר\"פ ויקרא. ס' חסד לאברהם מעין ב' נהר ג'. לקו\"ת במדבר ג, ב. דרושים לר\"ה נה, ד."],["1904","33","<b>בזה\"ק מים תחתונים בוכי'</b>: תקו\"ז ת\"ה (יט, ב)."],["1905","34","<b>דר\"ת אלול אני לדודי ודודי לי</b>: שה\"ש ו, ג. פע\"ח שער ר\"ה פ\"א. ראשית חכמה שער התשובה פ\"ד (ד\"ה עוד יש). ב\"ח לטור או\"ח סתקפ\"א. ועוד."],["1906","35","<b>קול ברמה נשמע</b>: ירמי' לא, יד."],["1907","36","<b>בזוה\"ק קוב\"ה בגלותא אסתלק לעילא לעילא</b>: ראה זח\"א רי, א. זח\"ב נה, ב. זח\"ג כ, ב. עה, א. וראה תו\"ח בראשית צה, א, ובמ\"מ שם."]]],[2101000297,"כו' וז\"ש כי איננו שעצמות אור א\"ס שבאצי' אסתלק לעילא ואינו בא לידי גלוי בבחי' מל', וגם בחי' מל' ירדה למטה בסתר המדריגות וע\"כ אמר רחל מבכ\"ה לעורר בכי' בכנ\"י ובנשמות ישראל שנסתלק מהם אור גלוי שכינה, כי בגלות נאמר אותותינו<sup data-n=\"1908\">37</sup> לא ראינו כו' (ונמצא הבכי' הזאת על ב' דברים הא' על העדר האור באצי' והב' על העדר האור בבי\"ע). ובאמת יוכל אדם לדון ק\"ו גדול ממה שמצינו בדברי<sup data-n=\"1909\">38</sup> רז\"ל ע\"פ עוברי בעמק הבכא כו' שהרשעים בוכי' על צערם באש של גיהנם, והרי אמרו באחר מוטב<sup data-n=\"1910\">39</sup> לדייני' בגיהנם בשביל שיקבל עונג העליון בגלוי זיו השכינה בג\"ע וא\"כ בהעדר גלוי אור האלקי מכ\"ש וק\"ו שיש לבכות, ומכ\"ש דכ\"ש מהעדר גלוי אור עצמות א\"ס שבאצי' המרומם לאין קץ מכל ההשתלשלות, שכל ההשתלשלות באבי\"ע אינו נחשב גם בערך טפה בים אוקינוס לגבי עצמות המאציל כו', כי בחי' גלוי אור האלקי הנק' שכינה אינו רק בחי' זיו ואור בלבד כידוע, וכאשר יתבונן האדם בעוצם רחוקו מה' אחד הרבה יש לו לבכות יותר מן יראת העונש בגיהנם מאחר שיסורי גיהנם נסבלי' בשביל התענוג האלקי הזה כו' (ומה<sup data-n=\"1911\">40</sup> שבכה ריב\"ז כשאינו יודע באיזה דרך מוליכים אותו לא מפני הצער של גיהנם אלא מפני ריחוקו מגלוי שכינה כו').\n<b>וענין</b> גלות השכינה בע' שרי' ידוע ע\"פ כרחל<sup data-n=\"1912\">41</sup> לפני גוזזיה נאלמ\"ה שהוא בחי' מל' שנק' רחל עקרת הבית שנמשכה בע' שרים שמקבלים מבחי' השערות דנוק'. אך לכאורה אין זה מובן דהלא גם בלתי גלות יש יניקה תמידית לע' שרים מבחי' השערות דנוק' ולמה אמר כרחל לפני גוזזיה נאלמה בזמן הגלות הלא גם בזמן בהמ\"ק הי' לאוה\"ע יניקה מבחי' השערות כמו שיש להם בזמן הגלות. אך הענין הוא דבבחי' השערות יש ב' מדריגות, הא' בחי' הפנימית והן עיקרי השערות שיונקי' מנקבי העור ממש והן הגומות שבעור שנמשך חיות פנימית לשם, והב' חיצונית השערות הנבדלים מן הגוף רק שחלל השערה יש בה קצת יניקה כל שהו ועובר ודוחק לחוץ מן השערה. כמו הזיעה שמתמלאת פנימיותה מחיות פסולת הדם שבגוף בגומות ונקבים שבעור ושם נאחזים עיקרי השערות, אמנם אותה הזיעה שעוברת בחלל השערה ונסחט לחוץ זהו חיצונית הזיעה והוא הנק' חיצונית השערה. וכן בכל יניקה וחיות שנמשך דרך השערות כמו בשערות<sup data-n=\"1913\">42</sup> שבראש ממותרי המוחין כידוע ומבואר במ\"א יש הפרש וחילוק שני מדריגות הללו פנימית וחיצונית. והנה בזמן הגלות מקבלים הע' שרים יניקה פנימית יותר, והיינו מבחי' נקבי העור דנוק' ששם עיקרי השערות (הגם שהוא בחי' פסולת האור הפנימי מ\"מ בפסולת עצמו יש פנימיות וחיצונית).",[["1908","37","<b>אותותינו לא ראינו</b>: תהלים עד, ט."],["1909","38","<b>בדברי רז\"ל ע\"פ עוברי בעמק הבכא</b>: תהלים פד, ז. עירובין יט, א."],["1910","39","<b>מוטב לדייני' בגיהנם</b>: חגיגה טו, ב."],["1911","40","<b>ומה שבכה ריב\"ז כשאינו יודע באיזה דרך</b>: ברכות כח, ב."],["1912","41","<b>כרחל לפני גוזזי' נאלמה</b>: ישעי' נג, ז. וראה גם לקו\"ת נצבים מח, ב. ובכ\"מ."],["1913","42","<b>בשערות שבראש ממותרי המוחין כידוע ומבואר במ\"א</b>: ראה לקו\"ת בהעלותך לא, א. שלח מה, א. תצא לו, ג. לז, ב. ובכ\"מ."]]],[2101000298,"<b>וזהו</b> כרחל לפני גוזזיה נאלמה כמשל הגוזז את השה שמפריד השערות לגמרי ונעשי' מובדלים כי גזז עיקר השערה ממקור חוצבה יניקתה בפנימיות נקבי העור, והיינו מה שאנו רואים שבגלות הע' שרים הם יותר יש ונפרד כמ\"ש אם<sup data-n=\"1914\">43</sup> תגביה כנשר, וכן שר של מצרים אמר לי יאורי כו' עד שאומרים ידינו רמה ולא ה' פעל כל זאת, הגם שכל יניקתם מבחי' השערות אינו אלא בחי' המותרות הנופלות מפנימיות האור האלקי שבאורות וכלים דמל' ולא נמשל רק לזיעה שיוצאת בנקבי העור כמו מזיעתן<sup data-n=\"1915\">44</sup> של חיות נהר דינור יוצא כו' וכמ\"ש במ\"א, מ\"מ בבחי' המותרות המה מקבלים מבחי' הפנימיות שבו ונעשים נבדלים בפ\"ע בפירוד גמור כמשל הגוזז, וע\"כ אמרו כרחל לפני גוזזיה כו' כמו שאחר הגזיזה אין לשערות חיבור וביטול לגבי השה כן אין להם אח\"כ ביטול לקדושה אלא אומרים ידינו רמה כו', משא\"כ בזמן בהמ\"ק הגם שקבלו הע' שרים יניקה מהקדושה האלקי אבל לא קיבלו רק מבחי' חיצונית השערות בנוק' שנק' רח\"ל היוצא לחוץ כמשל השערות המחוברות בגוף השה שבטלים ונגררים אחר הגוף השה ולא נמשך יניקה להם רק מקצה השערות התלוין ויורדין למטה, וגם זאת הי' בבחי' הביטול תמיד מאחר שבחי' עיקרי השערות מחוברים בנקבי העור (שהוא כמו חלל שבין אות לאות כמ\"ש במ\"א). ונמצא בעצם השפע גשמי' כסף וזהב ותענוגי' גשמי' הכל נמשך להם בזמן הגלות כמו בזמן בהמ\"ק, רק בבחי' הפירוד שלהם יש הפרש מפני שמקבלים בגלות בבחי' הפנימית יותר, ולכך אמר נאלמ\"ה בחי' אלם מאלקים כענין שאמרו גוים<sup data-n=\"1916\">45</sup> מרקדין בהיכלו והוא שותק אין<sup data-n=\"1917\">46</sup> כמוך באלמים כו', וכך ענין השכינה בגלות בע' שרים הוא בחי' אלם כמו הישן שהזבובים עוברים על פני עורו ואינו מרגיש אבל בהקיץ מרגיש כמ\"ש ויקץ<sup data-n=\"1918\">47</sup> כישן ה', אבל בזמן בהמ\"ק לא נאמר נאלמה לפי שהי' יחוד עליון דזו\"נ באצי' ובבריאה בבחי' סובב בממלא בבחי' גלוי המוחין דוקא ואז נאמר במל' למען<sup data-n=\"1919\">48</sup> יזמרך כבוד כו' היפך השתיקה כו' וד\"ל.\n<b>וזהו</b> קול ברמה נשמע רחל מבכה על בניה כו' פי' קול ברמה בבחי' הרוממות דכתר עליון שמשם נמשך מקור הי\"ג מדה\"ר כמ\"ש ויקרא<sup data-n=\"1920\">49</sup> ה' ה' אל רחום כו' שנמשך מבחי' הוי' שבעצמות המאציל להוי' שהוא שורש הנאצלים כי הכתר הוא בחי' ממוצע כי<sup data-n=\"1921\">50</sup>דוע והוא כללות בחי' רצון העליון (כמ\"ש בציץ והי'<sup data-n=\"1922\">51</sup> על מצחו תמיד לרצון כו' וכמ\"ש במ\"א), ומפני שנעוץ תחלתן בסופן וסופן בתחלתן דהיינו קו האמצעי דמל' עד הכתר ע\"כ אמר שבכיית רחל דוקא נשמע קול בכייתה ברמה לעורר בחי' רחמים רבים העליונים שברוממות פנימיות הכתר שנק' קול ברמה, כי",[["1914","43","<b>אם תגביה. . לי יאורי. . ידינו רמה</b>: עובדי' א, ד. יחזקאל כט, ג. האזינו לב, כז."],["1915","44","<b>מזיעתן של חיות נהר דינור יוצא</b>: חגיגה יג, ב. וראה תו\"א מקץ לא, ב. לקו\"ת במדבר יא, ב. שלח מא, א. שה\"ש מב, ד. ובכ\"מ."],["1916","45","<b>גוים מרקדין בהיכלו</b>: יומא סט, ב."],["1917","46","<b>אין כמוך באלמים</b>: ראה גיטין נו, ב. וראה ס' מאמרי אדהאמ\"צ קונטרסים ע' תקעב, ובמ\"מ שם."],["1918","47","<b>ויקץ כישן ה'</b>: תהלים עח, סה."],["1919","48","<b>למען יזמרך כבוד</b>: שם ל, יג."],["1920","49","<b>ויקרא ה' ה'</b>: תשא לד, ו."],["1921","50","<b>כי הכתר הוא בחי' ממוצע כידוע</b>: ראה ע\"ח שער דרושי אבי\"ע (שמ\"ב) פ\"א."],["1922","51","<b>והי' על מצחו תמיד לרצון</b>: תשא כח, לח."]]],[2101000299,"מי בוכי' מעוררי' י\"ג מדה\"ר כמ\"ש למעלה בפי' אני לדודי ודודי כו', ולפי ערך בחי' הרוממות כך ערך התפשטות הרחמים הרבים כמו שאנו אומרים המלך המרומם לבדו כו' ע\"כ ברחמיך הרבים רחם עלינו, כי כל הגבוה גבוה יותר יותר יתפשטו רחמים רבים ממנו, וכמו מלך בו\"ד שרוממותו דוקא גורמת הרחמנות כי כולם שפלים נגדו כו' וכמ\"ש במ\"א וד\"ל. וזהו ענין אהבת בכל מאדך בפ' הא' שבאה ע\"י התשובה שמעוררת למעלה רח\"ר בלי גבול שהוא למעלה מבחי' אהבה וחסד דונתתי מטר ארצכם שבפרשה שני' כנ\"ל וד\"ל. וזהו ג\"כ פי' עושים רצונו של מקום להמשיך מבחי' רצון העליון מקור הי\"ג מדה\"ר שיתפשטו עד למטה מטה בבחי' מקום שבמל' שנק' סופא דכל דרגין כי נעוץ תחלתן בסופן, וע\"כ נק' המשכה זאת רצונו של מקום וד\"ל.\n<b>אמנם</b> יש הפרש בין בחי' י\"ג מדה\"ר כמו שהם עדיין בשרשם העצמי בבחי' הכתר שנק' רצון העליון, בין בחי' התפשטותם וירידתם למטה מטה. הגם דהא בהא תליא דמפני הרוממות דכתר כך ערך ירידתם למטה, מ\"מ בהתפשטותם וירידתם למטה משתנה מהות אור הרצון ונעשה בצירוף אותיות באופן אחר והוא אותיות דונוצ\"ר חסד כו' שהן אותיות רצון בשינוי הצירוף כי<sup data-n=\"1923\">52</sup> תיבת ונוצר אותיות צנור להוריד ירידות ההמשכה של רצון העליון למטה עד\"מ קילוח הצינור שממשיך המים למרחוק ולהלאה עד למטה מטה מאד, כך ונוצר חסד העליון לאלפים ורבבות מדריגות עד למטה מטה מאד, וכן יתפרש לאלפים לשון אאלפך<sup data-n=\"1924\">53</sup> חכמה, ותיבת לאלפים מורה ריבוי האלפים מפני ריבוי מיני המשכות הרצון מכת\"ר לחכמ\"ה להיות נק' חכי\"ם ומבין כמ\"ש והחכמה<sup data-n=\"1925\">54</sup> מאין כו' כי החכמה נק' מעיין וכמו מעיין הנובע שיש כמה מעינות נובעים וכולם נובעים ממקור מוצא מים אחד כו', וז\"ש נוצר צינו\"ר השפע מכתר נחלק לכמה מדריגות הנק' אלפים דחכמה כדי להתפשט למטה כי כל שפע אינו יורד למטה רק באמצעית החכמה דוקא כמ\"ש כולם<sup data-n=\"1926\">55</sup> בחכמה עשית (ושם מ\"ה דחכמה הוא במלוי אלפי\"ן כי האל\"ף הוא בחכמה והבי\"ת בבינה כמ\"ש<sup data-n=\"1927\">56</sup> הני דרדקי אל\"ף בי\"ת אלף בינה וכמ\"ש<sup data-n=\"1928\">57</sup> בציור האלף במ\"א וד\"ל).\n<b>ובכל</b> הנ\"ל יובן ג\"כ ענין אחד שיש להבין בשורש פרשיות דק\"ש דהנה בפ' השני' אמר תחלה וקשרתם<sup data-n=\"1929\">58</sup> שהוא כללות כל המצות כי הוקשה<sup data-n=\"1930\">59</sup> כל התורה כולה לתפילין כידוע ובפ' הראשונה אמר תחלה ושננתם כו'. והענין הוא כנ\"ל דע\"י",[["1923","52","<b>כי תיבת ונוצר אותיות צנור</b>: ראה בכ\"ז תו\"א יתרו סט, ב. ובמ\"מ שם."],["1924","53","<b>אאלפך חכמה</b>: איוב לג, לג."],["1925","54","<b>והחכמה מאין</b>: שם כח, יב."],["1926","55","<b>כולם בחכמה עשית</b>: תהלים קד, כד."],["1927","56","<b>כמ\"ש הני דרדקי</b>: שבת קד, ב."],["1928","57","<b>וכמ\"ש בציור האלף במ\"א</b>: ראה סה\"מ תקס\"ח ח\"א ע' שיג. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' רכד, ובהמ\"מ שם."],["1929","58","<b>וקשרתם. . ושננתם</b>: עקב יא, יח. ואתחנן ו, ז."],["1930","59","<b>הוקשה כל התורה כולה לתפילין</b>: קידושין לה, א."]]],[2101000300,"הבכי' והתשובה מעוררים יג\"מ הרחמים שנק' רח\"ר והוא בחי' רצון העליון בכלל, והיינו בפ' השני' אחר שאמר ועצר<sup data-n=\"1931\">60</sup> את השמים כו' ואבדתם כו' וכתיב בצר לך ומצאוך כו' ובקשתם משם את ה' כו' בבחי' תשובה ואז ימשיכו רצון העליון שבמצות והוא מ\"ש וקשרתם כו' והוקשה כל התורה לתפילין כמו התפילין שנכתבו ע\"ג הקלף הגשמי והרי מלובש בקלף דפ' שמע כללות כל התורה דהיינו בחי' א' הפשוט וכך הוא כל התלבשות רצון העליון במעשה המצות המלובשים בגשמיות דדצ\"ח כו'.\n<b>והנה</b> כל המצות נכללים במצות הצדקה וכמ\"ש וצדקה<sup data-n=\"1932\">61</sup> תהי' לנו כי נשמור לעשות את כל המצוה כו', והטעם כי הצדקה למטה הוא להחיות רוח שפלים מן המשפיע אל המקבל וכך למעלה נמשך ונשפע מעצמות המאציל לנאצלים ונבראים כו', וז\"ש שם<sup data-n=\"1933\">62</sup> יתנו צדקות ה' צדקות פרזונו בישראל פי' פרזונו מלשון הערים הפרזים וכמו פרזות תשב כו' שהוא עיר בלתי חומה שמפולשת מכל צד וכך בחי' גלוי הארת עצמות אור א\"ס בלי הגבלת האור בבחי' כלי וצמצום נק' פרזון והיינו בחי' גלוי סובב הכללי שלמעלה מכל ההשתלשלות דאבי\"ע, כי בחי' ממכ\"ע הוא בחי' הקו והחוט שנמשך מעצמות אור א\"ס בבחי' אור וכלי דוקא וכמשל התלבשות הנפש באברי הגוף כמו כח השכל בכלי המוח וכח הראי' בכלי העין וכיוצא שהאברים מגבילים האור והחיות כידוע אבל בחי' סובב הכללי הוא אשר אינו נתפס ומוגבל בבחי' כלי כלל כמ\"ש הן<sup data-n=\"1934\">63</sup> השמים ושמי השמים לא יכלכלוך אפי' להיות כלי לכלי כו', והוא מפני עוצם רוממות אור עצמות הא\"ס שנבדל בערך לגמרי מבחי' ההשתלשלות דאבי\"ע, וכמו שאינו נתפס ומוגבל בגשמיות דבי\"ע כך אינו נתפס ברוחניות דעולם האצי' כי קמי' ממש שווים רוחניות וגשמיות אצי' ועשי' כו' כמ\"ש כחשכה<sup data-n=\"1935\">64</sup> כאורה כו' ומעלה ומטה שוים, וע\"כ נק' בשם פרזון כמ\"ש חדלו<sup data-n=\"1936\">65</sup> פרזון בישראל כלומר שלא נגלה עליהם מבחי' סובב הכללי שנק' פרזון, ואמנם ע\"י מעשה הצדקה שכוללת כל המצות כתיב שם יתנו צדקות ה' צדקות פרזונו בישראל שנמשך בחי' פרזונו שהוא הארת סובב בממלא כו', וע\"כ מצות הצדקה כוללת כל המצות לפי שכללות הכוונה במעשה המצות הוא ג\"כ רק בחי' המשכת הכתר שנק' רצון העליון והוא בחי' הארת סובב הכללי כידוע וד\"ל.\n<b>והנה</b> כתיב ביום<sup data-n=\"1937\">66</sup> ההוא יצאו מים חיים מירושלים חצים אל הים הקדמוני כו' פי' ע\"י התשובה ממטה למעלה נק' מים חיים שנובעין מלמטה למעלה ומעוררים בחי' סובב הכללי שנק' ים הקדמוני קדמונו של עולם הנאצל כו', והיינו",[["1931","60","<b>ועצר את השמים כו' ואבדתם. . בצר לך. . ובקשתם</b>: עקב יא, יז. ואתחנן ד, כט-ל."],["1932","61","<b>וצדקה תהי' לנו</b>: ואתחנן ו, כה."],["1933","62","<b>שם יתנו. . פרזות תשב</b>: שופטים ה, יא. זכרי' ב, ח."],["1934","63","<b>הן השמים ושמי השמים</b>: ע\"פ מלכים א ח, כז. דברי הימים ב ו, יח."],["1935","64","<b>כחשכה כאורה</b>: תהלים קלט, יב."],["1936","65","<b>חדלו פרזון בישראל</b>: שופטים שם ז."],["1937","66","<b>ביום ההוא יצאו מים חיים</b>: זכרי' יד, ח."]]],[2101000301,"ע\"י התורה ג\"כ שנק' מים חיים שהולכים למעלה במקור חוצבם שנק' ים הקדמוני וכמ\"ש בתורה כאשר<sup data-n=\"1938\">67</sup> יאמר משל הקדמוני כו' וכמ\"ש על תורה ואהי'<sup data-n=\"1939\">68</sup> אצלו אמון כו'. ולכך הקדים ת\"ת למצות בפ' הא' ובפ' הב' הקדים מצות לת\"ת באמרו וקשרתם ואח\"כ ולמדתם, לפי שלפעמים שהמצות הן בבחי' ההעלאה להיות שנעשים בדברים גשמי' ומתבררים ועולים מחשוכא לנהורא כו', ובפרט כד אתכפיא סט\"א בסור מרע בשס\"ה ל\"ת כו', והתורה היא בחי' המשכה כמ\"ש הליכות עולם לו, הליכות<sup data-n=\"1940\">69</sup> אלי כו' ומשפט<sup data-n=\"1941\">70</sup> תרגומו הלכתא וכן הלכות שבתורה כידוע, וע\"כ שינה הלשון במצות ת\"ת בפ' הא' אמר ושננתם לבנך שהוא בחי' ההעלאה כמ\"ש ביום ההוא יצאו מים חיים כו' ובפ' הב' אמר ולמדתם שהוא בחי' ההמשכה כתרגומו לימוד אולפנא אאלפך<sup data-n=\"1942\">71</sup> חכמה וכנ\"ל בפי' ונוצר חסד לאלפי' כו' וד\"ל.\n<b>וזהו</b> אני לדודי ודודי לי הרועה בשושנים, פי' אני הוא בחי' מל' דאצי' מקור כללות נ\"י כידוע, ובחי' העלאת מ\"ן מכנ\"י לגבי הקב\"ה שהוא בחי' אור א\"ס שבעולם האצי' שנק' דודי היינו ע\"י התשובה ומעש\"ט כנ\"ל, ואז נמשך בחי' המשכות רצון העליון מבחי' סובב הכללי בממלא ע\"י המצות וג\"כ נמשך י\"ג מדה\"ר למחול העונות כנ\"ל. וז\"ש ודודי לי והוא ר\"ת אלול, כי כל ר\"ח אלול ישראל עושים תשובה וגורמים בזה הכנה רבה להיות בחי' המשכת י\"ג מדה\"ר בר\"ה ויו\"כ להיות דודי לי כו' וד\"ל.\n<b>הרועה</b> בשושנים, הנה אמרו רז\"ל א\"ת<sup data-n=\"1943\">72</sup> שושנים אלא ששונים והן אותן ששונים הלכות כו', דהנה פי' רועה לשון<sup data-n=\"1944\">73</sup> פרנסה ומזון.",[["1938","67","<b>כאשר יאמר משל הקדמוני</b>: שמואל א כד, יד."],["1939","68","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["1940","69","<b>הליכות עולם לו, הליכות אלי</b>: חבקוק ג, ו. תהלים סח, כב."],["1941","70","<b>ומשפט תרגומו הלכתא</b>: ראה תרגום אונקלוס וישב מ, יג. וראה במ\"מ בסה\"מ מלוקט ח\"א ע' קס."],["1942","71","<b>אאלפך חכמה</b>: איוב לג, לג."],["1943","72","<b>א\"ת שושנים אלא ששונים</b>: שבת ל, ב. זהר שמות כ, ב."],["1944","73","<b>לשון פרנסה ומזון</b>: ע\"כ נרשם בכת\"י המעתיק (והמשך העמוד נשאר פנוי). ואפשר לא נשלם המשך זה בגוכי\"ק."]]],[2101000302,"<h3>להבין שרשי הדברים</h3>\n<b>ביאור לתורה הנ\"ל</b>\n<b>להבין</b><sup data-n=\"1945\">1</sup> שרשי הדברים הנ\"ל, הנה להבין שורש ענין רצונו של מקום הנ\"ל, יש להקדים תחלה להבין שני<sup data-n=\"1946\">2</sup> מאמרי רז\"ל דסתרי אהדדי לכאורה בפסוק זה דואספת דגנך כו', דפעם אמרו דהא דכתיב ולקחתי דגני כו' בשאין עושין רצונו של מקום והא דכתיב ואספת דגנך כו' כשעושים רצונו של מקום, ובמקום<sup data-n=\"1947\">3</sup> אחר בש\"ס רמי האי קרא דואספת דגנך אקרא דועמדו זרים כו' ומוקי קרא דואספת כשאין עושין רצונו של מקום, ואיך יתכן לומר בפי' ואספת דגנך כו' ב' דברים הפכים עושין רצונו ואין עושין רצונו כו'. אך הנה פי' רצונו של מקום על דרך הקבלה יתפרש בשני אופנים, הא' בבחי' מל' דאצילות שיורדת למטה ונעשית כתר לבי\"ע כדי לברר בירורי נוגה כמשי\"ת וע\"ז אמר ואספת דגנך כו' שזהו כשעושים רצונו של מקום, כי הרצון נק' כתר כידוע ובי\"ע נק' מקום כמשי\"ת, ורצונו של מקום הוא בחי' כתר דבריאה שנמשך מבחי' מל' דאצי', והאופן השני יתפרש למעלה בבחי' מלכות דא\"ס (או מל' דא\"ק) שנעשה כתר דאצי', וכן בכל עולם בפרט כי בחי'<sup data-n=\"1948\">4</sup> מל' שבעליון שנעשה כתר לתחתון נק' רצונו של מקום כו' (והענין המאמר השני הנ\"ל דקרא דואספת דגנך כשאין<sup data-n=\"1949\">5</sup> עושים רצונו של מקום היינו לעתיד לאחר תשלום כל הבירורים שאז נאמר ועמדו זרים כו' שלא יצטרכו לברר בעצמם ועכשיו שהמה צריכים לברר היינו כשאין עושים רצונו של מקום כו', ונמצא דמה שעושים רצונו של מקום עכשיו כדי לברר בירורים זהו הנק' אין עושים רצונו של מקום לעתיד לאחר הבירור, ולפי\"ז הרי מתורץ הסתירה הנ\"ל בשני מאמרים הנ\"ל ולא קשיין אהדדי כלל דשניהם אמת אלא שזה מדבר עכשיו בזמן הבירור וזה מדבר לעתיד לאחר הבירור וכמשי\"ת בעזה\"י וד\"ל).\n<b>והנה</b> יש להבין ביאור ענין רצונו של מקום שהוא בחי' מל' דאצי' שנעשה כתר לבריאה כנ\"ל, ותחלה יש להבין איך שייך לומר בחי' מקום בעולמות הרוחני' העליונים המופשטים מכל תואר הגשמה ומכ\"ש מגשם גדר מקום בעל ו\"ק גשמיי'. אך הענין הוא דמקום הגשמי שבעוה\"ז השפל יש לו שרש ומקור בעולם העליון הימנו הרוחני, וכמ\"ש<sup data-n=\"1950\">6</sup> במ\"א בביאור ענין הנה מקום אתי פי' שמקום הגשמי ו\"ק הגשמיי' הרי מקורם ושרשם ברוחניות ג\"כ הוא בבחי' מקום אלא שהוא בבחי' הרוחניות מאחר שהרוחניות מקור ושורש הגשמיות, וכמו אין<sup data-n=\"1951\">7</sup> לך עשב למטה שאין",[["1945","1","<b>להבין שרשי הדברים</b>: להלן ע' רפ נדפס ג\"כ נו\"א וקצר של ביאור זה. וראה בנסמן לעיל לתחילת המאמר."],["1946","2","<b>שני מאמרי רז\"ל דסתרי אהדדי. . דואספת דגנך. . ולקחתי דגני</b>: ברכות לה, ב. עקב יא, יד. ברכות לה, ב."],["1947","3","<b>ובמקום אחר בש\"ס</b>: הוא בגמ' ברכות שם בסמוך. ואולי יש כאן טעות מעתיק, וצ\"ל בש\"ס שם. וכיו\"ב."],["1948","4","<b>בחי' מל' שבעליון שנעשה כתר לתחתון</b>: ראה ע\"ח שער כסה\"כ (שמ\"ו) פ\"ב ופ\"ה."],["1949","5","<b>כשאין עושים</b>: כ\"ה בכת\"י המעתיק. ואוצ\"ל כשעושים."],["1950","6","<b>וכמ\"ש במ\"א בביאור ענין הנה מקום אתי</b>: תשא לג, כא. וראה לקו\"ת בחוקותי מח, ב. סה\"מ תקס\"ח ח\"א ע' ל. ס' מאמרי אדהאמ\"צ שמות ח\"א ע' קסז. ס' שע\"ת לאדהאמ\"צ קכה, ג. ועוד."],["1951","7","<b>אין לך עשב למטה</b>: ב\"ר פ\"י, ו. ועוד."]]],[2101000303,"לו מזל כו' כך אין כל גשם בכל חלקי דצח\"מ גשמיי' שאין לו שרש ברוחני במזלות הרוחניי' בפרטות, וכמו שיש בחי' דצח\"מ רוחניי' בפרט כך יש בחי' מקום רוחני בעל ו\"ק רוחניי' בכלל בכל עולם ועולם עד שנעשה מקור המקום הגשמי וע\"ז אנו אומרים לך<sup data-n=\"1952\">8</sup> הוי' הגדולה כו', וכמארז\"ל תמליכהו<sup data-n=\"1953\">9</sup> בשמים וארץ וד' רוחות העולם כלומר שיומשך ממקור כח האלקי מבחי' ו\"ק<sup data-n=\"1954\">10</sup> האלקים לו\"ק המוגבלים שבכל עולם ועולם עד עולם ומקום המוגבל הגשמי שלנו וזהו שאנו אומרים ברוך<sup data-n=\"1955\">11</sup> המקום היינו בחי' ו\"ק האלקי' שבע\"ס דעשי' נק' מקור מקומו של עולם העשי' בכלל, וזהו שאומרים ברוך<sup data-n=\"1956\">12</sup> כבוד ה' ממקומו דוקא, וכמאמרז\"ל הוא<sup data-n=\"1957\">13</sup> מקומו של עולם ואין העולם מקומו כו', ועד\"ז בחי' ו\"ק דיצירה נק' מקומו של עולם היצירה והוא הנק' בחי' סנד\"ל ועליו אמרו רז\"ל ג\"כ שיעור קומה במדה וכמבואר<sup data-n=\"1958\">14</sup> בפרקי היכלות דר\"י כה\"ג בשיעור קומה של יוצר בראשית הוא רל\"ו אלפים פרסאות בין דרועא ימינא לדרועא שמאלא כו' ויש בו בחי' עלי' וירידה מחול לשבת ומשבת לחול וכמ\"ש בזהר<sup data-n=\"1959\">15</sup> ע\"פ אנוש כחציר ימיו כו' ע\"ש, ומאחר שנאמר בו שיעור קומה ויש בו בחי' עלי' וירידה הרי הוא בגדר מקום אלא שהוא בבחי' רוחני' היותר עליון שבעולם היצירה, דהיינו שלפי ערך שיעור קומתו הרוחני' נמשך למטה שיעור מדת העולם היצירה, שהרי בודאי אין הפרסאות שבו כמו פרסאות הגשמי', אלא ר\"ל שכולל כמה אלפים בחי' פרסאות הרוחני' שבעולם היצירה בשיעור מדה שבכלי גופו כו', ועד\"ז בבחי' קומה דמט\"ט שהוא בחי' ו\"ק דבריאה העליונה הימנו, ובכללות לא נק' שיעור קומה של יוצר בראשית אלא בחי' מט\"ט<sup data-n=\"1960\">16</sup> דבריאה שנק' עבדו זקן ביתו המושל בכל אשר לו, ובדברי רז\"ל נזכר ג\"כ בפסוק דנער<sup data-n=\"1961\">17</sup> הייתי גם זקנתי שרו של עולם הבריאה אמרו, וידוע דנער הייתי היינו בחי' סנד\"ל דיצירה וכאשר עולה מבחי' הקטנות לבחי' הגדלות דבריאה נק' זקן ביתו והוא בחי' ו\"ק דבריאה הכולל יותר לכל ההשתלשלות העולמות בבחי' מקום בין בכלל כמו כללות כל עולם ועולם דבבי\"ע בין בפרט כמו בחי' היכלות בפרטיות שבכל עולם מג' עולמות בי\"ע. ומה שאמר שיעור קומה בפרקי היכלות על בחי' סנד\"ל דיצירה, היינו לפי שבימי החול כל הנהגות העולמות הוא ע\"י בחי' התלבשות ו\"ק דבריאה בו\"ק דיצירה לפי שבחי' מל' דאצי' מסתתרת בבריאה, ובחו\"ל מסתתר ג\"כ בחי' ו\"ק דיצירה בו\"ק דעשי' ומתנהג העולם ע\"י העלם האחרון דו\"ק דעשי' אבל בא\"י גם",[["1952","8","<b>לך הוי' הגדולה</b>: דברי הימים א כט, יא."],["1953","9","<b>תמליכהו בשמים וארץ</b>: ראה ברכות יג, ב. זח\"ג רכג, ב. ערב, א. ובכ\"מ."],["1954","10","<b>ו\"ק האלקים</b>: כ\"ה בכת\"י המעתיק."],["1955","11","<b>ברוך המקום</b>: נוסח הגש\"פ. וראה מס' מדות ספ\"ה."],["1956","12","<b>ברוך כבוד ה' ממקומו</b>: יחזקאל ג, יב."],["1957","13","<b>הוא מקומו של עולם</b>: ב\"ר פס\"ח, ט."],["1958","14","<b>וכמבואר בפרקי היכלות דר\"י כה\"ג</b>: ראה ע\"ח שמ\"ב פ\"ב בשם פרקי היכלות. ועד\"ז הוא בלקו\"ת ויקרא נד, ב. שלח נ, ג. ובפרדס שער עצמות וכלים פ\"א בשם ס' היכלות, וכ\"ה במק\"מ לזח\"ב נו, א. וראה בהנסמן ע\"ז בארוכה במילואים להמ\"מ בסו\"ס מאמרי אדהאמ\"צ במדבר ח\"א ע' דש."],["1959","15","<b>בזהר ע\"פ אנוש כחציר ימיו</b>: תהלים קג, טו. ראה זח\"ג רטז, ב. ריז, ב."],["1960","16","<b>מט\"ט דבריאה שנק' עבדו זקן ביתו</b>: חיי\"ש כד, ב. ראה זח\"ג ריז, א-ב. ביאוה\"ז וישב כג, ד ואילך."],["1961","17","<b>דנער הייתי גם זקנתי שרו של עולם הבריאה אמרו</b>: תהלים לז, כה. יבמות טז, ב ותוס' שם."]]],[2101000304,"בחול אין ההנהגה בהעלם ו\"ק דיצירה בו\"ק דעשי' אלא בו\"ק דיצירה בלתי התלבשות בעשי' רק דרך פרוכתא קלישתא כמ\"ש<sup data-n=\"1962\">18</sup> בזהר ע\"פ וזה שער השמים כו', ובשבת בבחי' ו\"ק דבריאה בלתי מלובש בו\"ק דיצירה וכמ\"ש<sup data-n=\"1963\">19</sup> בכוונת דבגדי שבת וכמ\"ש ותלבש<sup data-n=\"1964\">20</sup> אסתר מלכות שהוא אור הבריאה כמו שהוא כו' כמ\"ש במ\"א ביאור זה באריכות.\n<b>וכלל</b> ענין התלבשות הללו דו\"ק דבריאה ביצירה ויצירה בעשי' מבואר במ\"א עד\"מ התלבשות מדות שבלב במחשבה שנק' בריאה וממחשבה לדיבור ומדבור למעשה כו' ועיקר ההנהגה בחול הוא בדבור שהוא בחי' יצירה וע\"כ אמר בו\"ק דיצירה שהוא שיעור קומה כו', וע\"ז נאמר הנה<sup data-n=\"1965\">21</sup> אנכי שולח מלאך לפניך כו' אל תמר בו כי לא ישא לפשעכם כי שמי בקרבו כו' כי הוא בבחי' הקטנות לגבי בחי' מט\"ט דבריאה שנק' זקן ביתו וד\"ל (וענין ההעלם והתלבשות דבריאה ביצירה ויצירה בעשי' היינו העלם ממש כמו שהמחשבה נעלמת ממש בדיבור וכיוצא אמנם ענין ההארה בגלוי בלתי העלם עליון בתחתון הנה לכאורה אינו מובן זה במשל דמחשבה דו\"מ, דאם הכוונה שהמחשבה אינה מאירה כלל בדיבור הרי אין זה גלוי אור המחשבה שנק' בריאה וכן בדיבור למעשה כו', אלא הכונה שהמחשבה מאירה בגלוי בדבור ואין הדבור מעלימו ומסתירו כלל וכן הדבור במעשה כו', וכמו עד\"מ אור העובר דרך מעבר בעלמא בזכוכית בהירה מאד שאין הזכוכית מעלים ומחשיך הזיו כלל שזה נק' דרך<sup data-n=\"1966\">22</sup> מעבר ולא דרך מלבוש כלל וכלל וכמ\"ש במ\"א, וכך בהפרש בין חול לשבת היינו שבחי' הבריאה אינו מוסתר ונעלם ביצירה בשבת כי בחי' היצירה אינו מעלים אורו כלל וכן מיצירה לעשי' כהפרש שבין א\"י לחוץ לארץ כנ\"ל וד\"ל).\n<b>והנה</b> כתיב ותקם בעוד לילה ותתן טרף לביתה כו' פי' בחי' המל' מסתתרת מאד מאד למטה בירידות המדריגות בהסתר אחר הסתר והעלם אחר העלם עד שמתלבשת בע' שרים דנוגה לברר ולאהפכא מחשוכא לנהורא כו' מבחי' רפ\"ח ניצוצות דתוהו שנפלו שמה בשבירה כידוע, וז\"ש ותתן טרף רפ\"ח ע\"ה<sup data-n=\"1967\">23</sup> והוא בחי' שם ב\"ן המברר, בעוד לילה בהיותה בתכלית ההסתר והצמצום, וענין הבירור הזה",[["1962","18","<b>כמ\"ש בזהר ע\"פ וזה שער השמים כו'</b>: ראה גם זח\"ב קמא, א. וראה גם לקו\"ת מסעי פט, ב ואילך. סה\"מ הנחות הר\"פ ע' קי ואילך. תקס\"ב ח\"א ע' שנב. תקס\"ה ח\"א ע' שנד ואילך. תקס\"ו ע' סט. סידור עם דא\"ח קמט, א."],["1963","19","<b>וכמ\"ש בכוונת דבגדי שבת</b>: ראה שער הכוונות ענין קבלת שבת דרוש א'. פע\"ח שער השבת פ\"א."],["1964","20","<b>ותלבש אסתר מלכות</b>: אסתר ה, א. וראה גם סה\"מ תרס\"ב ע' רלא. סה\"מ אעת\"ר ע' רכח (ובהוצאה החדשה הוא בע' רמז). המשך תער\"ב ח\"ב ע' תתעב."],["1965","21","<b>הנה אנכי שולח</b>: משפטים כג, כ-כא."],["1966","22","<b>דרך מעבר ולא דרך מלבוש. . וכמ\"ש במ\"א</b>: ראה תניא קו\"א ד\"ה להבין מ\"ש בפע\"ח (קנח, א). לקו\"ת מסעי פט, ב-ג. אוה\"ת שמיני כרך ב ע' תסח ואילך. סה\"מ תרל\"ב ח\"א ע' קמח. סה\"מ תרצ\"ו ע' 113. וש\"נ."],["1967","23","<b>ותקם בעוד לילה. . טרף רפ\"ח ע\"ה</b>: משלי לא, טו. מק\"מ לזח\"ג ס, א. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ במדבר ח\"א ע' שג."]]],[2101000305,"היינו להבדיל ולהפריש חלק הטוב מחלק הרע שלא יהי' מעורבים יחד כי בחי' נוגה מעורב טו\"ר כמו פני שור פני נשר שבנוגה שבמרכבה דעשי' הנה מפעולת השפעתם למטה בהתהוות חלקי דצ\"ח אנו רואים שגם בעצם מהותם מעורב טו\"ר ברוחניות כי הנה החיות והבהמות והעופות שנתהוו מפני שור פני נשר כו' הרי נתהווה חיות ובהמות ועופות טהורים וחיות ובהמות ועופות טמאים, והטמא הוא בחי' רע גמור שנפל בשבירה מז' מדות הרעות דנוגה כמו עופות הדורסים המזיקין וחיות רעות הטורפין ומזיקין, וכיוצא בזה בחי' רע גמור שבאדם הפועל רע תמיד כו', או דברים האסורים לגמרי כגזל ועריות ושפיכות דמים כו', שכל אלה יצאו לכלל פירוד מאלקות ולא יוכלו להתברר ולעלות וליכלל בקדושה העליונה כמ\"ש טהור<sup data-n=\"1968\">24</sup> עיניים מראות ברע, לא יגורך רע כו', אך הבהמה והחי' הטהורה שרשה מבחי' פני שור כו' שהוא בחי' נוגה מעורב טו\"ר, כי הנה הבהמה הטהורה כשירה לקרבן ולמאכל אדם ויכולה לעלות וליכלל בקדושה האלקית כשמתפלל ומוסר נפשו באחד בכח המאכל של בשר בהמה ואדרבה ניתוסף עי\"ז אור השגה אלקית וכמ\"ש<sup data-n=\"1969\">25</sup> ר\"נ עד דלא אכילנא בשרא דתורא כו' וכן אמר חמרא<sup data-n=\"1970\">26</sup> וריחנא פקחין כו' לפי ששרשם מבחי' התוהו שלפני התיקון וכמ\"ש במ\"א. אך זהו דוקא כשאינו אוכל רק לשובע נפשו האלקית ולא למלאות תאוות גופו הבהמית, אבל כשאוכל למלאות תאוות נפשו הבהמית אזי יהי' להיפך שהמאכל מגשם גם את נפשו האלקית לבלתי יוכל לעלות רוחו ונשמתו לעבודת ה' כו', ולכך נק' אכילה גסה שהיא מגשמת הגוף כ\"כ עד שגם נפשו האלקית יחשך אורה, והטעם הוא לפי שהמאכל הוא מעורב טו\"ר ומתברר ויוצא ממנו הפסולת הרע לחוץ והחלק הטוב והמובחר עולה למוח ששם משכן נפש האלקית ומחזקה ובחי' הפסולת הגס מגשם לגוף וא\"א להיות שיאכל אדם גם לשובע נפשו ולא יפעול בגופו הגשמה כלל, רק בשבת בלבד דהגשמיות שבמאכל נברר ועולה גם הוא ונכלל בקדושה כמ\"ש<sup data-n=\"1971\">27</sup> בפע\"ח בכונות סעודת שבת (שהוא כמו לחם<sup data-n=\"1972\">28</sup> הפנים שכולו פנים בלתי פסולת כלל כמ\"ש במ\"א), וע\"כ מותר לאכול בשבת לתאבון ואינו מזיק גם לגוף, אמנם צדיק<sup data-n=\"1973\">29</sup> שאוכל לשובע נפשו מתגבר חלק הטוב שמחזק לאור הנשמה ומהפך את הגשמת הגוף להיות לעזר להוסיף כח בעבודת ה' וכמ\"ש ר\"נ עד דלא אכילנא כו'. ועכ\"פ הרי מובן מזה שיש במאכל טו\"ר ממש, ומוכרח שגם במקור חוצבו יש תערובות טו\"ר ברוחניות והוא בחי' נוגה שבמרכבה כידוע שנמשך מפני שור שורש נפש הבהמית כו', אך הן בהמות ועופות טהורים וד\"ל, וזהו ענין הבירור למעלה ע\"י שם ב\"ן לברר ולהעלות חלק הטוב מבחי' נוגה ולהגביר אורו גם על חלק הפסולת ולאהפכא חשוכא לנהורא כו' עד שלא ישאר רק חלק הרע הגס שאין לו בירור כענין צדיק אוכל לשובע נפשו הנ\"ל.",[["1968","24","<b>טהור עיניים. . לא יגורך רע</b>: חבקוק א, יג. תהלים ה, ה."],["1969","25","<b>וכמ\"ש ר\"נ עד דלא אכילנא בשרא דתורא</b>: ראה ב\"ק עב, א."],["1970","26","<b>חמרא וריחנא פקחין</b>: יומא עו, ב."],["1971","27","<b>כמ\"ש בפע\"ח בכונות סעודת שבת</b>: ראה פע\"ח שער השבת פי\"ד ואילך."],["1972","28","<b>לחם הפנים שכולו פנים. . כמ\"ש במ\"א</b>: מנחות צו, א. וראה לקו\"ת עקב יז, ב. סידור קז, ד. מאמרי אדהאמ\"צ במדבר ח\"ב ע' תקנ. ח\"ג ע' תתקלב. דברים ח\"ג ע' א'קיז."],["1973","29","<b>צדיק שאוכל לשובע נפשו</b>: משלי יג, כה."]]],[2101000306,"<b>וזהו</b> פי' ותקם בעוד לילה שהוא בחי' מל' שמסתתרת בתכלית ההסתר בע' שרים דנוגה לברר ולהעלות מהם הניצוצות הטוב שנפלו, ותתן טרף זה לנשמות ומלאכים עליונים שנק' נערותי' ואנשי ביתה, וח\"ק ומזון זה מעלה לנערותי' להוסיף כח ואור השגה אלקית כמו שע\"י המאכל יתחזק האדם בנפשו האלקית יותר מטעם הנ\"ל. וזהו פי' ואספת דגנך לברר בירורי נוגה כמו הדגן שמחמתו יש דעת גם לתינוק דעת לקרוא אבא כו', ותירושך ויצהרך הן יין ושמן שהן בעלמא דאתכסיא שנפלו ג\"כ בשבירת הכלים מרפ\"ח ניצוצות דתוהו כו' וד\"ל.\n<b>אך</b> הנה מהיכן יש כח לשם ב\"ן לברר ולהעלות כל בירורי נוגה כנ\"ל שהרי אמרו האיש<sup data-n=\"1974\">30</sup> דרכו לכבש ואין האשה דרכה לכבש פי' לכבש מלחמה אין דרכה של אשה בזה, ובחי' שם ב\"ן נק' אשה<sup data-n=\"1975\">31</sup> יראת ה' כידוע וכתיב אשת חיל מי ימצא כו', אלא צריכה לעזר בזה מכח בעלה שכח האיש לכבש ולברר בירורים, והוא שרש ענין מ\"ש קודם ואספת כו' ונתתי<sup data-n=\"1976\">32</sup> מטר ארצכם כו' שהוא בחי' המשכת מ\"ד דדכורא משם מ\"ה ליתן כח לשם ב\"ן להעלות מ\"ן מבירורי נוגה כנ\"ל, וזהו ונתתי מטר כו' כמו עד\"מ המטר שנמשך טיפין טיפין בהתחלקות ואמנם עי\"ז כתיב והרוה<sup data-n=\"1977\">33</sup> את הארץ והולידה והצמיחה שנותן כח בכח הצומח שבארץ שתוציא צמחה כו' וכן בחי' מ\"ד מתחלק טיפין טיפין ועי\"ז נותן כח להיות העלאת מ\"ן להוליד ולהצמיח כו' וכמו שנאמר אשה<sup data-n=\"1978\">34</sup> כי תזריע וילדה כו' אך אינה מעלה מ\"ן רק בסיבת כח המ\"ד שגורם לה שתזריע כו' וכמ\"ש במ\"א, ולמטה היינו המשכת האהבה רבה שבאה מלמעלה בכל חד לפום שיעורא דילי' וכמבואר שם ונמשל למים להיות יותר בבחי' קרירות ובהתחלקות דוקא בס' רבוא דעות כו', ואח\"כ כללות נ\"י מעלין מ\"ן במס\"נ שהוא בבחי' רשפי אש התשוקה וכמ\"ש ואל<sup data-n=\"1979\">35</sup> אישך תשוקתך והוא הנק' העלאת מ\"ן ונק' מי בוכי' כמ\"ש למעלה, וע\"ז נאמר רשפיה<sup data-n=\"1980\">36</sup> רשפי אש שלהבת י\"ה פי' שבחי' המשכת המ\"ד שנמשך אחר העלאת מ\"ן זה ברשפי אש התשוקה נק' שלהבת י\"ה שנמשך ג\"כ בבחי' תגבורת רשפי אש שלהבת ולא בבחי' קרירות כמטר המתחלק כו', והוא בחי' המשכת מ\"ד בבחי' גבורות שנק' גבורות אנשים שבא בכח גדול וברשפי אש גדול ולכך נק' שלהבת י\"ה דוקא, כי כל המשכת מ\"ד הוא מבחי' מוחין דאו\"א שבז\"א שהן אותיות י\"ה דשם הוי' דז\"א. אך המשכת מ\"ד החסדים הבאה בקרירות כמטר הוא רק כדי שיהי' בכח המקבל להעלות מ\"ן להיות מזרעת תחלה, אבל עיקר המשכת מ\"ד הוא לאחר העלאת מ\"ן שנמשך בבחי' גבורות רשפי אש שממנו עיקר התולדה להוליד ולד, וכידוע<sup data-n=\"1981\">37</sup> דכל טיפה שאינו יורה כחץ אינו מוליד כו', משא\"כ המשכת מ\"ד שלפני העלאת מ\"ן אינו מוליד כלום כו' וד\"ל.",[["1974","30","<b>האיש דרכו לכבש</b>: יבמות סה, ב."],["1975","31","<b>אשה יראת ה'. . אשת חיל מי ימצא</b>: משלי לא, ל. י."],["1976","32","<b>ונתתי מטר</b>: עקב יא, יד."],["1977","33","<b>והרוה את הארץ</b>: ע\"פ ישעי' נה, י. [וראה במ\"מ תו\"ח בראשית כא, ד]."],["1978","34","<b>אשה כי תזריע. . וכמ\"ש במ\"א</b>: תזריע יב, ב. לקו\"ת תזריע כ, א ואילך."],["1979","35","<b>ואל אישך תשוקתך</b>: בראשית ג, טז."],["1980","36","<b>רשפיה רשפי אש</b>: שה\"ש ח, ו."],["1981","37","<b>וכידוע דכל טיפה שאינו יורה כחץ</b>: חגיגה טו, א. נדה מג, א."]]],[2101000307,"<b>ובכל</b> זה מובן פי' עושין רצונו של מקום דהיינו בחי' הבירורים הנ\"ל שנעשה ע\"י שם ב\"ן שיורד בבי\"ע שזהו עיקר הרצון של בחי' מל' בהתלבשותה בבי\"ע ולכך נק' רצונו של מקום שבמל', וגם נק' רצונו של מקום מטעם שנמשך בחי' המשכת מ\"ד בשביל העלאת מ\"ן כנ\"ל ומכ\"ש בחי' המשכת מ\"ד שאחר העלאת מ\"ן כנ\"ל, וכ\"ז נכלל בפי' ואספת דגנך משום דמה שאמר ונתתי מטר בחי' מ\"ד הוא בשביל העלאת מ\"ן כנ\"ל וד\"ל. אך עדיין יש להבין למה נק' בשם רצונו של מקום שהוא בחי' הכתר שנק' רצון העליון כידוע. אך הענין הוא דבחי' הכתר של כל עולם הוא בחי' הרצון של כל עולם, כמו כתר דבריאה הוא בחי' הרצון להיות עולם הבריאה וכמ\"ש<sup data-n=\"1982\">38</sup> בזהר בכמה דוכתי' כד סליק ברעותא למברי' עלמא כו' וכן כתר דיצירה וכתר דעשי' מאחר שנאמר לכבודי<sup data-n=\"1983\">39</sup> בראתיו יצרתיו אף עשיתיו כו' וכמו\"כ בחי' כתר דאצי' היינו כשעלה ברצונו להאציל כו', ובכל עולם שהוא הנה עיקר הרצון הוא בשביל בחי' הבירורים שבאותו העולם מחשוכא לנהורא כו', כמו הרצון לבריאה הוא בשביל בירור דבינה דבריאה כי כאשר עלה הרצון לבריאה נבראו ע\"י בחי' אורות וכלים גם בחי' נוגה דבריאה ועיקר הרצון הי' כדי לברר בחי' נוגה דבריאה, וכן בכתר דיצירה לברר נוגה דיצירה וכן בכתר דעשי' כו', וזהו הנק' רצונו של מקום בכל עולם ועולם לפי מדריגתו, גם בעולם האצי' נק' רצונו של מקום דאצי' בחי' כתר דאצי', ועיקר הרצון שנק' כת\"ר הוא בשביל בירור שבנוגה דאצי', וסדר ההשתלשלות של הכתרים בכללות היינו שמבחי' מל' דא\"ס (או מל' דא\"ק) נעשה כתר לאצי' ומבחי' מל' דאצי' נעשה כתר דבריאה ומבחי' מל' דבריאה נעשה כתר דיצירה כו'.\n<b>אך</b> למה תלה עיקר שם הרצון על בחי' מקום שהוא בחי' ו\"ק מעלה ומטה כו', הענין הוא לפי שעיקר גלוי הארת הכתר בבינה שהוא בבחי' יש בהתפשטות אורך ורוחב שבו מתהווה גדר ו\"ק מזרח ומערב כו', עד\"מ השכל הבא בהשגה שמתפשט אז לימין ולשמאל שהוא לזכות ולחוב ויש בו אורך ורוחב גם גדר מעלה ומטה כו', משא\"כ קודם בואו לידי השגה והסברה עדיין רק שנברק ומאיר כברק בבחי' נקודה א' דחכמה שאין בו בחי' התפשטות כלל ודאי שאין בו גדר ו\"ק כלל כידוע<sup data-n=\"1984\">40</sup> בענין נקודה קו שטח, ואמנם בחי' נקודה דחכמה הוא בחי' ממוצע בין הכתר לבינה כידוע בעין ג\"ר כח\"ב שהוא כדמיון מעיין הנובע מן התהום שהמעיין ממוצע בין התהום לנהר דהיינו שבמעיין מתקצר ומתעלם עצם שפע התהום וממנו מתרחב אח\"כ בהמשך הנהר שנק' רחובות כמ\"ש<sup data-n=\"1985\">41</sup> בע\"ח בענין שאול מרחובות הנהר וכך כתיב והחכמה<sup data-n=\"1986\">42</sup> מאין (דכתר) תמצא הרי גם החכמה נק' אין עדיין להיותה",[["1982","38","<b>וכמ\"ש בזהר בכמה דוכתי' כד סליק ברעותא</b>: ראה זח\"א פו, ב. עד, א."],["1983","39","<b>לכבודי בראתיו</b>: ישעי' מג, ז."],["1984","40","<b>כידוע בענין נקודה קו שטח</b>: ראה גם ס' מאמרי אדהאמ\"צ במדבר ח\"ב ע' שלב ואילך, שלז ואילך. דרושי חתונה ח\"א ע' קכו. דברים ח\"ד ע' א'תע. וש\"נ."],["1985","41","<b>כמ\"ש בע\"ח בענין שאול מרחובות הנהר</b>: ע\"ח שער דרושי הנקודות (ש\"ח) פ\"ד. מבוא שערים ש\"ב ח\"ב פ\"ח. וראה זח\"ג קמב, א. עמק המלך שער עולם התוהו (ש\"ו) פמ\"ו (כה, א). פמ\"ח (כח, א). פנ\"א (ל, א)."],["1986","42","<b>והחכמה מאין</b>: איוב כח, יב."]]],[2101000308,"כנקודא א' בהעלם ובא לידי גלוי יש במציאות מורגש בגדר ו\"ק דבינה כידוע, ונמצא בחי' הכתר עיקר גלוי שלו במרחב הוא בבינה דוקא אבל בחכמה הוא בבחי' ההעלם עדיין רק שע\"י בחי' הנקודה דחכמה עובר השפע מכתר לבינה, ולכך נק' הרצון ע\"ש בחי' מקום שבבינה דוקא כי החכמה אינו אלא בחי' ממוצע להעביר עצם השפע לבא לידי גלוי במרחב בבינה, וסדר זה דג\"ר כח\"ב הנק' רצונו של מקום ישנו בכל עולם מד' עולמות דאבי\"ע אך כללות כולם הוא בחי' כתר דאצי' לפי שסוף מעשה דוקא עלה במחשבה תחלה, פי' סוף כל הבירורים האחרונים דנוגה דעשי' הוא אשר עלה במח' ורצון תחלה דהיינו בבחי' כתר דאצי' (וכן עד\"ז עד רום המעלות במח' דא\"ק שנק' רצון קדום שנעשה מבחי' מל' דא\"ס כו') דהיינו שעלה ברצון המאציל להיות ד' עולמות אבי\"ע בבחי' מקום וגם להיות בחי' נוגה ויתברר ויתהפך מחשוכא לנהורא כו', ובודאי בירור האחרון עלה ברצון המאציל תחלה שהרי האצי' אינו אלא בשביל הבריאה כמ\"ש אפיקת<sup data-n=\"1987\">43</sup> י' תקונין כו' לאחזאה לאתנהגא בהון עלמין בלבד כו' והבריאה בשביל היצירה והיצירה בשביל העשי' ונמצא סוף מעשה הוא עיקר הרצון, עד\"מ הרוצה לבנות בנין שעיקר הרצון הוא בנין הבא בפ\"מ ומה שמשכיל בשכלו ופועל במדותיו ובמחשבתו ודבורו כולם אינם אלא בשביל להוציא הדבר לידי פועל המעשה בלבד כו' וד\"ל.\n<b>ובכל</b> זה מובן יותר מה שאמרו דמ\"ש ואספת דגנך כו' היינו כאשר ישראל עושין רצונו של מקום דהיינו בחי' הבירורים שהמל' מברר שזה עלה במחשבה ורצון הקדום שלפני האצי' כו' והיינו פי' עושין רצונו של מקום, ופי' עושין רצונו היינו מלמעלה מבחי' גלוי הרצון כמו שאמרו יהי רצון דר\"ל מבעל הרצון יתחדש רצון אחר כך עושין רצונו שממשיכים ממקור כל הרצונות שנק' רעוא דכל רעוין, והוא ע\"י התשובה מעומקא דלבא ונק' בכל מאדך בלי גבול למעלה מן הטעם שברצון (כי כל רצון נולד מטעם הכמוס של רצון אבל במקור רצון אין טעם כלל לרצון כו') שבזה מעוררים בחי' מאד ברצון העליון שאינו בא בבחי' גבול בחכמה וטעם (גם לא בטעם כמוס שנק' ח\"ס דא\"א כידוע) והיינו ענין בכל מאדך שבפ' ראשונה שלמעלה מבחי' אה\"ר דונתתי מטר ארצכם כו' וד\"ל.\n<b>והנה</b> בזמן בהמ\"ק הי' יחוד פב\"פ בהיכל ק\"ק דבריאה דהיינו יחוד זו\"נ כמ\"ש<sup data-n=\"1988\">44</sup> בזהר בימי שלמה קיימא סיהרא באשלמותא פי' בכל קומת בנין הנוק' בע\"ס אורות וכלים הי' מאיר אור א\"ס שבז\"א דאצי', לפי שבכל יחוד עליון יש בהם הארה מעצמות אור א\"ס דהיינו מבחי' מל' דא\"ס שמאיר בפנימיות הכתר הנק' רעוא דכל רעוין והוא הנק' עושים רצונו של מקום כנ\"ל וא\"כ הי' הארה זאת תמידית מצד יחוד העליון שלא נפסק לעולם, אבל בזמן הגלות דאתתא<sup data-n=\"1989\">45</sup> אתתרכת מבעלה דהיינו ה\"א",[["1987","43","<b>אפיקת י' תקונין כו'</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."],["1988","44","<b>כמ\"ש בזהר בימי שלמה קיימא סיהרא באשלמותא</b>: זח\"א קנ, א. זח\"ב פה, א. רטו, א. ועוד. וראה שמו\"ר פט\"ו, כו."],["1989","45","<b>דאתתא אתתרכת מבעלה</b>: ראה זח\"ב רטז, ב."]]],[2101000309,"מוי\"ו כי המל' ירדה בגלות בע' שרים ובחי' ז\"א היא בבחי' שינה כמ\"ש ויקץ כישן ה' כו' כנ\"ל, וכמ\"ש בזהר<sup data-n=\"1990\">46</sup> דקוב\"ה בגלותא אסתלק לעילא כו', א\"כ א\"א שיהי' גלוי אור א\"ס בכתר מצד עצמו כ\"א מצד התעוררות התחתונים ולא בבחי' העלאת מ\"ן במצות וכיוצא שהרי המל' בגלות כו' אלא רק מצד בכי' בשפלות ומרירות שבזה מעוררים בחי' הארת רחמים רבים העליונים שבכתר שנמשך מהארת עצמות אור א\"ס.\n<b>וזהו</b> שרש ענין קול ברמה נשמע רח\"ל מבכ\"ה כו' פי' קול ברמה בבחי' פנימיות הכתר שנק' רמה כמ\"ש חנה רמ\"ה קרנ\"י (כי חנה<sup data-n=\"1991\">48</sup> בגי' ס\"ג דבינה והארת הכתר בבינה הוא מ\"ש אהי' אשר אהי'<sup data-n=\"1992\">49</sup> אנא זמין כו' והיינו מ\"ש רמה<sup data-n=\"1993\">47</sup> קרני בבחי' הכתר עצמו), והקול הזה נק' קול<sup data-n=\"1994\">50</sup> גדול ולא יסף כו', והוא פי' קול<sup data-n=\"1995\">51</sup> ברמה כמו קול<sup data-n=\"1996\">52</sup> השופר הולך וחזק כו', דהיינו מפני שמעורר בחי' קול רח\"ר שבכתר שהן נמשכים מצד עצמות אור המאציל שהוא בבחי' א\"ס ממש כידוע.\n<b>אך</b> תחלה יש להבין מהו בחי' הבכי' דרחל בזמן הגלות דוקא, כי הנה בחי' היחוד שהי' בזמן בהמ\"ק בבחי' פב\"פ העיקר הוא בחי' גלוי התענוג במוחין דאו\"א בז\"א שמלובש בשעת היחוד וכמו\"כ גלוי התענוג במוחין דנוק' כו', ובזמן הגלות נסתלקו בחי' המוחין דאו\"א מז\"א כמו בחי' שינה וממילא אין יחוד עליון כו', וכמו\"כ בחי' נוק' דז\"א שירדה למטה בגלות ורחוק<sup data-n=\"1997\">53</sup> ממנה מנחם משיב נפשה כי איננו כו' וכמבואר בספרי הקבלה, הנה בט' באב שהוא זמן חורבן בהמ\"ק שנסתלק בחי' היחוד אזי דוקא מתעורר בכנ\"י הבכי' כי אז נזכרת על בחי' התענוג העליון שביחוד. והנה ידוע דהצער הוא היפך העונג ממש לפי ערך, כי לפי הפלאת העונג כן ירבה הצער מהעדרו, כמו אשת נעורים שתתרחק מבעלה לפי ערך עומק הפלאת העונג שהיתה מקבלת ביחוד כן ירבה צערה בזכרה את בעלה, וא\"כ בשעת הצער והבכי' דוקא נתעורר כח אותו העונג לפי מה שהוא ממש ולא בעת שכחה או בעת שמחתה כו' וממילא מעורר בשעה זו גם אצל בעלה צער גדול כי רוח<sup data-n=\"1998\">54</sup> אייתי רוח כו' ובפרט בחי' התקשרות המקבל במשפיע ומשפיע במקבל שנתאחדו ממש והיו<sup data-n=\"1999\">55</sup> לבשר א' כו'. והנמשל מזה יובן למעלה בט' באב שנסתלק היחוד אז זמן זכרון היחוד העליון בכנ\"י שהוא בחי' מל' דאצי' ואז נאמר רחל מבכה על בניה כו' כי בנ\"י הן באים",[["1990","46","<b>בזהר דקוב\"ה בגלותא אסתלק לעילא</b>: ראה זח\"א רי, א. זח\"ב נח, ב. זח\"ג כ, ב. עה, א. וראה לקו\"ש חל\"א ע' 273."],["1991","48","<b>חנה בגי' ס\"ג דבינה</b>: ראה ע\"ח שכ\"ב (שער מוחין דקטנות) פ\"ב. מאמרי אדהאמ\"צ ח\"ד ע' א'תצד. וש\"נ."],["1992","49","<b>אהי' אשר אהי' אנא זמין כו'</b>: שמות ג, יד. זח\"ג סה, ב."],["1993","47","<b>רמה קרני</b>: שמואל א ב, א."],["1994","50","<b>קול גדול ולא יסף</b>: ואתחנן ה, יט."],["1995","51","<b>קול ברמה</b>: ירמי' לא, יד."],["1996","52","<b>קול השופר הולך וחזק</b>: יתרו יט, יט."],["1997","53","<b>ורחוק ממנה מנחם משיב נפשה כי איננו כו' וכמבואר בספרי הקבלה</b>: ע\"פ איכה א, טז. ירמי' לא, יד. וראה זח\"א רי, א. זח\"ב כט, ב. זח\"ג כ, ב. פע\"ח שער ר\"ח פ\"ג. ועוד."],["1998","54","<b>רוח אייתי רוח</b>: ראה זח\"ב קסב, ב. זח\"א צט, ב."],["1999","55","<b>והיו לבשר א'</b>: בראשית ב, כד."]]],[2101000310,"מיחוד העליון כו' ואז דוקא נתעורר בחי' פנימית כח העונג העליון שנמשך ביחוד עליון דז\"א, ומעורר גם במשפיע שהוא בחי' ז\"א במקור המשכת מוחין שלו שהוא נק' בחי' פנימיות ע\"י שממנו נמשך טפת אור אבא כו' כמשל הטיפה שמתהווה במוח האב וכמ\"ש כי<sup data-n=\"2000\">56</sup> אתה אבינו כו', וע\"כ אז זמן המשכת רח\"ר על כנ\"י כרחמי האב על הבן כו', והוא בחי' קול בכי' ברמה על העדר גלוי העונג שמתעורר מחמת בכי' דרחל מבכה כו', ויש התעוררות זאת בכל חצות, אך בט' באב הוא בכללות, וכל ר\"ח אלול נמשך י\"ג מדה\"ר מטעם זה עד ר\"ה ויו\"כ שנמשכים למטה ממש כנ\"ל וד\"ל, ונמצא שאותו הגלוי שהי' בזמן בהמ\"ק מצד היחוד נעשה זה הגלוי בזמן הגלות מצד ההסתר מטעם הנ\"ל, ואדרבה הרי נתעורר יותר בחי' פנימיות העונג בהעדרו מבגלוי כנראה בחוש שמתגבר כח התענוג יותר בהעדרו המנגדו, כמו אהבת אב לבן ואיש לאשתו כשנתרחקו, וכן במניעת היחוד אמרו כד<sup data-n=\"2001\">57</sup> ארי' ואריותא קיימין ווי למאן דעבר בינייהו וכמ\"ש במ\"א, וז\"ש והפכתי<sup data-n=\"2002\">58</sup> אבלם לששון וכמ\"ש במ\"א, וע\"כ נק' בחי' קול ברמה שמצד הבכי' קול גדול ולא יסף יותר מקול השופר שבמ\"ת ביחוד פב\"פ, כי בחי' ההסתר פנים מעורר בחי' פנימיות עונג יותר, ולכך אמרו כל<sup data-n=\"2003\">59</sup> שאינו בהסתר פנים כו', וז\"ש בפ' שני' דק\"ש וחרה<sup data-n=\"2004\">60</sup> אף הוי' שהוא בחי' הסתר פנים ועצר השמים ואבדתם כו' ואח\"כ ושמתם את דברי כו', כמ\"ש בצר<sup data-n=\"2005\">61</sup> לך ושבת עד ה' שהוא בחי' ובכל מאדך דתשובה שמעורר מקור י\"ג מדה\"ר וד\"ל.\n<b>ומעתה</b> יש להבין שרש ענין וכרחל<sup data-n=\"2006\">62</sup> לפני גוזזי' נאלמ\"ה. דהנה מבואר<sup data-n=\"2007\">63</sup> בע\"ח דרחל הוא בחי' מל' וגוזזי\"ה הן מקור יניקת החיצונים שמקבלים מבחי' השערות דנוק' וכמ\"ש<sup data-n=\"2008\">64</sup> בזהר ע\"פ הנה מטתו שלשלמה כו' בשערהא אחידן כו' בטופרהא אחידן כו'. והנה עד\"מ שערות גשמיים שצומחים על העור והבשר הרי העור מפסיק בין השערות לבשר ועכ\"ז עיקר יניקתם הוא מהבשר דהיינו מן הדם שבבשר שבוקע דרך נקבי הגומות שבעור (וע\"כ יש שערות אדומים ויש שערות ירוקות הכל לפי מזג הדמים וכמ\"ש<sup data-n=\"2009\">65</sup> בזהר ע\"פ ודלת ראשך כארגמן דשערות דנוק' סומקין סומקי גו סומקי כו' מפני שעיקר בנין הנוק' מבחי' הגבו' כו') וכמו\"כ יובן למעלה בבחי' יניקת הע' שרים שלא יוכלו לקבל מבחי' אור פנימיות הכלים שנק' אברים דשכינתא אלא רק מבחי' פסולת הגבורות הנדחה ובוקע דרך בחי' עור דנוק' שהוא בחי' לבוש החשמ\"ל שמלביש לזו\"נ כידוע בפי' ויעש ה' לאדם ואשתו כתנו\"ת עור כו', ולפי שמקבלים מבחי' פסולת הגבורות והצמצומים שבדם<sup data-n=\"2010\">66</sup> הוא הנפש ע\"כ",[["2000","56","<b>כי אתה אבינו</b>: ישעי' סג, טז."],["2001","57","<b>כד ארי' ואריותא קיימין</b>: ראה זח\"ג ער, א."],["2002","58","<b>והפכתי אבלם לששון וכמ\"ש במ\"א</b>: ירמי' לא, יב. ראה ד\"ה והפכתי אבלם בס' מאמרי אדה\"ז נביאים ע' ריד ואילך, ובמ\"מ לשם."],["2003","59","<b>כל שאינו בהסתר פנים</b>: חגיגה ה, א."],["2004","60","<b>וחרה אף הוי'</b>: עקב יא, יז."],["2005","61","<b>בצר לך ושבת עד ה'</b>: ע\"פ ואתחנן ד, ל."],["2006","62","<b>וכרחל לפני גוזזי' נאלמ\"ה</b>: ישעי' נג, ז."],["2007","63","<b>מבואר בע\"ח דרחל הוא בחי' מל'</b>: ראה ע\"ח שער פרצופי זו\"ן (של\"א) פ\"א."],["2008","64","<b>וכמ\"ש בזהר ע\"פ הנה מטתו שלשלמה כו' בשערהא אחידן כו'</b>: זח\"ג ס, ב."],["2009","65","<b>וכמ\"ש בזהר ע\"פ ודלת ראשך כארגמן</b>: שה\"ש ז, ו. זח\"ג קמד, ב. וראה שם קלו, ב."],["2010","66","<b>שבדם הוא הנפש</b>: פ' ראה יב, כג."]]],[2101000311,"עיקר יניקתם מבחי' שערות שנמשכים וצומחים רק מבחי' פסולת דמים, וגם זאת הן יוצאין בבחי' צמצומים גדולים, מלבד שהן באים רק מבחי' המותרות והפסולת הרי הן נמשכים כאו\"א רק דרך גומא קטנה שממנה יונקת עיקר השערה ונמשך תוך חללה והוא מצומצם מאד (וכמארז\"ל<sup data-n=\"2011\">67</sup> ע\"פ בסערה כו' בין טפה לטפה ובין שערה לשערה לא נתחלף לי כו', כי כל שערה יש לה גומא בפ\"ע כו'), ונמצא ששרש יניקה זו מתחלת מפסולת ומותרות הדם שבבשר (וכן ממותרי המוחין שבראש צומחים שערות שבראש כידוע) אך בנקבי העור דחשמ\"ל בוקע הארה מצומצמת הזאת ומסתיימת בסוף השערה, והנה הגם שעור מפסיק בין השרש של יניקת השערה לסופה מ\"מ ע\"י חיבור העור בבשר והשערות מושרשים בעור בגומות הן הרי המה טפלים לעור ובשר ונאחזין ונגררין אחר שרשיהן בבשר ואינם בחי' נפרד כלל בפ\"ע (שהרי כשימשוך השערה יכאוב לבשר אך כשגוזז אינו מרגיש כאב בבשר לפי שגוזז את השערה בלבד ואין נוגע כלל בעיקר יניקתה בגומא שבתוך הבשר והעור, ונמצא הפרש גדול בין גוף השערה לעיקר שרשה בגומא שבתוך העור והבשר, שעיקר שרשה יש לה שייכות עם עצם הבשר והעור עד שירגיש כאב כשמושך השערה מחמת שנוגע בגומא כנ\"ל אבל לגוף השערה אין לה שייכות כלל עם הבשר וע\"כ לא ירגיש כאב כלל בגזיזה).\n<b>והנמשל</b> מכ\"ז יובן למעלה בבחי' שערות דעור דנוק' דז\"א יש בהן ב' מדריגות הא' עיקר שרשם בגומא כו' והב' גוף השערות והיינו יודי\"ן ווי\"ן כי הגומא שבתוך הבשר והעור הוא כמו יו\"ד שבראש הוי\"ו וגוף השערה הוא רגל הוי\"ו שנמשך מראשו והולך ומתקצר (וכמ\"ש<sup data-n=\"2012\">68</sup> בע\"ח בענין קדש יהי' גדל כו' בשערות דראש' ממותרי מוחין סתימאה שהן כמו ווי\"ן והיינו בווי\"ן<sup data-n=\"2013\">69</sup> תתקטר), ובחי' עור דחשמל מפסיק לחלק לחלקים מצומצמים בריבוי נקבים וגומות שבעור שבוקעין לחוץ, והנה כאשר בחי' השערות מחוברים בשרשן שהן יודי\"ן שבתוך הכלים דע\"ס יש להם שייכות ויחוד קצת בכלים דע\"ס דנוק' (עד\"מ שמרגיש כאב בהמשך השערה) אך כשגוזזין אותן נעשים נפרדין מעיקרי שרשיהן ואין להם שייכות ויחוד כלל עם העור והבשר שנק' כלים ואברים ואז הע' שרים שמקבלים מבחי' השערות הנגזזין נק' בחי' נפרד לגמרי כמו שר של מצרים שאמר לי<sup data-n=\"2014\">70</sup> יאורי כו' או ידינו רמה וכיוצא, אמנם בחי' גזיזה זאת הוא ירידה גדולה להן להפרידן משרשן כי בודאי הרבה חיות ואור יונקת השערה בעודנה מחוברת בעור ובשר שיונקת תמיד מחיות ואור בבשר משא\"כ כשנגזזו לא יומשך עוד חיות בהן רק מה שכבר נמשך בהן, כי בחלק החי גם בחי' הצומח שבו יקרא ע\"ש בחי' החי להיותם צומחים מן החי, ואין לצומח שצומח מן הדומם כתבואה ערוך לו כלל, וכמו\"כ ודאי אין ערוך לצמיחת קרן הבהמה לצמיחת שער הזקן באדם ששער הזקן הוא בחי' צומח שבמדבר וקרן",[["2011","67","<b>וכמארז\"ל ע\"פ בסערה</b>: ב\"ב טז, א."],["2012","68","<b>וכמ\"ש בע\"ח בענין קדש יהי' גדל</b>: ראה גם לקו\"ת (טעהמ\"צ) פ' בהר מצות נזיר. תו\"ח חיי\"ש קכג, ד."],["2013","69","<b>בווי\"ן תתקטר</b>: פיוט אזמר בשבחין, סעודת ליל שבת."],["2014","70","<b>לי יאורי. . ידינו רמה</b>: יחזקאל כט, ג. האזינו לב, כז."]]],[2101000312,"הבהמה הוא צומח שבחי (ובודאי גם בצומח<sup data-n=\"2015\">71</sup> שבחי יש הפרש בין אדם לבהמה כי חי שבאדם הוא חי שבמדבר כו'). ונמצא ב' דברים יש במעלת השערות המחוברות על השערות הגזוזות, הא' שמחוברים הן צומח שבחי כנ\"ל, והב' מה שיצמחו עוד ואינו נק' בחי' דומם משא\"כ הגזוזות לא יצמחו עוד ונעשים בחי' דומם (אלא ששער אדם הגזוז נק' דומם שבאדם כו' (ובזה יובן מ\"ש בזה\"ק<sup data-n=\"2016\">72</sup> ע\"פ ביום ההוא יגלח ה' בתער השכירה במלך אשור בזקן כו' וכמוזכר בדברי רז\"ל בפ' חלק שהוא להפריד את תוס' יניקת החיצונים מהקדושה העליונה כו') וע\"ד טעם גילוח הלוים להיות שרשם מבחי' הגבורות והשערות מוסיפים גבורות קשות מטעם הנ\"ל כך מלך אשור צריך גילוח להיותו מלא גבורות קשות ולא יחריב את העולם כו' וד\"ל).\n<b>וזהו</b> שרש ענין כרחל לפני גוזזיה בזמן הגלות דוקא, דהנה בזמן הגלות בחי' המל'<sup data-n=\"2017\">73</sup> מלאה גבורות כמאמרז\"ל כאשה עוברה כו'<sup data-n=\"2018\">74</sup> ואז אם הי' יניקת הע' שרים משערות המחוברים הי' נמשך להם גבורות קשות לרוב והיו מחריבין העולם, אבל כשהן מקבלים מהשערות הנגזזות אינם מקבלים רק בצמצום וגבול שכבר נמשך בהן כי הרי נפרדין לגמרי מעיקרי השרשים של השערות ונעשים בחי' דומם בלבד כנ\"ל, ואעפ\"י שבזה נעשים נפרדים יותר מטעם הנ\"ל מ\"מ לא נמשך להן עוד, והגוזזים את בחי' שערות דנוק' הן בחי' שמים<sup data-n=\"2019\">75</sup> עליונים כמו תער הנז' בלוים שהוא בחי' גבורות דשם ב\"ן כו' (כמ\"ש במ\"א) וכמשל שערות האדם שכבדים עליו מגלחם כו', משא\"כ בזמן בהמ\"ק מפני שהמל' היתה מלאה חסדים עליונים מבחי' יחוד עליון דזו\"נ פב\"פ תמיד כמ\"ש בזוהר דבימי שלמה קיימא סיהרא שהוא המל' באשלמותא בכל קומת בנינה הי' אור החסדים דז\"א ואו\"א כו' מאירים בה עד שגם בחי' התפשטות אור המל' בבי\"ע הי' מאיר מאותו האור וכמו זמן מלוי הלבנה שאז עת רצון כו' ע\"כ אף שהי' יניקה לחיצוני' ג\"כ מבחי' השערות דנוק' מבחי' עור החשמ\"ל כנ\"ל היו גם הם בבחי' הביטול לקדושה העליונה, אך לא בתכלית השלימות כמו לעתיד, שהרי כל האומות היו נכנעים תחת מלכות שלמה ומביאין לו מנחה ודורון, וכל החכמים שבגוים היו באים לשמוע חכמת שלמה כו', וכן בזמן חזקיהו הי' מעין מעלה זאת, וע\"כ יכלו כל הע' שרים לקבל אז גם מבחי' הפנימית של השערות ולא היו מחריבין את העולם אלא אדרבה נתוסף בהן בחי' ביטול יותר כמו משל שערות שבגוף שנגררים ובטלים לגבי אברים לגמרי כנ\"ל, משא\"כ בזמן הגלות כתיב כרחל לפני גוזזי' דוקא מטעם הנ\"ל וד\"ל.\n<b>אך</b> עדיין יש להבין מהו שאמר לפני גוזזי' נאלמ\"ה מהו ענין אלמת זאת. אך הנה יש להקדים מ\"ש למען<sup data-n=\"2020\">76</sup> יזמרך כבוד כו' שהוא בחי' עליות המל' שנק' כבוד",[["2015","71","<b>בצומח</b>: כ\"ה בכת\"י המעתיק, ואוצ\"ל: בחי."],["2016","72","<b>בזה\"ק ע\"פ ביום ההוא יגלח. . וכמוזכר בדברי רז\"ל בפ' חלק</b>: ישעי' ז, כ. זח\"ג מט, א. סנהדרין צה, ב. וראה ס' מאמרי אדה\"ז נביאים ע' מג ואילך, ובמ\"מ שם."],["2017","73","<b>המל' מלאה גבורות</b>: ראה סידור עם דא\"ח מא, א. ס' מאמרי אדהאמ\"צ דברים ח\"א ע' ריח. וש\"נ."],["2018","74","<b>כמארז\"ל כאשה עוברה כו'</b>: ברכות כט, ב."],["2019","75","<b>שמים עליונים</b>: כ\"ה בכת\"י המעתיק."],["2020","76","<b>למען יזמרך כבוד</b>: תהלים ל, יג."]]],[2101000313,"בשיר וזמרה כו' וכמ\"ש<sup data-n=\"2021\">77</sup> בזהר בפי' אלקים אל דמי לך כידוע, ולכאורה אין לזה הבנה דאיך שייך בחי' שיר וזמרה בבחי' מל' שנחשבת מי' ספירות ואיהו<sup data-n=\"2022\">78</sup> וחיוהי חד כידוע ולמען יזמרך משמע שמזמרת לפני ה' כו'. אך הענין הוא דאין בחי' שיר שייך רק בבחי' הכלים ולא בבחי' האורות. והענין הוא משום דעיקר בחי' שיר הוא בחי' ההעלאה של העלול בעילה שלו כמ\"ש במ\"א<sup data-n=\"2023\">79</sup> בענין שירה של המלאכים כמ\"ש במשנה בעלי השיר יוצאין בשיר כו' שהוא בחי' ביטול היש לאין כו', אך כל בחי' עילה ועלול אינו אלא בבחי' הכלים ולא בבחי' האורות, ולא<sup data-n=\"2024\">80</sup> כדעת הפרד\"ס שגם באורות יש בחי' עילה ועלול כמבואר בשער עצמות וכלים, שהרי כל עיקר בחי' התהוות עלול מעילה אינו אלא ע\"י אמצעי' הכלים דוקא, כמו התהוות השכל מן המשכיל אינו אלא מבחי' הכלי שלו, דהיינו כאשר יש בחי' כלי וחומר הנושא לצורת כח המשכיל אזי נמשך התהוות שכליים וסברות רבות מכח המשכיל, וכן מן השכל שבמוח דוקא מתהווה התפעלות המדות דהיינו רק מבחי' כלי המוח, אבל כאשר האורות בלתי כלים כמו בכחות הכלולים בעצמות הנפש א\"א לומר שיתהווה שם השכל מכח השכל אלא כלולים זב\"ז ומתאחדים כולם בנפש כו', וכך יובן למעלה דבבחי' האורות העליונים מצד עצמן הן כלולים במאציל בתכלית האחדות הפשוטה וא\"א לומר בהן בחי' השתלשלות עילה ועלול ושהעלול יוכלל בעילתו, רק כשבאים בהתלבשות בבחי' כלים כמו חכמה<sup data-n=\"2025\">81</sup> מוחא קרקפתא כתר חסד דרועא כו', כמו שאנו רואים בחוש שעליית המדות בשכל והשכל למעלה מן השכל אינו [אלא] דרך אמצעי' הכלי ולא בבחי' האורות, והשינה תוכיח שהמדות והשכל עולים כ\"א בעצמות הנפש כו' וד\"ל. וא\"כ מ\"ש למען יזמרך כבוד כו' הוא בבחי' הכלים דע\"ס דמל', דהיינו בחי' למ\"ד כלים דמל' שמתלבשים בבי\"ע, י' כלים הפנימי' בבריאה וי' האמצעי' ביצירה כו', אבל בבחי' האורות א\"א לומר בחי' שיר וזמרה שהוא בחי' עליית העלול בעילתו אחר שאין העלול נפרד שם מעילתו כלל כנ\"ל וד\"ל.\n<b>והנה</b> בזמן בהמ\"ק נאמר למען יזמרך כבוד ולא ידום וכן אלקים אל דמי לך כו' שהוא בחי' מל' דאצי' שעולה למעלה באצי' תמיד בבחי' שיר וזמרה שהוא בחי' עליות והתכללות העלול בעילתו כו' ואעפ\"י שאין זה רק בבחי' הכלים דמל' דאצי' ולא בבחי' האורות כנ\"ל, אבל בזמן בהמ\"ק הוה קיימא סיהרא באשלמותא",[["2021","77","<b>וכמ\"ש בזהר בפי' אלקים אל דמי לך כידוע</b>: ראה זח\"ב רנו, ב. קמ, א. ועוד."],["2022","78","<b>ואיהו וחיוהי חד כידוע</b>: תקו\"ז בהקדמה (ג, ב)."],["2023","79","<b>במ\"א בענין שירה של המלאכים כמ\"ש במשנה בעלי השיר יוצאין בשיר</b>: שבת נא, ב. וראה תו\"א ז, ג. קיג, א. לקו\"ת ברכה צח, א. סידור עם דא\"ח ערה, ב. תו\"ח בראשית לד, ד. ובמ\"מ שם."],["2024","80","<b>ולא כדעת הפרד\"ס שגם באורות יש עילה ועלול</b>: ראה גם בהגהות לד\"ה פתח אליהו תרנ\"ח ע' ס, וסה\"מ תרס\"ה ע' רעג. (בשני מקומות הנ\"ל מבואר שגם לשיטת הפרדס ענין עילה ועלול הוא רק בהכלים ולא באורות, ועי' במובא בליקוט פירושים לתניא (חיטריק) אגה\"ק ס\"כ, ע' שצו ואילך. ובמאמר כאן כנראה קאי לאופן הביאור בשיטת הפרדס שגם האורות הם בציור ואינם אחדות פשוטה, ראה לעיל בס' זה ע' רלו, אוה\"ת על מארז\"ל וענינים ע' רסג, המשך תרס\"ו ע' קסב, ובמובא בס' הערכים חב\"ד כרך ד' ע' קז)."],["2025","81","<b>חכמה מוחא קרקפתא כתר חסד דרועא</b>: תקו\"ז בהקדמה ד\"ה פתח אליהו."]]],[2101000314,"באורות וכלים ג\"כ כנ\"ל והי' בחי' הביטול דעלול בעילתו בבחי' הכלים ג\"כ מפני תוקף האור בבחי' יחוד עליון שבבחי' האורות דזו\"נ, אבל בזמן הגלות שלמ\"ד כלים דמל' דאצי' יורדים ומתלבשים בהעלם אחר העלם בירידת המדריגות עד שמסתתר בתכלית ההסתר והצמצום בע' שרים דנוגה דעשי' אז אין בחי' שיר ועלי' בכלים דמל' דאצי' כמו בזמן בהמ\"ק (וכידוע<sup data-n=\"2026\">82</sup> מענין שיר השירים דשלמה שלא ניתנה רק בזמן בנין בהמ\"ק שהיתה בחי' שמחה גדולה למעלה כמ\"ש ביום חתונתו כו' וכמ\"ש במ\"א וד\"ל) אלא אדרבה כתיב כרחל לפני גוזזיה נאלמה בחי' אלם שהוא צמצום הדיבור (והוא אותיות אלם מאלקים שהוא בחי' הקטנות שבמל' כו'). ומ\"ש לפני גוזזיה דוקא נאלמה, היינו כמ\"ש נאלמתי<sup data-n=\"2027\">83</sup> דומי' כו' דהיינו כשמתקבצים במל' בחי' הדינים והצמצומים בבחי' השערות שלה שהן סומקי גו סומקי<sup data-n=\"2028\">84</sup> כו' אזי כתיב נאלמתי דומי' שנתעלם כח הדיבור שהוא מפני בחי' צמצום המוחין והסתלקות מן הדיבור כדי שיוכל להיות צמצום גמור שהן בחי' הגבורות שנק' גוזזיה כדי שעי\"ז יומשך יניקה לע' שרים להפרידן מהקדושה כנ\"ל וז\"ש כרחל לפני גוזזיה דוקא נאלמה וד\"ל.\n<b>ואחר</b> כל הנ\"ל יובן שורש ענין הנ\"ל בשני מאמרי רז\"ל ע\"פ ואספת דגנך דסתרי אהדדי לכאורה כנ\"ל, דהנה ג' מדריגות יש, הא' מ\"ש ולקחתי דגני כו' שהוא מדבר כשאין ישראל עושין רצונו של מקום כו' כנ\"ל, והב' מ\"ש ואספת דגנך עכשיו בזמן הבירור שהוא בזמן שישראל עושין רצונו של מקום, והג' מ\"ש ועמדו זרים כו' לעתיד דלאחר הבירור כו' (ומ\"ש ואספת דגנך עכשיו יהי' לעתיד נחשב בבחי' אין עושין רצונו של מקום כנ\"ל). וביאור ג' אלה המדריגות הנה יובן עפ\"י הנ\"ל דבחי' הבירורים זהו שעלה בעיקר הרצון העליון ונק' רצונו של מקום בכל עולם ועולם עד רום המעלות, והנה מ\"ש ולקחתי דגני היינו כשאין ישראל מבררים בירורים בהעלאת רפ\"ח כלל כי אין בידם תשומע\"ט אז נק' דגני ולא דגנך והיינו כשאין ישראל עושין רצונו של מקום, אבל כשישראל מבררים ומעלים כל הניצוצות שנפלו כו' ומהפכים חשוכא לנהורא כו' אז נאמר ואספת דגנך והיינו כשישראל עושים רצונו של מקום, אבל לעתיד הנה לא יצטרכו לברר בירורים דרפ\"ח כו' כי הכל יבורר וכמ\"ש ואת<sup data-n=\"2029\">85</sup> רוח הטומאה אעביר כו' אז נאמר ועמדו זרים ורעו צאנכם כו' שלא יצטרכו בעצמם לעבוד עבודה כלל ואז לא יקרא עושין רצונו של מקום בעבודת הבירורים כלל אחר שכבר נברר הכל אלא יקרא עושין רצונו של מקום במעלה ומדריגה יתירה הרבה מבחי' עושין רצונו של מקום שבעבודת הבירורים בזמן הגלות כנ\"ל. דהנה מה שמבואר למעלה בפי' ואספת דגנך שהוא לברר בירורים היינו ע\"י בחי' שם מ\"ה דתיקון שמברר לבחי' ב\"ן שנפל בעולם הבריאה כי בחכמה<sup data-n=\"2030\">86</sup> אתברירו דוקא כידוע, ואמנם הנה שם מ\"ה יהי' לעתיד למטה משם ב\"ן",[["2026","82","<b>וכידוע מענין שיר השירים דשלמה. . כמ\"ש ביום חתונתו כו'</b>: ראה זח\"ב קמג, א. ועוד. שה\"ש ג, יא."],["2027","83","<b>נאלמתי דומי'</b>: תהלים לט, ג."],["2028","84","<b>סומקי גו סומקי</b>: ראה בנסמן לעיל ע' ערב."],["2029","85","<b>ואת רוח הטומאה אעביר</b>: זכרי' יג, ב."],["2030","86","<b>בחכמה אתברירו</b>: ראה זח\"ב רנד, ב. וראה במ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' רצה."]]],[2101000315,"כמ\"ש אשת<sup data-n=\"2031\">87</sup> חיל שהוא שם ב\"ן לאחר הבירור עטרת לבעלה שם מ\"ה כי תעלה לשרשה בבחי' ס\"ג דתוהו שלפני מ\"ה דתיקון, כי הנה בחי' הכלים דתוהו הוא שנפלו ונשברו כידוע<sup data-n=\"2032\">88</sup> בע\"ח שמפני תוקף האור דתוהו לא יכול הכלי לסובלו ונשבר הכלי ונפל למטה ומבואר דבר זה במ\"א, אבל בחי' האורות דתוהו נסתלקו ועלו למעלה בעצמות המאציל ולא שייך לומר בהן שבירה ונפילה כלל, והנה עיקר הבירור הוא לאהפכא חשוכא לנהורא כו' שהוא להעלות לבחי' הכלים דתוהו שנפלו למטה ולאחר הבירור הרי עולים בחי' הכלים דתוהו לשרשם שהוא בחי' שם ב\"ן דז' מלכים דתוהו שהן ב\"ן דס\"ג כידוע והן גבוהים גם מבחי' האורות דתיקון כמ\"ש ואלה<sup data-n=\"2033\">89</sup> המלכים אשר מלכו כו' לפני מלוך מלך לבנ\"י וכל מלוכה הוא בחי' ב\"ן, וגם הן היו לפני בחי' האורות דתיקון שנק' ישראל כידוע, וא\"כ מה שיקרא לעתיד בשם עושין רצונו של מקום היינו שיומשך בחי' אורות דתהו שכבר נסתלקו ועלו למעלה מעלה, שירדו למטה ויתלבשו בבחי' הכלים שלהם שעלו מן הבירור ע\"י התיקון דשם מ\"ה כנ\"ל, וידוע<sup data-n=\"2034\">90</sup> בע\"ח דבחי' אורות דתהו הן בחי' י' כתרים בלבד שנק' י' נקודות ולכך נק' הם בשם רצונו של מקום כי הכתר הוא בחי' מקיף כו', ונמצא הרי בחי' רצונו של מקום שבהמשכת הי' כתרים דתוהו לבחי' הכלים גבוה הרבה מבחי' רצונו של מקום שבבירורים שהוא רק בבחי' האורות דש' מ\"ה דתיקון שהן למטה גם מבחי' הכלים דתוהו כנ\"ל, וזהו שורש הטעם לזה שאמרו לעתיד דקרא ואספת דגנך נק' אין עושין רצונו של מקום לגבי בחי' רצונו של מקום שיהי' לעתיד בהמשכת אורות הכתרים דתהו אבל עכשיו קרא דואספת דגנך בעבודת הבירורים רצונו של מקום, ושני המאמרים אמת ולא סתרי אהדדי כלל דזה מדבר עכשיו וזה מדבר לעתיד כנ\"ל וד\"ל.\n<b>ובכל</b> הנ\"ל יובן מה שבפ' ראשונה דק\"ש אמר ושננתם<sup data-n=\"2035\">91</sup> לבניך תחלה ואח\"כ וקשרתם לאות ובפ' שני' אמר בהיפוך דמצות קודמים לתורה והזכיר וקשרתם<sup data-n=\"2036\">92</sup> קודם ולמדתם כו', כי הנה תחלה יש להבין שורש התורה והמצות דהנה אורייתא<sup data-n=\"2037\">93</sup> מחכמה עילאה נפקת ולכאורה אין זה מובן דהרי עיקר התורה הוא בחי' המדות טמא וטהור כשר פסול כו' כמו כל דינין שבתושב\"כ במ\"ע ומל\"ת הכל אינו אלא בחי' מדות זה יכשר וזה יפסל, זה טמא לא יאכל כו' כמ\"ש להבדיל<sup data-n=\"2038\">94</sup> בין הטמא לטהור כו'. אך הענין הוא דשרש תשב\"כ הוא בחי' ו\"ק דז\"א, ואמנם נמשך בו\"ק דז\"א מהארת אור אבא שהוא בחי' החכמה והטעם לכל דין והלכה שבתורה שבע\"פ למה זה יטמא ויפסל ולמה זה יטהר כמו מ\"ט דר' פלוני כו', כידוע",[["2031","87","<b>אשת חיל</b>: משלי יב, ד."],["2032","88","<b>כידוע בע\"ח שמפני תוקף האור דתוהו</b>: ראה ע\"ח שער המלכים (שי\"א) פ\"א. וראה מאמרי אדהאמ\"צ קונטרסים ע' שס. וש\"נ."],["2033","89","<b>ואלה המלכים אשר מלכו</b>: וישלח לו, לא."],["2034","90","<b>וידוע בע\"ח דבחי' אורות דתהו הן בחי' י' כתרים בלבד</b>: ראה בארוכה תו\"ח בראשית ט, א ובהמ\"מ שם."],["2035","91","<b>ושננתם לבניך. . וקשרתם לאות</b>: ואתחנן ו, ז-ח."],["2036","92","<b>וקשרתם קודם ולמדתם</b>: עקב יא, יח-יט."],["2037","93","<b>אורייתא מחכמה עילאה נפקת</b>: זח\"ב סב, א. פה, א. קכא, א. ועוד."],["2038","94","<b>להבדיל בין הטמא לטהור</b>: שמיני יא, מז."]]],[2101000316,"שהתלמוד<sup data-n=\"2039\">95</sup> בבריאה בבחי' הטעמים כו', ושרש החכמה דאצי' הוא בבחי' הח\"ס דא\"א שנק' חכמה נעלמה שהוא בחי' טעם כמוס לרצון שבמצוה כו', אבל הנה המצוה עצמה היא רצון בלתי טעם כלומר למעלה גם מטעם כמוס כו', אך הנה בזמן הגלות המצות הן למטה מן התורה דהיינו שהמצות מקבלים מן התורה כי<sup data-n=\"2040\">96</sup> המצוה נק' מצות המלך שהוא ציווי המלך בלתי ידיעת טעם לצווי ואינו אלא קבלת עומ\"ש בלי טעם, והיינו מפני שבזמן הגלות המל' מקבלת מז\"א וע\"כ מצות שנק' מצות המלך מלכות דאצי' מקבלי' מו\"ק דז\"א דתושב\"כ דאור אבא מאיר שם כנ\"ל. ולכך נאמר בפ' שני' וקשרתם תחלה שהוא כללות המצות שהוקשו לתפילין ואח\"כ ולמדתם כו' כי מזכיר את הנמוך ואח\"כ את הגבוה כסדרן מלמטה למעלה בסדר המדריגות שעולים זה למעלה מזה והמצות שרשן בבחי' מל' מזכיר תחלה ואח\"כ א' ולמדתם שהוא התורה שהוא בבחי' ז\"א, כי פרשה והי' א\"ש מדבר בזמן הגלות כמ\"ש וסרתם ואבדתם כו', אבל הנה לע\"ל כתיב אשת חיל עט\"ב כנ\"ל דבחי' המל' לאחר הבירור תעלה למעלה מבחי' שם מ\"ה דז\"א שנק' בעלה לפי שתעלה לבחי' ס\"ג דבינה ובבחי' בינה מאיר שם אהי' דכתר כמ\"ש אהי'<sup data-n=\"2041\">97</sup> אשר אהי' כידוע, והיינו בחי' עלי' שלישית דמל' שתעלה לבחי' הכתר דא\"א שלמעלה גם מבחי' ח\"ס דא\"א, והיינו ענין שורש המצות למעלה שהן למעלה גם מבחי' טעם כמוס לרצון אלא רצון פשוט בלתי טעם ותענוג גלוי לרצון (והיינו בחי' י\"ג<sup data-n=\"2042\">98</sup> חוורתי שבגולגלתא דא\"א שהוא בחי' עונג העליון הנעלם שלמעלה מבחי' גלוי העונג שבח\"ס כנ\"ל וד\"ל) ואז יהי' שורש המצות גבוה משורש התורה ותקבל התורה מן המצות כו' וע\"כ מזכיר בפ' ראשונה מצות ת\"ת קודם ואח\"כ וקשרתם כו' שהן המצות דהיינו כסדר עליות המדריגות מלמטה למעלה כנ\"ל לפי שהמצות יהיו גבוהים לעתיד יותר מן התורה מטעם הנ\"ל ופ' ראשונה מדבר לעתיד כמשמעות לשון ואהבת שעתיד לאהוב ואז יהיו הדברים האלה כו' וע\"כ לא נזכר ואספת דגנך בפ' ראשונה לפי שבחי' הבירורים לא יצטרכו לעתיד כנ\"ל ומה שנק' רצונו של מקום יהי' לעתיד בבחי' המשכת אורות מקיפים דתהו שהן למעלה מבחי' התיקון כנ\"ל, וע\"כ נזכר בכל מאדך בפ' ראשונה שהוא בחי' מקיף דכתרי' דתוהו ולא נזכר בכל מאדך בפ' שני' לפי שבפרשה שני' מדבר עכשיו בזמן הבירורים שהוא ואספת כו' והן מעשה המצות ג\"כ שמקבלים מחכמה שבתורה שהוא שם מ\"ה דז\"א דתיקון כנ\"ל ואספת דגנך נז' בפ' שני' ולא בפ' ראשונה והכל מטעם א' הנ\"ל וד\"ל.\n<b>ובזה</b> יובן ג\"כ שורש ענין תפילין דרש\"י ותפילין דר\"ת דהנה ידוע בפע\"ח בשער התפילין דרש\"י ד' פרשיות כסדרן קדש והי' כי יביאך שמע והי' א\"ש היינו חו\"ב ת\"ת ומל' שהן או\"א זו\"נ והוא כסדר אותיות דשם הוי' יו\"ד באור אבא ה'",[["2039","95","<b>שהתלמוד בבריאה</b>: פע\"ח שער הנהגת הלימוד (שי\"ז)."],["2040","96","<b>כי המצוה נק' מצות המלך</b>: ל' הפסוק אסתר ג, ג. וראה בהמ\"מ בס' מאמרי אדהאמ\"צ שמות ח\"א ע' יא."],["2041","97","<b>אהי' אשר אהי' כידוע</b>: ראה זח\"א יא, א. ובמ\"מ בס' מאמרי אדהאמ\"צ דברים ח\"א ע' רכו."],["2042","98","<b>י\"ג חוורתי שבגולגלתא דא\"א</b>: ראה זח\"ג קכח, ב."]]]]});
